INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1160, 27, 'TEXT', 'The ratio of Sana''s age 4 years ago to Ryan''s age 4 years hence is 1:1. Sana is now 28. How old is Ryan now?', NULL, '["16","24","20","22"]', '20', NULL, 'HARD', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-11T13:34:25.213Z') ON CONFLICT DO NOTHING;
