INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1166, 27, 'TEXT', 'A man''s age is the square of his son''s. In 3 years, it will be 5 times the son''s age then. How old is the son now?', NULL, '["2","4","3","5"]', '3', NULL, 'HARD', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-11T13:34:25.213Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1168, 27, 'TEXT', 'Fifteen years from now, A will be 5/3 of B''s age. Fifteen years ago, A was 1/3 of B''s age. How old is A now?', NULL, '["15","25","20","30"]', '20', NULL, 'HARD', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-11T13:34:25.213Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1170, 27, 'TEXT', 'A mother is 3 times her daughter''s age. 6 years later, the mother will be (10/4) times her daughter''s age. How old is the daughter now?', NULL, '["6","10","8","12"]', '8', NULL, 'HARD', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-11T13:34:25.213Z') ON CONFLICT DO NOTHING;
