INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1165, 27, 'TEXT', 'The ages of Raj, Sam, and Tim are in AP (arithmetic progression) with common difference 3. Sam is 15 years old. In 5 years, what will be the sum of all three ages?', NULL, '["54","51","57","60"]', '54', NULL, 'HARD', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:21:01.383Z') ON CONFLICT DO NOTHING;
