INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1169, 27, 'TEXT', 'The ratio of ages of A and B is 3:5. Sum of ages 10 years hence will be 80. How old is B now?', NULL, '["35","30","20","25"]', '30', NULL, 'HARD', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:21:01.383Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1173, 27, 'TEXT', 'In 20 years, a son will be half his father''s age. 20 years ago, the father was 6 times the son''s age. How old is the son now?', NULL, '["10","15","25","20"]', '20', NULL, 'HARD', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:21:01.383Z') ON CONFLICT DO NOTHING;
