INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1198, 28, 'TEXT', 'A trader sells 240 kg of rice at a profit equal to the selling price of 40 kg. What is the profit percentage?', NULL, '["15%","25%","20%","18%"]', '20%', NULL, 'HARD', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-11T13:34:25.213Z') ON CONFLICT DO NOTHING;
