INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1201, 29, 'TEXT', 'What number is represented by these tally marks? IIII/ IIII/ I I I I', NULL, '["19","15","14","13"]', '14', NULL, 'EASY', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-11T13:34:25.213Z') ON CONFLICT DO NOTHING;
