INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4099, 17, 'TEXT', 'A number n when divided by 8 leaves a remainder of 4. What is the remainder when 3n is divided by 8?', NULL, '["7","4","5","6"]', '4', 'The remainder of 3n modulo 8 is equivalent to (3 × 4) modulo 8 = 4.', 'HARD', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:20:40.670Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4083, 17, 'TEXT', 'Eggs are packed in cartons of 4. If a farmer has 142 eggs, how many eggs will be leftover after packing full cartons?', NULL, '["3","0","1","2"]', '2', '142 ÷ 4 leaves a remainder of 2.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:20:40.670Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4089, 17, 'TEXT', 'A number n when divided by 4 leaves a remainder of 0. What is the remainder when 3n is divided by 4?', NULL, '["1","2","0","3"]', '0', 'The remainder of 3n modulo 4 is equivalent to (3 × 0) modulo 4 = 0.', 'HARD', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:20:40.670Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4101, 17, 'TEXT', 'A number n when divided by 7 leaves a remainder of 1. What is the remainder when 3n is divided by 7?', NULL, '["4","6","5","3"]', '3', 'The remainder of 3n modulo 7 is equivalent to (3 × 1) modulo 7 = 3.', 'HARD', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:20:40.671Z') ON CONFLICT DO NOTHING;
