INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5271, 10, 'TEXT', 'An item originally priced at £120 is reduced by 1/4, and then reduced further by 30%. What is the final price?', NULL, '["£63.00","£73.00","£90.00","£58.00"]', '£63.00', 'Reducing by 1/4 means the price is £120 × 3/4 = £90. Reducing this by 30% means the final price is £90 × 70% = £63.00.', 'HARD', 1, TRUE, '2026-07-11T13:34:31.832Z', '2026-07-11T13:34:31.832Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5272, 10, 'TEXT', 'Calculate: (4/5 × 3/4) + 0.15. Express the final value as a percentage.', NULL, '["112.5%","75%","80%","65%"]', '75%', '(4/5 × 3/4) = 12/20 = 0.6. Adding 0.15 gives 0.6 + 0.15 = 0.75. As a percentage, this is 75%.', 'HARD', 1, TRUE, '2026-07-11T13:34:31.832Z', '2026-07-11T13:34:31.832Z') ON CONFLICT DO NOTHING;
