INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5279, 10, 'TEXT', 'Evaluate: 60% of 80 + 0.30 of 200 - 1/4 of 40', NULL, '["102","108","93","98"]', '98', '60% of 80 = 48. 0.30 of 200 = 60. 1/4 of 40 = 10. Combining gives 48 + 60 - 10 = 98.', 'HARD', 1, TRUE, '2026-07-11T13:34:31.832Z', '2026-07-18T06:20:53.296Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (12122, 61, 'TEXT', 'A bag contains 7 yellow, 8 green, 3 red counters. One counter is picked at random. What is the probability it is yellow?', NULL, '["7/18"]', '7/18', NULL, 'EASY', 1, TRUE, '2026-07-13T11:32:39.203Z', '2026-07-18T06:27:43.865Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5288, 10, 'TEXT', 'Evaluate: 50% of 80 + 0.25 of 200 - 1/4 of 40', NULL, '["75","84","90","80"]', '80', '50% of 80 = 40. 0.25 of 200 = 50. 1/4 of 40 = 10. Combining gives 40 + 50 - 10 = 80.', 'HARD', 1, TRUE, '2026-07-11T13:34:31.832Z', '2026-07-11T13:34:31.832Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5289, 10, 'TEXT', 'An item originally priced at £120 is reduced by 1/4, and then reduced further by 60%. What is the final price?', NULL, '["£31.00","£46.00","£36.00","£90.00"]', '£36.00', 'Reducing by 1/4 means the price is £120 × 3/4 = £90. Reducing this by 60% means the final price is £90 × 40% = £36.00.', 'HARD', 1, TRUE, '2026-07-11T13:34:31.832Z', '2026-07-11T13:34:31.832Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5290, 10, 'TEXT', 'Calculate: (4/5 × 3/4) + 0.15. Express the final value as a percentage.', NULL, '["112.5%","65%","80%","75%"]', '75%', '(4/5 × 3/4) = 12/20 = 0.6. Adding 0.15 gives 0.6 + 0.15 = 0.75. As a percentage, this is 75%.', 'HARD', 1, TRUE, '2026-07-11T13:34:31.832Z', '2026-07-11T13:34:31.832Z') ON CONFLICT DO NOTHING;
