INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5292, 10, 'TEXT', 'An item originally priced at £120 is reduced by 1/4, and then reduced further by 40%. What is the final price?', NULL, '["£90.00","£49.00","£54.00","£64.00"]', '£54.00', 'Reducing by 1/4 means the price is £120 × 3/4 = £90. Reducing this by 40% means the final price is £90 × 60% = £54.00.', 'HARD', 1, TRUE, '2026-07-11T13:34:31.832Z', '2026-07-11T13:34:31.832Z') ON CONFLICT DO NOTHING;
