INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10952, 54, 'TEXT', 'Use the quadratic formula to solve: x² - 4x + 1 = 0', NULL, '["x = (-4 ± √20)/2 = -2 ± √5","x = (-4 ± √12)/2 = -2 ± √3","x = (4 ± √12)/2 = 2 ± √3","x = (4 ± √20)/2 = 2 ± √5"]', 'x = (4 ± √12)/2 = 2 ± √3', NULL, 'MEDIUM', 1, TRUE, '2026-07-13T10:01:55.340Z', '2026-07-18T06:28:06.170Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10954, 54, 'TEXT', 'Use the quadratic formula to solve: 2x² + 5x + 1 = 0', NULL, '["x = (5 ± √33)/4","x = (5 ± √17)/4","x = (-5 ± √33)/4","x = (-5 ± √17)/4"]', 'x = (-5 ± √17)/4', NULL, 'MEDIUM', 1, TRUE, '2026-07-13T10:01:55.646Z', '2026-07-18T06:28:06.170Z') ON CONFLICT DO NOTHING;
