INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2169, 29, 'TEXT', 'What number is represented by these tally marks? <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s>', NULL, '["32","29","30","31"]', '30', 'Counting each group of 5 (<s>||||</s>) and individual marks (|) gives 30.', 'EASY', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:57.172Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (317, 6, 'TEXT', 'A number doubled and increased by 7 equals 23. Write an equation and find the number.', NULL, '["2n - 7 = 23, n = 15","n + 7 = 23, n = 16","2n + 7 = 23, n = 8","2(n+7) = 23, n = 4.5"]', '2n + 7 = 23, n = 8', NULL, 'MEDIUM', 1, TRUE, '2026-07-11T13:21:45.992Z', '2026-07-18T06:20:59.347Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1153, 26, 'TEXT', 'A train overtakes a man at 6 km/h in 30 seconds, and a cyclist at 12 km/h in 60 seconds. What is the train''s length?', NULL, '["120 m","150 m","200 m","100 m"]', '120 m', NULL, 'HARD', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:21:00.398Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6278, 26, 'TEXT', 'A car travels at a speed of 55 mph for 1.5 hours. What is the total distance traveled in miles? (Variation: 138)', NULL, '["72.5","82.5","110","87.5"]', '82.5', 'Distance = Speed × Time = 55 × 1.5 = 82.5 miles.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:21:00.400Z') ON CONFLICT DO NOTHING;
