INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2686, 7, 'TEXT', 'Two times a number x is subtracted from the square of y, and the result is divided by 130. Write the formula.', NULL, '["(2x - y²) / 130","(y² - x) / 130","(y² - 2x) / 130","(y - 2x)² / 130"]', '(y² - 2x) / 130', 'Subtracting 2x from y² gives y² - 2x. Dividing by 130 gives (y² - 2x) / 130.', 'HARD', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:21:01.381Z') ON CONFLICT DO NOTHING;
