INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4928, 23, 'TEXT', 'Find the product of prime factors of 144.', NULL, '["2 × 2 × 2 × 5","5 × 5","2 × 3 × 3","2 × 2 × 2 × 2 × 3 × 3"]', '2 × 2 × 2 × 2 × 3 × 3', '144 factored into primes is 2 × 2 × 2 × 2 × 3 × 3.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:20:46.961Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5875, 21, 'TEXT', 'What is the Highest Common Factor (HCF) of 24 and 30? (Variation: 148)', NULL, '["12","8","5","6"]', '6', 'HCF of 24 and 30 is 6.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:31.832Z', '2026-07-18T06:20:47.933Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6210, 24, 'TEXT', 'Calculate the cube of 5: (Variation: 142)', NULL, '["125","140","110","100"]', '125', '5³ = 125.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:20:48.951Z') ON CONFLICT DO NOTHING;
