INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5446, 9, 'TEXT', 'Calculate: 1/3 ÷ 2/5. Express your answer in simplest form. (Variation: 180)', NULL, '["5/6","7/6","3/4","1/2"]', '5/6', 'Multiplying by the reciprocal gives 1/3 × 5/2 = 5/6.', 'HARD', 1, TRUE, '2026-07-11T13:34:31.832Z', '2026-07-18T06:20:51.176Z') ON CONFLICT DO NOTHING;
