INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5526, 11, 'TEXT', 'Perform the division: 3.2 ÷ 0.08. (Variation: 161)', NULL, '["4","30","80","40"]', '40', '3.2 ÷ 0.08 is equivalent to 320 ÷ 8 = 40.', 'HARD', 1, TRUE, '2026-07-11T13:34:31.832Z', '2026-07-18T06:20:52.277Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3166, 12, 'TEXT', 'If 15% of a number is 1740, what is 100% of the number?', NULL, '["11500","11600","11550","11650"]', '11600', 'Since 15% is 1740, 1% is 116. Thus 100% is 11600 = 11600.', 'HARD', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:53.292Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4345, 13, 'TEXT', 'Increase £165 by 10%.', NULL, '["£181.50","£173.25","£198.00","£165"]', '£181.50', '10% of £165 is £16.5. Total is £181.50000000000003.', 'EASY', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:20:54.813Z') ON CONFLICT DO NOTHING;
