INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1227, 30, 'TEXT', 'How many days are there in the month of May (in a non-leap year)?', NULL, '["29","30","31","32"]', '31', NULL, 'EASY', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:20:54.816Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3806, 30, 'TEXT', 'If the 5th of a month is a Thursday, what date will the fourth Thursday of the month be?', NULL, '["19th","26th","27th","25th"]', '26th', 'First is 5th, second is 12th, third is 19th, fourth is 26th.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:54.816Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6513, 30, 'TEXT', 'If the 4th of a month is a Sunday, what date will the fourth Sunday of that month be? (Variation: 154)', NULL, '["26th","18th","25th","24th"]', '25th', 'Suns/Days fall on 4th, 11th, 18th, 25th.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:20:56.112Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6558, 30, 'TEXT', 'Assuming a non-leap year, if February 28th is a Wednesday, what day of the week will March 4th be? (Variation: 199)', NULL, '["Saturday","Monday","Sunday","Sunday_alt_1"]', 'Sunday', 'Feb 28 is the last day of Feb. Adding 4 days gives March 4th, which lands on Sunday.', 'HARD', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:20:56.114Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3686, 31, 'TEXT', 'The temperature was 10°C and fell by 22°C. What is the new temperature?', NULL, '["-11°C","-16°C","-12°C","-14°C"]', '-12°C', '10 - 22 = -12°C.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:57.169Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3724, 31, 'TEXT', 'Find the average temperature of: 18°C, 26°C, 14°C, and -26°C.', NULL, '["9.5°C","7°C","8°C","8.5°C"]', '8°C', 'Sum of temperatures is 32. Dividing by 4 gives 8.0°C.', 'HARD', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:57.171Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2223, 29, 'TEXT', 'Calculate the sum represented by: <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> |||| + <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> |||', NULL, '["177","174","167","172"]', '172', '84 + 88 equals 172.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:57.173Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1125, 28, 'TEXT', 'A company''s revenue rose from £25,000 to £30,000. What is the percentage increase?', NULL, '["18%","25%","15%","20%"]', '20%', NULL, 'MEDIUM', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:20:58.343Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4177, 28, 'TEXT', 'A bicycle was bought for £385 and sold for £308. What is the percentage loss?', NULL, '["15%","20%","10%","25%"]', '20%', 'Loss is £77. Percentage loss = (77 / 385) × 100 = 20%.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:20:58.346Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (316, 6, 'TEXT', 'The perimeter of a square is 48cm. If the side length is s, write an equation and find s.', NULL, '["4s = 48, s = 4","4s = 48, s = 12","s² = 48, s = 6.93","2s = 48, s = 24"]', '4s = 48, s = 12', NULL, 'MEDIUM', 1, TRUE, '2026-07-11T13:21:45.427Z', '2026-07-18T06:20:59.347Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2889, 6, 'TEXT', 'Solve for x: x + 7 = 9', NULL, '["2","1","4","3"]', '2', 'Subtracting 7 from both sides gives x = 2.', 'EASY', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:59.347Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2983, 26, 'TEXT', 'Sarah has 4 packs of pencils. Each pack has 26 pencils. She gives 3 pencils to her brother. How many does she have left?', NULL, '["101","105","99","97"]', '101', 'Total pencils is 4 × 26 = 104. Subtracting 3 leaves 101.', 'EASY', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:21:00.399Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6291, 26, 'TEXT', 'A car travels at a speed of 45 mph for 1.5 hours. What is the total distance traveled in miles? (Variation: 151)', NULL, '["57.5","67.5","90","72.5"]', '67.5', 'Distance = Speed × Time = 45 × 1.5 = 67.5 miles.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:21:00.400Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6410, 27, 'TEXT', 'A mother is five times as old as her daughter. If their combined age is 48, how old is the daughter? (Variation: 142)', NULL, '["11","8","7","10"]', '8', 'd + 5d = 6d = 48. Daughter is 8.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:21:01.384Z') ON CONFLICT DO NOTHING;
