INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4916, 23, 'TEXT', 'Find the product of prime factors of 102.', NULL, '["2 × 2 × 2 × 5","2 × 3 × 17","5 × 5","2 × 3 × 3"]', '2 × 3 × 17', '102 factored into primes is 2 × 3 × 17.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:20:46.960Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5881, 21, 'TEXT', 'Two alarm systems trigger: Alarm A every 8 minutes and Alarm B every 10 minutes. If they trigger simultaneously at 9:00 AM, when is next occurrence? (Variation: 154)', NULL, '["9:45 AM","9:40 AM","9:30 AM","10:15 AM"]', '9:40 AM', 'LCM is 40 minutes. 9:00 AM + 40 minutes is 9:40 AM.', 'HARD', 1, TRUE, '2026-07-11T13:34:31.832Z', '2026-07-18T06:20:47.933Z') ON CONFLICT DO NOTHING;
