INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (174, 3, 'TEXT', 'What is the value of 5.4 ÷ 0.018?', NULL, '["0.3","30","300","3000"]', '300', NULL, 'HARD', 1, TRUE, '2026-07-11T13:20:22.534Z', '2026-07-18T06:20:52.270Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3055, 12, 'TEXT', 'Find 10% of £680', NULL, '["£34","£68","£136","£102"]', '£68', '10% of £680 is 10/100 × 680 = £68.', 'EASY', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:52.278Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3160, 12, 'TEXT', 'If 15% of a number is 1668, what is 100% of the number?', NULL, '["11070","11170","11120","11020"]', '11120', 'Since 15% is 1668, 1% is 111.2. Thus 100% is 11120 = 11120.', 'HARD', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:53.292Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5390, 10, 'TEXT', 'A coat is on sale. Its original price contains a reduction of 1/5 and a starting price of £1210. If a further discount of 50% is applied, what is final cost?', NULL, '["£474.00","£484.00","£489.00","£150.00"]', '£484.00', 'First reduction gives £968. Second reduction gives £484.00.', 'HARD', 1, TRUE, '2026-07-11T13:34:31.832Z', '2026-07-18T06:20:53.298Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1279, 30, 'TEXT', 'If the 1st of a month falls on a Friday, what day of the week is the 20th of that month?', NULL, '["Wednesday","Monday","Tuesday","Thursday"]', 'Wednesday', NULL, 'MEDIUM', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:20:54.816Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1303, 31, 'TEXT', 'The temperature is 6°C and falls by 14°C. What is the new temperature? (Remember the temperature can go below 0°C.)', NULL, '["-10°C","8°C","-8°C","-6°C"]', '-8°C', NULL, 'MEDIUM', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:20:56.116Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3652, 31, 'TEXT', 'The temperature rises from 6°C to 14°C. What is the increase in degrees Celsius?', NULL, '["9","8","10","6"]', '8', 'Subtracting gives 14 - 6 = 8°C.', 'EASY', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:57.168Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3734, 31, 'TEXT', 'Find the average temperature of: 13°C, 15°C, 9°C, and -15°C.', NULL, '["7°C","5.5°C","4.5°C","6°C"]', '5.5°C', 'Sum of temperatures is 22. Dividing by 4 gives 5.5°C.', 'HARD', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:57.171Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1048, 28, 'TEXT', 'A book is bought for £20 and sold at a 10% profit. What is the selling price?', NULL, '["£23","£24","£21","£22"]', '£22', NULL, 'EASY', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:20:58.343Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4205, 28, 'TEXT', 'By selling a book for £630.00, a bookshop makes a 20% profit. What was the origin cost price of the book?', NULL, '["£520","£515","£525","£530"]', '£525', 'Cost Price = Selling Price ÷ 1.20 = £630.00 ÷ 1.20 = £525.', 'HARD', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:20:59.342Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (277, 5, 'TEXT', 'Simplify: 2(3a + 4) - 3(a - 1).', NULL, '["3a + 11","9a + 5","3a + 8","3a + 5"]', '3a + 11', NULL, 'MEDIUM', 1, TRUE, '2026-07-11T13:21:22.438Z', '2026-07-18T06:20:59.347Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1148, 26, 'TEXT', 'A boat travels downstream for 5 hours and upstream for 8 hours covering equal distances. If stream speed is 3 km/h, what is the boat''s speed in still water?', NULL, '["9 km/h","13 km/h","15 km/h","11 km/h"]', '11 km/h', NULL, 'HARD', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:21:00.397Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6326, 26, 'TEXT', 'If 4 workers take 3 days to construct a brick frame, how long will it take 6 workers to do same work? (Variation: 186)', NULL, '["3.5 days","2.0 days","4.0 days","2.0 days_alt_1"]', '2.0 days', 'Man-days = 4 * 3 = 12. 6 workers need 12 ÷ 6 = 2.0 days.', 'HARD', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:21:00.401Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2599, 7, 'TEXT', 'A number x is multiplied by 43 and then increased by 7. Which formula represents this statement?', NULL, '["x + 50","43x + 7","43x - 7","43(x + 7)"]', '43x + 7', 'Multiplying x by 43 gives 43x. Increasing by 7 gives 43x + 7.', 'EASY', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:21:00.402Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2664, 7, 'TEXT', 'A shopkeeper sells notebooks for £108 each and pens for £2 each. What is the total cost (C) of n notebooks and p pens?', NULL, '["C = 108n + 2p","C = 110(n + p)","C = 2n + 108p","C = 108np"]', 'C = 108n + 2p', 'notebooks cost 108n, pens cost 2p. The sum is 108n + 2p.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:21:01.380Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1103, 27, 'TEXT', 'Two years ago, a boy was 1/3 of his uncle''s age. Now the uncle is 30. How old is the boy now?', NULL, '["12","9","10","8"]', '10', NULL, 'MEDIUM', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:21:01.383Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5653, 17, 'TEXT', 'A positive integer n leaves a remainder of 0 when divided by 4. What remainder does 3n leave when divided by 4? (Variation: 181)', NULL, '["0_alt_1","1","2","0"]', '0', 'The remainder of 3n modulo 4 is equivalent to (3 × 0) modulo 4 = 0.', 'HARD', 1, TRUE, '2026-07-11T13:34:31.832Z', '2026-07-18T06:20:40.668Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5645, 17, 'TEXT', 'A positive integer n leaves a remainder of 4 when divided by 8. What remainder does 3n leave when divided by 8? (Variation: 173)', NULL, '["4","5","0","6"]', '4', 'The remainder of 3n modulo 8 is equivalent to (3 × 4) modulo 8 = 4.', 'HARD', 1, TRUE, '2026-07-11T13:34:31.832Z', '2026-07-18T06:20:40.668Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3290, 19, 'TEXT', 'I think of a number, add 62, and get 72. What is the number?', NULL, '["14","10","8","12"]', '10', 'Subtracting 62 from 72 gives 10.', 'EASY', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:41.850Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3291, 19, 'TEXT', 'I think of a number, add 63, and get 73. What is the number?', NULL, '["12","14","8","10"]', '10', 'Subtracting 63 from 73 gives 10.', 'EASY', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:41.850Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3331, 19, 'TEXT', 'I think of a number, multiply it by 3, and then subtract 103. The result is -73. What is my starting number?', NULL, '["10","9","12","11"]', '10', 'Add 103 to get 30, then divide by 3 to get 10.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:41.853Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3809, 30, 'TEXT', 'If the 5th of a month is a Sunday, what date will the fourth Sunday of the month be?', NULL, '["19th","25th","26th","27th"]', '26th', 'First is 5th, second is 12th, third is 19th, fourth is 26th.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:54.816Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3696, 31, 'TEXT', 'The temperature was 5°C and fell by 14°C. What is the new temperature?', NULL, '["-11°C","-13°C","-8°C","-9°C"]', '-9°C', '5 - 14 = -9°C.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:57.169Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1119, 28, 'TEXT', 'By selling at £96, a shopkeeper makes a 20% profit. What was the cost price?', NULL, '["£85","£75","£70","£80"]', '£80', NULL, 'MEDIUM', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:20:58.343Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4159, 28, 'TEXT', 'A bicycle was bought for £295 and sold for £236. What is the percentage loss?', NULL, '["20%","25%","15%","10%"]', '20%', 'Loss is £59. Percentage loss = (59 / 295) × 100 = 20%.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:20:58.345Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2981, 26, 'TEXT', 'Sarah has 4 packs of pencils. Each pack has 24 pencils. She gives 3 pencils to her brother. How many does she have left?', NULL, '["93","91","97","89"]', '93', 'Total pencils is 4 × 24 = 96. Subtracting 3 leaves 93.', 'EASY', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:21:00.398Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1037, 27, 'TEXT', 'Three children are aged 5, 8, and 11. What is their average age?', NULL, '["8","7","6","9"]', '8', NULL, 'EASY', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:21:01.383Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6378, 27, 'TEXT', 'Sarah is 6 years old. Her sister is 3 years younger. What will be the sum of their ages in 2 years? (Variation: 110)', NULL, '["11","9","13","15"]', '13', 'Sarah in 2 years: 8. Sister in 2 years: 5. Sum is 13.', 'EASY', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:21:01.384Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6461, 27, 'TEXT', 'A father is 35 years old and his son is 11 years old. After how many years will father be twice as old as the son? (Variation: 193)', NULL, '["15","12","13","14"]', '13', '35 + x = 2*(11 + x). Solving yields x = 13.', 'HARD', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:21:01.385Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3256, 19, 'TEXT', 'I think of a number, add 28, and get 38. What is the number?', NULL, '["14","8","10","12"]', '10', 'Subtracting 28 from 38 gives 10.', 'EASY', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:40.672Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3271, 19, 'TEXT', 'I think of a number, add 43, and get 53. What is the number?', NULL, '["14","10","8","12"]', '10', 'Subtracting 43 from 53 gives 10.', 'EASY', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:40.673Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3279, 19, 'TEXT', 'I think of a number, add 51, and get 61. What is the number?', NULL, '["10","8","12","14"]', '10', 'Subtracting 51 from 61 gives 10.', 'EASY', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:41.848Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3286, 19, 'TEXT', 'I think of a number, add 58, and get 68. What is the number?', NULL, '["8","10","14","12"]', '10', 'Subtracting 58 from 68 gives 10.', 'EASY', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:41.850Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3295, 19, 'TEXT', 'I think of a number, add 67, and get 77. What is the number?', NULL, '["14","8","12","10"]', '10', 'Subtracting 67 from 77 gives 10.', 'EASY', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:41.852Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3322, 19, 'TEXT', 'I think of a number, multiply it by 3, and then subtract 94. The result is -64. What is my starting number?', NULL, '["10","12","11","9"]', '10', 'Add 94 to get 30, then divide by 3 to get 10.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:41.853Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3324, 19, 'TEXT', 'I think of a number, multiply it by 3, and then subtract 96. The result is -66. What is my starting number?', NULL, '["11","9","12","10"]', '10', 'Add 96 to get 30, then divide by 3 to get 10.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:41.853Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3424, 19, 'TEXT', 'I think of a number, double it, add 196, and then divide by 2. The result is 108. Starting number?', NULL, '["10","13","7","11"]', '10', 'Multiply by 2, subtract 196, then divide by 2. The original number is 10.', 'HARD', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:42.834Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3378, 19, 'TEXT', 'I think of a number, double it, add 150, and then divide by 2. The result is 85. Starting number?', NULL, '["11","10","13","7"]', '10', 'Multiply by 2, subtract 150, then divide by 2. The original number is 10.', 'HARD', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:42.831Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3393, 19, 'TEXT', 'I think of a number, double it, add 165, and then divide by 2. The result is 92.5. Starting number?', NULL, '["7","10","13","11"]', '10', 'Multiply by 2, subtract 165, then divide by 2. The original number is 10.', 'HARD', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:42.833Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (137, 1, 'TEXT', 'True or False: Every multiple of 6 is also a multiple of both 2 and 3.', NULL, '["Sometimes","Only multiples of 12","False","True"]', 'True', NULL, 'HARD', 1, TRUE, '2026-07-11T13:20:00.623Z', '2026-07-18T06:20:42.835Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1432, 1, 'TEXT', 'The number 21 is a multiple of 7.', NULL, '["False","True"]', 'True', NULL, 'EASY', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:20:43.822Z') ON CONFLICT DO NOTHING;
