INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5380, 10, 'TEXT', 'A coat is on sale. Its original price contains a reduction of 1/5 and a starting price of £1010. If a further discount of 30% is applied, what is final cost?', NULL, '["£150.00","£570.60","£565.60","£555.60"]', '£565.60', 'First reduction gives £808. Second reduction gives £565.60.', 'HARD', 1, TRUE, '2026-07-11T13:34:31.832Z', '2026-07-18T06:20:53.298Z') ON CONFLICT DO NOTHING;
