INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1052, 28, 'TEXT', 'A phone is bought for £120 and sold for £90. What is the loss?', NULL, '["£35","£30","£20","£25"]', '£30', NULL, 'EASY', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:20:58.342Z') ON CONFLICT DO NOTHING;
