INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2893, 6, 'TEXT', 'Solve for x: x + 11 = 17', NULL, '["7","8","6","5"]', '6', 'Subtracting 11 from both sides gives x = 6.', 'EASY', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:59.347Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2970, 26, 'TEXT', 'Sarah has 4 packs of pencils. Each pack has 13 pencils. She gives 3 pencils to her brother. How many does she have left?', NULL, '["47","45","53","49"]', '49', 'Total pencils is 4 × 13 = 52. Subtracting 3 leaves 49.', 'EASY', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:21:00.398Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6314, 26, 'TEXT', 'If 4 workers take 3 days to construct a brick frame, how long will it take 6 workers to do same work? (Variation: 174)', NULL, '["4.0 days","2.0 days","3.5 days","2.0 days_alt_1"]', '2.0 days', 'Man-days = 4 * 3 = 12. 6 workers need 12 ÷ 6 = 2.0 days.', 'HARD', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:21:00.400Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6332, 26, 'TEXT', 'If 4 workers take 3 days to construct a brick frame, how long will it take 6 workers to do same work? (Variation: 192)', NULL, '["4.0 days","2.0 days_alt_1","3.5 days","2.0 days"]', '2.0 days', 'Man-days = 4 * 3 = 12. 6 workers need 12 ÷ 6 = 2.0 days.', 'HARD', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:21:00.401Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2688, 7, 'TEXT', 'Two times a number x is subtracted from the square of y, and the result is divided by 132. Write the formula.', NULL, '["(y² - 2x) / 132","(y - 2x)² / 132","(2x - y²) / 132","(y² - x) / 132"]', '(y² - 2x) / 132', 'Subtracting 2x from y² gives y² - 2x. Dividing by 132 gives (y² - 2x) / 132.', 'HARD', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:21:01.381Z') ON CONFLICT DO NOTHING;
