INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5277, 10, 'TEXT', 'An item originally priced at £120 is reduced by 1/4, and then reduced further by 40%. What is the final price?', NULL, '["£54.00","£49.00","£90.00","£64.00"]', '£54.00', 'Reducing by 1/4 means the price is £120 × 3/4 = £90. Reducing this by 40% means the final price is £90 × 60% = £54.00.', 'HARD', 1, TRUE, '2026-07-11T13:34:31.832Z', '2026-07-18T06:20:53.296Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4442, 13, 'TEXT', 'A ticket price was increased by 25% to £1625.00. What was the original price?', NULL, '["£1300.00","£1310.00","£100.00","£1290.00"]', '£1300.00', 'Original Price = £1625.00 ÷ 1.25 = £1300.00.', 'HARD', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:20:54.815Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1219, 30, 'TEXT', 'If today is Saturday, what day of the week will it be in 3 days?', NULL, '["Tuesday","Wednesday","Monday","Thursday"]', 'Tuesday', NULL, 'EASY', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:20:54.816Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3795, 30, 'TEXT', 'If today is Sunday, what day of the week will it be in 5 days?', NULL, '["Thursday","Saturday","Friday","Sunday"]', 'Friday', '5 days after Sunday is Friday.', 'EASY', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:54.816Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2314, 32, 'TEXT', 'Convert 50 liters (L) into milliliters (mL).', NULL, '["50000 mL","5000 mL","500000 mL","500 mL"]', '50000 mL', 'Since 1 L = 1000 mL, 50 L = 50000 mL.', 'EASY', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:56.114Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3699, 31, 'TEXT', 'The temperature was 8°C and fell by 23°C. What is the new temperature?', NULL, '["-19°C","-17°C","-15°C","-14°C"]', '-15°C', '8 - 23 = -15°C.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:57.169Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2213, 29, 'TEXT', 'Calculate the sum represented by: <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> |||| + <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> |||', NULL, '["147","152","154","157"]', '152', '74 + 78 equals 152.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:57.172Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4113, 28, 'TEXT', 'A toy is bought for £65 and sold for £76. What is the profit?', NULL, '["£10","£2","£11","£12"]', '£11', 'Profit = Selling Price - Cost Price = £76 - £65 = £11.', 'EASY', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:20:58.344Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4178, 28, 'TEXT', 'A bicycle was bought for £390 and sold for £312. What is the percentage loss?', NULL, '["10%","25%","15%","20%"]', '20%', 'Loss is £78. Percentage loss = (78 / 390) × 100 = 20%.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:20:58.346Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (283, 6, 'TEXT', 'If x = -2, find the value of x² - 3x.', NULL, '["-10","4","-2","10"]', '10', NULL, 'MEDIUM', 1, TRUE, '2026-07-11T13:21:25.796Z', '2026-07-18T06:20:59.346Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2996, 26, 'TEXT', 'Sarah has 4 packs of pencils. Each pack has 39 pencils. She gives 3 pencils to her brother. How many does she have left?', NULL, '["153","149","157","151"]', '153', 'Total pencils is 4 × 39 = 156. Subtracting 3 leaves 153.', 'EASY', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:21:00.399Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2719, 7, 'TEXT', 'Two times a number x is subtracted from the square of y, and the result is divided by 163. Write the formula.', NULL, '["(y² - x) / 163","(y² - 2x) / 163","(y - 2x)² / 163","(2x - y²) / 163"]', '(y² - 2x) / 163', 'Subtracting 2x from y² gives y² - 2x. Dividing by 163 gives (y² - 2x) / 163.', 'HARD', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:21:01.382Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2738, 7, 'TEXT', 'Two times a number x is subtracted from the square of y, and the result is divided by 182. Write the formula.', NULL, '["(2x - y²) / 182","(y² - 2x) / 182","(y - 2x)² / 182","(y² - x) / 182"]', '(y² - 2x) / 182', 'Subtracting 2x from y² gives y² - 2x. Dividing by 182 gives (y² - 2x) / 182.', 'HARD', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:21:01.382Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6163, 24, 'TEXT', 'Calculate the square of 12: (Variation: 95)', NULL, '["148","140","144","152"]', '144', '12² = 144.', 'EASY', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:20:48.948Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3442, 25, 'TEXT', 'Find the next number in the pattern: 16, 21, 26, 31, ...', NULL, '["46","36","37","31"]', '36', 'The rule is add 5. The next number is 36.', 'EASY', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:48.951Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3533, 25, 'TEXT', 'Find the missing term: 107, 214, 428, ?, 1712', NULL, '["856","642","1070","1284"]', '856', 'The rule is multiply by 2. The missing term is 856.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:48.952Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5102, 8, 'TEXT', 'Find the next term in the descending sequence: 550, 547, 544, ...', NULL, '["540","0","544","541"]', '541', 'The common difference is -3. The next term is 541.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:31.832Z', '2026-07-18T06:20:50.152Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (582, 9, 'TEXT', 'A school of 640 pupils has 37.5% taking part in a sports event. How many pupils is that?', NULL, '["220","230","250","240"]', '240', NULL, 'HARD', 1, TRUE, '2026-07-11T13:24:19.516Z', '2026-07-18T06:20:50.156Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (501, 9, 'TEXT', 'Calculate 9/10 ÷ 3.', NULL, '["27/10","1/3","3/10","3/30"]', '3/10', NULL, 'MEDIUM', 1, TRUE, '2026-07-11T13:23:32.821Z', '2026-07-18T06:20:50.157Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5415, 9, 'TEXT', 'Simplify the fraction 10/20 to its simplest form. (Variation: 149)', NULL, '["1/5","1/2","3/8","2/7"]', '1/2', 'Dividing numerator and denominator by their HCF gives 1/2.', 'EASY', 1, TRUE, '2026-07-11T13:34:31.832Z', '2026-07-18T06:20:51.175Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3954, 14, 'TEXT', 'If 1/3 of a container of liquid is 20 liters, how many liters does the full container hold?', NULL, '["60","80","40","110"]', '60', '20 ÷ 1 × 3 gives the total capacity: 60 liters.', 'HARD', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:20:51.180Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5047, 11, 'TEXT', 'Calculate: 4.8 ÷ 0.08', NULL, '["120","30","60","6"]', '60', '4.8 ÷ 0.08 is equivalent to 480 ÷ 8 = 60.', 'HARD', 1, TRUE, '2026-07-11T13:34:31.832Z', '2026-07-18T06:20:52.276Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5230, 10, 'TEXT', 'Convert the percentage 50% into a simplified fraction.', NULL, '["1/3","1/4","1/2","1"]', '1/2', '50% = 50/100. Simplifying this fraction gives 1/2.', 'EASY', 1, TRUE, '2026-07-11T13:34:31.832Z', '2026-07-18T06:20:53.295Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6478, 30, 'TEXT', 'If the 4th of a month is a Sunday, what date will the fourth Sunday of that month be? (Variation: 119)', NULL, '["26th","24th","25th","18th"]', '25th', 'Suns/Days fall on 4th, 11th, 18th, 25th.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:20:54.818Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1300, 31, 'TEXT', 'The daytime temperature is 6°C and the night-time temperature is 0°C. What is the difference between the two temperatures?', NULL, '["7°C","-6°C","6°C","5°C"]', '6°C', NULL, 'MEDIUM', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:20:56.116Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2163, 29, 'TEXT', 'What number is represented by these tally marks? <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> ||||', NULL, '["25","23","24","26"]', '24', 'Counting each group of 5 (<s>||||</s>) and individual marks (|) gives 24.', 'EASY', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:57.172Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2265, 29, 'TEXT', 'Solve: (<s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> | + <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> |||) - <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s>', NULL, '["131","129","127","133"]', '129', '126 + 128 - 125 equals 129.', 'HARD', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:57.173Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1082, 26, 'TEXT', 'A rectangle''s perimeter is 56 cm. Its length is 16 cm. What is its area?', NULL, '["196 cm²","168 cm²","180 cm²","192 cm²"]', '192 cm²', NULL, 'MEDIUM', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:21:00.397Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6338, 26, 'TEXT', 'If 4 workers take 3 days to construct a brick frame, how long will it take 6 workers to do same work? (Variation: 198)', NULL, '["2.0 days","3.5 days","4.0 days","2.0 days_alt_1"]', '2.0 days', 'Man-days = 4 * 3 = 12. 6 workers need 12 ÷ 6 = 2.0 days.', 'HARD', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:21:00.401Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6167, 24, 'TEXT', 'Calculate the square of 4: (Variation: 99)', NULL, '["20","12","16","24"]', '16', '4² = 16.', 'EASY', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:20:48.948Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3462, 25, 'TEXT', 'Find the next number in the pattern: 36, 41, 46, 51, ...', NULL, '["57","51","66","56"]', '56', 'The rule is add 5. The next number is 56.', 'EASY', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:48.951Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (397, 8, 'TEXT', 'A sequence has nth term n² + 2n. Find the value of n for which the term equals 35.', NULL, '["5","4","7","6"]', '5', NULL, 'HARD', 1, TRUE, '2026-07-11T13:22:32.481Z', '2026-07-18T06:20:48.952Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (574, 9, 'TEXT', 'In a class of 32, 3/4 walk to school. Of those who walk, 1/2 walk with a friend. How many walk alone?', NULL, '["24","12","8","16"]', '12', NULL, 'HARD', 1, TRUE, '2026-07-11T13:24:15.293Z', '2026-07-18T06:20:50.156Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5408, 9, 'TEXT', 'Simplify the fraction 6/12 to its simplest form. (Variation: 142)', NULL, '["1/5","2/7","3/8","1/2"]', '1/2', 'Dividing numerator and denominator by their HCF gives 1/2.', 'EASY', 1, TRUE, '2026-07-11T13:34:31.832Z', '2026-07-18T06:20:50.156Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3858, 14, 'TEXT', 'Find 1/5 of £400', NULL, '["£160","£75","£80","£85"]', '£80', 'Divide £400 by 5 to get £80.', 'EASY', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:51.179Z') ON CONFLICT DO NOTHING;
