INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2456, 10, 'TEXT', 'Convert the fraction 1/10 into a percentage.', NULL, '["5%","10%","10%1","20%"]', '10%', '1/10 = 0.1 = 10%.', 'EASY', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:53.295Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5340, 10, 'TEXT', 'What is the decimal representation of the mixed number 3 3/8?', NULL, '["3.375","3.5","3.125","3.875"]', '3.375', '3 + 3/8 = 3 + 0.375 = 3.375.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:31.832Z', '2026-07-18T06:20:53.297Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3644, 31, 'TEXT', 'The temperature rises from 13°C to 21°C. What is the increase in degrees Celsius?', NULL, '["10","8","6","9"]', '8', 'Subtracting gives 21 - 13 = 8°C.', 'EASY', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:57.168Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2226, 29, 'TEXT', 'Calculate the sum represented by: <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> || + <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> |', NULL, '["178","183","173","180"]', '178', '87 + 91 equals 178.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:57.173Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1066, 28, 'TEXT', 'An item costing £50 is sold at a 40% profit. What is the selling price?', NULL, '["£80","£65","£75","£70"]', '£70', NULL, 'EASY', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:20:58.343Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4158, 28, 'TEXT', 'A bicycle was bought for £290 and sold for £232. What is the percentage loss?', NULL, '["20%","25%","15%","10%"]', '20%', 'Loss is £58. Percentage loss = (58 / 290) × 100 = 20%.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:20:58.345Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4190, 28, 'TEXT', 'A bicycle was bought for £450 and sold for £360. What is the percentage loss?', NULL, '["10%","25%","20%","15%"]', '20%', 'Loss is £90. Percentage loss = (90 / 450) × 100 = 20%.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:20:58.347Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (275, 5, 'TEXT', 'Simplify: 7p - 2(p + 3).', NULL, '["9p - 6","5p - 3","5p - 6","5p + 6"]', '5p - 6', NULL, 'MEDIUM', 1, TRUE, '2026-07-11T13:21:21.007Z', '2026-07-18T06:20:59.347Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2957, 6, 'TEXT', 'Solve for x: 4x + 10 = 5x - 5', NULL, '["13","11","7","10"]', '10', 'Rearranging terms to solve for x gives x = 10.', 'HARD', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:59.349Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1151, 26, 'TEXT', 'Two cyclists start at the same point and ride in opposite directions. One at 15 km/h and the other at 20 km/h. After how long are they 105 km apart?', NULL, '["4 h","3 h","2 h","5 h"]', '3 h', NULL, 'HARD', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:21:00.397Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6328, 26, 'TEXT', 'If 4 workers take 3 days to construct a brick frame, how long will it take 6 workers to do same work? (Variation: 188)', NULL, '["3.5 days","2.0 days_alt_1","4.0 days","2.0 days"]', '2.0 days', 'Man-days = 4 * 3 = 12. 6 workers need 12 ÷ 6 = 2.0 days.', 'HARD', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:21:00.401Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2678, 7, 'TEXT', 'A shopkeeper sells notebooks for £122 each and pens for £2 each. What is the total cost (C) of n notebooks and p pens?', NULL, '["C = 2n + 122p","C = 122n + 2p","C = 122np","C = 124(n + p)"]', 'C = 122n + 2p', 'notebooks cost 122n, pens cost 2p. The sum is 122n + 2p.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:21:01.380Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4849, 27, 'TEXT', 'A mother is 26 years old and her daughter is 8 years old. In how many years will the mother be twice as old as the daughter?', NULL, '["12","9","11","10"]', '10', 'Setting up equation: 26 + x = 2 × (8 + x). Solving gives x = 10.', 'HARD', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:21:01.383Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6445, 27, 'TEXT', 'A father is 32 years old and his son is 10 years old. After how many years will father be twice as old as the son? (Variation: 177)', NULL, '["14","11","12","13"]', '12', '32 + x = 2*(10 + x). Solving yields x = 12.', 'HARD', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:21:01.384Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3519, 25, 'TEXT', 'Find the missing term: 93, 186, 372, ?, 1488', NULL, '["558","1116","930","744"]', '744', 'The rule is multiply by 2. The missing term is 744.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:48.952Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (395, 8, 'TEXT', 'A sequence''s nth term is 3n + 5. For which value of n does the term equal 50?', NULL, '["14","16.7","15","45"]', '15', NULL, 'HARD', 1, TRUE, '2026-07-11T13:22:31.254Z', '2026-07-18T06:20:48.952Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5167, 8, 'TEXT', 'If the nth term of a sequence is 6n + 120, what is the 10th term?', NULL, '["180","175","50","185"]', '180', 'Substitute n = 10 into the formula: 6(10) + 120 = 180.', 'HARD', 1, TRUE, '2026-07-11T13:34:31.832Z', '2026-07-18T06:20:50.153Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5414, 9, 'TEXT', 'Simplify the fraction 8/16 to its simplest form. (Variation: 148)', NULL, '["3/8","2/7","1/5","1/2"]', '1/2', 'Dividing numerator and denominator by their HCF gives 1/2.', 'EASY', 1, TRUE, '2026-07-11T13:34:31.832Z', '2026-07-18T06:20:51.175Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3943, 14, 'TEXT', 'If 5/7 of a container of liquid is 350 liters, how many liters does the full container hold?', NULL, '["510","470","540","490"]', '490', '350 ÷ 5 × 7 gives the total capacity: 490 liters.', 'HARD', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:51.179Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5029, 11, 'TEXT', 'Calculate: 0.3 × 0.4', NULL, '["0.12","1.12","1.2","0.22"]', '0.12', '0.3 × 0.4 equals 0.12.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:31.832Z', '2026-07-18T06:20:52.276Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5524, 11, 'TEXT', 'Perform the division: 5.6 ÷ 0.08. (Variation: 159)', NULL, '["30","7","140","70"]', '70', '5.6 ÷ 0.08 is equivalent to 560 ÷ 8 = 70.', 'HARD', 1, TRUE, '2026-07-11T13:34:31.832Z', '2026-07-18T06:20:52.277Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3073, 12, 'TEXT', 'Find 10% of £1040', NULL, '["£156","£208","£104","£52"]', '£104', '10% of £1040 is 10/100 × 1040 = £104.', 'EASY', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:52.278Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2475, 10, 'TEXT', 'Convert the fraction 74/8 into a decimal.', NULL, '["9.25","9.15","9.3","9.35"]', '9.25', 'Dividing 74 by 8 gives 9.250.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:53.295Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6472, 30, 'TEXT', 'If yesterday was Monday, what day of the week will it be in 6 days from today? (Variation: 113)', NULL, '["Monday","Monday_alt_1","Tuesday","Sunday"]', 'Monday', 'Today is Tuesday. Adding 6 days yields Monday.', 'EASY', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:20:54.817Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2349, 32, 'TEXT', 'A jug contains 120 L of juice. If you pour out 750 mL, how much juice remains in mL?', NULL, '["119150 mL","119450 mL","119350 mL","119250 mL"]', '119250 mL', '120 L is 120000 mL. Subtracting 750 mL leaves 119250 mL.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:56.114Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2438, 32, 'TEXT', 'A large flask has a capacity of 298 L. How many full cups of 250 mL can be filled from this flask?', NULL, '["1196","1194","1192","1190"]', '1192', '298 L = 298000 mL. 298000 ÷ 250 = 1192 cups.', 'HARD', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:56.115Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3628, 31, 'TEXT', 'The temperature rises from 12°C to 20°C. What is the increase in degrees Celsius?', NULL, '["10","6","8","9"]', '8', 'Subtracting gives 20 - 12 = 8°C.', 'EASY', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:57.168Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1274, 29, 'TEXT', 'A survey was recorded using tally marks: Football: IIII/ IIII/ IIII/ Tennis: IIII/ IIII/ I Swimming: IIII/ IIII/ I I How many votes did Football receive?', NULL, '["17","16","15","14"]', '15', NULL, 'MEDIUM', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:20:57.171Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2192, 29, 'TEXT', 'Calculate the sum represented by: <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> ||| + <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> ||', NULL, '["112","115","105","110"]', '110', '53 + 57 equals 110.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:57.172Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2271, 29, 'TEXT', 'Solve: (<s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> || + <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> ||||) - <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> |', NULL, '["139","133","137","135"]', '135', '132 + 134 - 131 equals 135.', 'HARD', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:57.173Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1113, 28, 'TEXT', 'An article is sold at a 15% profit for £92. What is the cost price?', NULL, '["£85","£75","£78","£80"]', '£80', NULL, 'MEDIUM', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:20:58.345Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4226, 28, 'TEXT', 'By selling a book for £756.00, a bookshop makes a 20% profit. What was the origin cost price of the book?', NULL, '["£620","£625","£635","£630"]', '£630', 'Cost Price = Selling Price ÷ 1.20 = £756.00 ÷ 1.20 = £630.', 'HARD', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:20:59.344Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (371, 6, 'TEXT', 'Solve: x/4 - 2 = x/8 + 1.', NULL, '["x = 12","x = 24","x = 8","x = 6"]', 'x = 24', NULL, 'HARD', 1, TRUE, '2026-07-11T13:22:17.532Z', '2026-07-18T06:20:59.347Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2604, 7, 'TEXT', 'A number x is multiplied by 48 and then increased by 7. Which formula represents this statement?', NULL, '["48x + 7","48x - 7","48(x + 7)","x + 55"]', '48x + 7', 'Multiplying x by 48 gives 48x. Increasing by 7 gives 48x + 7.', 'EASY', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:21:00.402Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2650, 7, 'TEXT', 'A shopkeeper sells notebooks for £94 each and pens for £2 each. What is the total cost (C) of n notebooks and p pens?', NULL, '["C = 96(n + p)","C = 94n + 2p","C = 2n + 94p","C = 94np"]', 'C = 94n + 2p', 'notebooks cost 94n, pens cost 2p. The sum is 94n + 2p.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:21:01.379Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6352, 27, 'TEXT', 'Sarah is 10 years old. Her sister is 3 years younger. What will be the sum of their ages in 2 years? (Variation: 84)', NULL, '["19","21","17","15"]', '21', 'Sarah in 2 years: 12. Sister in 2 years: 9. Sum is 21.', 'EASY', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:21:01.383Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (486, 9, 'TEXT', 'Calculate 2/3 + 3/4.', NULL, '["17/12","5/7","1 5/12","5/12"]', '1 5/12', NULL, 'MEDIUM', 1, TRUE, '2026-07-11T13:23:24.115Z', '2026-07-18T06:20:50.154Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2525, 9, 'TEXT', 'Simplify the fraction 8/16 to its simplest form.', NULL, '["3/8","1/2","2/7","1/5"]', '1/2', 'Dividing numerator and denominator by their HCF gives 1/2.', 'EASY', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:50.156Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3882, 14, 'TEXT', 'Find 4/5 of £250', NULL, '["£200","£190","£210","£250"]', '£200', 'Divide £250 by 5 and multiply by 4 = £200.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:51.179Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5603, 14, 'TEXT', 'Calculate 2/3 of £270. (Variation: 175)', NULL, '["£170","£270","£190","£180"]', '£180', 'Divide £270 by 3 and multiply by 2 = £180.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:31.832Z', '2026-07-18T06:20:51.180Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4361, 13, 'TEXT', 'Increase £245 by 10%.', NULL, '["£294.00","£245","£269.50","£257.25"]', '£269.50', '10% of £245 is £24.5. Total is £269.5.', 'EASY', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:20:54.814Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3777, 30, 'TEXT', 'If today is Tuesday, what day of the week will it be in 6 days?', NULL, '["Sunday","Tuesday","Monday","Wednesday"]', 'Monday', '6 days after Tuesday is Monday.', 'EASY', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:54.816Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6476, 30, 'TEXT', 'If the 4th of a month is a Friday, what date will the fourth Friday of that month be? (Variation: 117)', NULL, '["18th","26th","25th","24th"]', '25th', 'Suns/Days fall on 4th, 11th, 18th, 25th.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:20:54.817Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6496, 30, 'TEXT', 'If the 4th of a month is a Thursday, what date will the fourth Thursday of that month be? (Variation: 137)', NULL, '["24th","26th","18th","25th"]', '25th', 'Suns/Days fall on 4th, 11th, 18th, 25th.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:20:56.110Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2320, 32, 'TEXT', 'Convert 62 liters (L) into milliliters (mL).', NULL, '["62000 mL","620000 mL","6200 mL","620 mL"]', '62000 mL', 'Since 1 L = 1000 mL, 62 L = 62000 mL.', 'EASY', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:56.114Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2443, 32, 'TEXT', 'A large flask has a capacity of 308 L. How many full cups of 250 mL can be filled from this flask?', NULL, '["1232","1230","1234","1236"]', '1232', '308 L = 308000 mL. 308000 ÷ 250 = 1232 cups.', 'HARD', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:56.116Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3617, 31, 'TEXT', 'The temperature rises from 16°C to 21°C. What is the increase in degrees Celsius?', NULL, '["7","3","5","6"]', '5', 'Subtracting gives 21 - 16 = 5°C.', 'EASY', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:57.167Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1335, 29, 'TEXT', 'A survey was recorded using tally marks: Red: IIII/ IIII/ I I Blue: IIII/ I Green: IIII/ IIII/ IIII/ What fraction of the total votes did Red receive? Give your answer as a fraction in its simplest possible whole-number ratio form (votes : total).', NULL, '["12 : 34","13 : 33","11 : 33","12 : 33"]', '12 : 33', NULL, 'HARD', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:20:57.171Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5335, 10, 'TEXT', 'Determine the percentage value of the fraction 7/36. (Hint: Convert to percentage)', NULL, '["29.44%","17.44%","19.44%","24.44%"]', '19.44%', '7/36 as a percentage is 19.44%.', 'EASY', 1, TRUE, '2026-07-11T13:34:31.832Z', '2026-07-18T06:20:53.297Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4404, 13, 'TEXT', 'Decrease £460 by 15%.', NULL, '["£414.00","£368.00","£460","£391.00"]', '£391.00', '15% of £460 is £69. Subtracting gives £391.00.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:20:54.814Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4469, 13, 'TEXT', 'A ticket price was increased by 25% to £1962.50. What was the original price?', NULL, '["£1580.00","£100.00","£1560.00","£1570.00"]', '£1570.00', 'Original Price = £1962.50 ÷ 1.25 = £1570.00.', 'HARD', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:20:54.815Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2280, 29, 'TEXT', 'Solve: (<s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> | + <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> |||) - <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s>', NULL, '["146","148","144","142"]', '144', '141 + 143 - 140 equals 144.', 'HARD', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:57.174Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4187, 28, 'TEXT', 'A bicycle was bought for £435 and sold for £348. What is the percentage loss?', NULL, '["15%","10%","25%","20%"]', '20%', 'Loss is £87. Percentage loss = (87 / 435) × 100 = 20%.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:20:58.347Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (350, 6, 'TEXT', 'If a = 5, find the value of a² - 2a + 1, and explain what special form this represents.', NULL, '["26, which is (a+1)²","14, no special form","16, which is (a-1)²","16, which is a²-1"]', '16, which is (a-1)²', NULL, 'HARD', 1, TRUE, '2026-07-11T13:22:05.141Z', '2026-07-18T06:20:59.347Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2919, 6, 'TEXT', 'Solve for x: 2x + 9 = 13', NULL, '["0","2","4","3"]', '2', 'Subtracting 9 gives 2x = 4. Dividing by 2 gives x = 2.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:59.348Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6308, 26, 'TEXT', 'If 4 workers take 3 days to construct a brick frame, how long will it take 6 workers to do same work? (Variation: 168)', NULL, '["2.0 days","3.5 days","4.0 days","2.0 days_alt_1"]', '2.0 days', 'Man-days = 4 * 3 = 12. 6 workers need 12 ÷ 6 = 2.0 days.', 'HARD', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:21:00.400Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6337, 26, 'TEXT', 'If 4 workers take 3 days to construct a brick frame, how long will it take 6 workers to do same work? (Variation: 197)', NULL, '["2.0 days","4.0 days","3.5 days","2.0 days_alt_1"]', '2.0 days', 'Man-days = 4 * 3 = 12. 6 workers need 12 ÷ 6 = 2.0 days.', 'HARD', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:21:00.401Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2666, 7, 'TEXT', 'A shopkeeper sells notebooks for £110 each and pens for £2 each. What is the total cost (C) of n notebooks and p pens?', NULL, '["C = 110n + 2p","C = 112(n + p)","C = 110np","C = 2n + 110p"]', 'C = 110n + 2p', 'notebooks cost 110n, pens cost 2p. The sum is 110n + 2p.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:21:01.380Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1100, 27, 'TEXT', 'A teacher is 24 years older than a pupil. In 4 years, the teacher will be 3 times the pupil''s age. How old is the pupil now?', NULL, '["10","8","12","6"]', '10', NULL, 'MEDIUM', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:21:01.383Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6395, 27, 'TEXT', 'A mother is five times as old as her daughter. If their combined age is 48, how old is the daughter? (Variation: 127)', NULL, '["8","7","11","10"]', '8', 'd + 5d = 6d = 48. Daughter is 8.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:21:01.384Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3077, 12, 'TEXT', 'Find 10% of £1120', NULL, '["£56","£112","£168","£224"]', '£112', '10% of £1120 is 10/100 × 1120 = £112.', 'EASY', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:52.278Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3151, 12, 'TEXT', 'If 15% of a number is 1560, what is 100% of the number?', NULL, '["10450","10300","10350","10400"]', '10400', 'Since 15% is 1560, 1% is 104. Thus 100% is 10400 = 10400.', 'HARD', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:53.291Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3816, 30, 'TEXT', 'In a leap year, if February 27th is a Tuesday, what day of the week will March 4th be?', NULL, '["Saturday","Sunday","Monday","Tuesday"]', 'Monday', 'Leap year has 29 days in Feb. Add 6 days to Feb 27th to land on March 4th.', 'HARD', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:54.816Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2351, 32, 'TEXT', 'A jug contains 124 L of juice. If you pour out 300 mL, how much juice remains in mL?', NULL, '["123600 mL","123700 mL","123800 mL","123900 mL"]', '123700 mL', '124 L is 124000 mL. Subtracting 300 mL leaves 123700 mL.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:56.114Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1238, 31, 'TEXT', 'The temperature is 11°C. It rises by 4°C. What is the new temperature?', NULL, '["7°C","16°C","15°C","14°C"]', '15°C', NULL, 'EASY', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:20:56.116Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3633, 31, 'TEXT', 'The temperature rises from 17°C to 22°C. What is the increase in degrees Celsius?', NULL, '["5","7","6","3"]', '5', 'Subtracting gives 22 - 17 = 5°C.', 'EASY', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:57.168Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3739, 31, 'TEXT', 'Find the average temperature of: 18°C, 25°C, 14°C, and -25°C.', NULL, '["7°C","8°C","9.5°C","8.5°C"]', '8°C', 'Sum of temperatures is 32. Dividing by 4 gives 8.0°C.', 'HARD', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:57.171Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2236, 29, 'TEXT', 'Calculate the sum represented by: <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> || + <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> |', NULL, '["200","193","198","203"]', '198', '97 + 101 equals 198.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:57.173Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1117, 28, 'TEXT', 'Goods worth £600 are sold at a 5% loss. What is the selling price?', NULL, '["£570","£560","£580","£575"]', '£570', NULL, 'MEDIUM', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:20:58.343Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4152, 28, 'TEXT', 'A bicycle was bought for £260 and sold for £208. What is the percentage loss?', NULL, '["20%","25%","15%","10%"]', '20%', 'Loss is £52. Percentage loss = (52 / 260) × 100 = 20%.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:20:58.345Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (190, 4, 'TEXT', 'A shop in France prices an item at €189.99. VAT in France is 20%. If £1 = €1.17, what is the pre-VAT price in pounds?', NULL, '["£175.00","£130.50","£162.39","£135.90"]', '£135.90', NULL, 'HARD', 1, TRUE, '2026-07-11T13:20:31.856Z', '2026-07-18T06:20:58.345Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (315, 6, 'TEXT', 'Tickets cost £p each. A group buys 5 tickets and gets a £3 discount, paying £22 total. Write an equation and find p.', NULL, '["5p + 3 = 22, p = 3.8","5(p-3) = 22, p = 7.4","5p - 3 = 22, p = 5","p - 3 = 22, p = 25"]', '5p - 3 = 22, p = 5', NULL, 'MEDIUM', 1, TRUE, '2026-07-11T13:21:44.898Z', '2026-07-18T06:20:59.347Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6317, 26, 'TEXT', 'If 4 workers take 3 days to construct a brick frame, how long will it take 6 workers to do same work? (Variation: 177)', NULL, '["2.0 days_alt_1","4.0 days","3.5 days","2.0 days"]', '2.0 days', 'Man-days = 4 * 3 = 12. 6 workers need 12 ÷ 6 = 2.0 days.', 'HARD', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:21:00.400Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2578, 7, 'TEXT', 'A number x is multiplied by 22 and then increased by 7. Which formula represents this statement?', NULL, '["x + 29","22x - 7","22x + 7","22(x + 7)"]', '22x + 7', 'Multiplying x by 22 gives 22x. Increasing by 7 gives 22x + 7.', 'EASY', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:21:00.402Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2682, 7, 'TEXT', 'A shopkeeper sells notebooks for £126 each and pens for £2 each. What is the total cost (C) of n notebooks and p pens?', NULL, '["C = 126n + 2p","C = 128(n + p)","C = 126np","C = 2n + 126p"]', 'C = 126n + 2p', 'notebooks cost 126n, pens cost 2p. The sum is 126n + 2p.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:21:01.380Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3114, 12, 'TEXT', 'Find 35% of £1860', NULL, '["£465","£744","£651","£558"]', '£651', '35% of £1860 is 35/100 × 1860 = £651.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:53.290Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3773, 30, 'TEXT', 'If today is Wednesday, what day of the week will it be in 10 days?', NULL, '["Friday","Sunday","Saturday","Monday"]', 'Saturday', '10 days after Wednesday is Saturday.', 'EASY', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:54.816Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6475, 30, 'TEXT', 'If the 4th of a month is a Thursday, what date will the fourth Thursday of that month be? (Variation: 116)', NULL, '["24th","25th","26th","18th"]', '25th', 'Suns/Days fall on 4th, 11th, 18th, 25th.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:20:54.817Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6536, 30, 'TEXT', 'Assuming a non-leap year, if February 28th is a Tuesday, what day of the week will March 4th be? (Variation: 177)', NULL, '["Saturday","Friday","Sunday","Saturday_alt_1"]', 'Saturday', 'Feb 28 is the last day of Feb. Adding 4 days gives March 4th, which lands on Saturday.', 'HARD', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:20:56.112Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1248, 31, 'TEXT', 'Which of these three temperatures is the coldest: 3°C, 4°C, 17°C?', NULL, '["17°C","They are all the same","4°C","3°C"]', '3°C', NULL, 'EASY', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:20:56.116Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3607, 31, 'TEXT', 'The temperature rises from 6°C to 9°C. What is the increase in degrees Celsius?', NULL, '["3","4","1","5"]', '3', 'Subtracting gives 9 - 6 = 3°C.', 'EASY', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:57.167Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1212, 29, 'TEXT', 'When the number 21 is shown as tally marks, how many single (leftover) marks are there after the full groups of five?', NULL, '["4","2","1","3"]', '1', NULL, 'EASY', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:20:57.171Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4167, 28, 'TEXT', 'A bicycle was bought for £335 and sold for £268. What is the percentage loss?', NULL, '["25%","20%","10%","15%"]', '20%', 'Loss is £67. Percentage loss = (67 / 335) × 100 = 20%.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:20:58.345Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4232, 28, 'TEXT', 'By selling a book for £792.00, a bookshop makes a 20% profit. What was the origin cost price of the book?', NULL, '["£665","£655","£660","£650"]', '£660', 'Cost Price = Selling Price ÷ 1.20 = £792.00 ÷ 1.20 = £660.', 'HARD', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:20:59.344Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3014, 26, 'TEXT', 'Sarah has 4 packs of pencils. Each pack has 57 pencils. She gives 3 pencils to her brother. How many does she have left?', NULL, '["225","221","229","223"]', '225', 'Total pencils is 4 × 57 = 228. Subtracting 3 leaves 225.', 'EASY', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:21:00.400Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6452, 27, 'TEXT', 'A father is 38 years old and his son is 12 years old. After how many years will father be twice as old as the son? (Variation: 184)', NULL, '["16","14","15","13"]', '14', '38 + x = 2*(12 + x). Solving yields x = 14.', 'HARD', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:21:01.385Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4453, 13, 'TEXT', 'A ticket price was increased by 25% to £1762.50. What was the original price?', NULL, '["£100.00","£1400.00","£1410.00","£1420.00"]', '£1410.00', 'Original Price = £1762.50 ÷ 1.25 = £1410.00.', 'HARD', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:20:54.815Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1346, 30, 'TEXT', 'How many days are there from 20 September to 5 October (counting forward, not including 20 September itself)?', NULL, '["16","15","14","22"]', '15', NULL, 'HARD', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:20:54.816Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3811, 30, 'TEXT', 'In a leap year, if February 27th is a Thursday, what day of the week will March 4th be?', NULL, '["Monday","Thursday","Tuesday","Wednesday"]', 'Wednesday', 'Leap year has 29 days in Feb. Add 6 days to Feb 27th to land on March 4th.', 'HARD', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:54.816Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1320, 32, 'TEXT', 'A container has 5000 ml of juice. 1500 ml is poured out. How much juice is left in the container?', NULL, '["3500 ml","3400 ml","3600 ml","5000 ml"]', '3500 ml', NULL, 'MEDIUM', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:20:56.113Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2442, 32, 'TEXT', 'A large flask has a capacity of 306 L. How many full cups of 250 mL can be filled from this flask?', NULL, '["1222","1228","1226","1224"]', '1224', '306 L = 306000 mL. 306000 ÷ 250 = 1224 cups.', 'HARD', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:56.116Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3657, 31, 'TEXT', 'The temperature was 11°C and fell by 27°C. What is the new temperature?', NULL, '["-20°C","-16°C","-15°C","-18°C"]', '-16°C', '11 - 27 = -16°C.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:57.168Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2148, 29, 'TEXT', 'What number is represented by these tally marks? <s>||||</s> ||||', NULL, '["8","11","10","9"]', '9', 'Counting each group of 5 (<s>||||</s>) and individual marks (|) gives 9.', 'EASY', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:57.172Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6312, 26, 'TEXT', 'If 4 workers take 3 days to construct a brick frame, how long will it take 6 workers to do same work? (Variation: 172)', NULL, '["2.0 days_alt_1","3.5 days","4.0 days","2.0 days"]', '2.0 days', 'Man-days = 4 * 3 = 12. 6 workers need 12 ÷ 6 = 2.0 days.', 'HARD', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:21:00.400Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2559, 7, 'TEXT', 'A number x is multiplied by 3 and then increased by 7. Which formula represents this statement?', NULL, '["3(x + 7)","3x + 7","x + 10","3x - 7"]', '3x + 7', 'Multiplying x by 3 gives 3x. Increasing by 7 gives 3x + 7.', 'EASY', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:21:00.402Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2672, 7, 'TEXT', 'A shopkeeper sells notebooks for £116 each and pens for £2 each. What is the total cost (C) of n notebooks and p pens?', NULL, '["C = 2n + 116p","C = 118(n + p)","C = 116np","C = 116n + 2p"]', 'C = 116n + 2p', 'notebooks cost 116n, pens cost 2p. The sum is 116n + 2p.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:21:01.380Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2741, 7, 'TEXT', 'Two times a number x is subtracted from the square of y, and the result is divided by 185. Write the formula.', NULL, '["(2x - y²) / 185","(y - 2x)² / 185","(y² - x) / 185","(y² - 2x) / 185"]', '(y² - 2x) / 185', 'Subtracting 2x from y² gives y² - 2x. Dividing by 185 gives (y² - 2x) / 185.', 'HARD', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:21:01.383Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3807, 30, 'TEXT', 'If the 5th of a month is a Friday, what date will the fourth Friday of the month be?', NULL, '["19th","25th","26th","27th"]', '26th', 'First is 5th, second is 12th, third is 19th, fourth is 26th.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:54.816Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6503, 30, 'TEXT', 'If the 4th of a month is a Thursday, what date will the fourth Thursday of that month be? (Variation: 144)', NULL, '["18th","25th","24th","26th"]', '25th', 'Suns/Days fall on 4th, 11th, 18th, 25th.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:20:56.111Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2387, 32, 'TEXT', 'A jug contains 196 L of juice. If you pour out 450 mL, how much juice remains in mL?', NULL, '["195750 mL","195650 mL","195550 mL","195450 mL"]', '195550 mL', '196 L is 196000 mL. Subtracting 450 mL leaves 195550 mL.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:56.115Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3702, 31, 'TEXT', 'The temperature was 11°C and fell by 24°C. What is the new temperature?', NULL, '["-13°C","-17°C","-15°C","-12°C"]', '-13°C', '11 - 24 = -13°C.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:57.169Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4121, 28, 'TEXT', 'A toy is bought for £105 and sold for £114. What is the profit?', NULL, '["£10","£2","£8","£9"]', '£9', 'Profit = Selling Price - Cost Price = £114 - £105 = £9.', 'EASY', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:20:58.344Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4151, 28, 'TEXT', 'A toy is bought for £255 and sold for £264. What is the profit?', NULL, '["£8","£10","£9","£2"]', '£9', 'Profit = Selling Price - Cost Price = £264 - £255 = £9.', 'EASY', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:20:58.345Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (299, 6, 'TEXT', 'Solve: 4x + 7 = 3x + 12.', NULL, '["x = 19","x = 1","x = -5","x = 5"]', 'x = 5', NULL, 'MEDIUM', 1, TRUE, '2026-07-11T13:21:35.444Z', '2026-07-18T06:20:59.346Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2880, 6, 'TEXT', 'Solve for x: x + 5 = 8', NULL, '["2","4","5","3"]', '3', 'Subtracting 5 from both sides gives x = 3.', 'EASY', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:59.347Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2992, 26, 'TEXT', 'Sarah has 4 packs of pencils. Each pack has 35 pencils. She gives 3 pencils to her brother. How many does she have left?', NULL, '["133","141","137","135"]', '137', 'Total pencils is 4 × 35 = 140. Subtracting 3 leaves 137.', 'EASY', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:21:00.399Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2360, 32, 'TEXT', 'A jug contains 142 L of juice. If you pour out 150 mL, how much juice remains in mL?', NULL, '["141750 mL","142050 mL","141950 mL","141850 mL"]', '141850 mL', '142 L is 142000 mL. Subtracting 150 mL leaves 141850 mL.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:56.114Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1249, 31, 'TEXT', 'Which temperature is warmer: 13°C or -9°C?', NULL, '["-9°C","13°C","They are the same","14°C"]', '13°C', NULL, 'EASY', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:20:56.116Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1264, 29, 'TEXT', 'A survey was recorded using tally marks: Football: IIII/ IIII/ I I I I Tennis: IIII/ IIII/ IIII/ Swimming: IIII/ IIII/ I I Which category received the most votes?', NULL, '["Swimming","None of these","Tennis","Football"]', 'Tennis', NULL, 'MEDIUM', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:20:57.171Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2176, 29, 'TEXT', 'What number is represented by these tally marks? <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> ||', NULL, '["36","38","37","39"]', '37', 'Counting each group of 5 (<s>||||</s>) and individual marks (|) gives 37.', 'EASY', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:57.172Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2248, 29, 'TEXT', 'Solve: (<s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> |||| + <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> |) - <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> |||', NULL, '["114","110","116","112"]', '112', '109 + 111 - 108 equals 112.', 'HARD', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:57.173Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (184, 4, 'TEXT', '£1 = $1.26. A US company charges $3,150. What is the cost in pounds, to the nearest pound?', NULL, '["£2,350","£2,450","£2,400","£2,500"]', '£2,500', NULL, 'HARD', 1, TRUE, '2026-07-11T13:20:28.281Z', '2026-07-18T06:20:58.342Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4191, 28, 'TEXT', 'A bicycle was bought for £455 and sold for £364. What is the percentage loss?', NULL, '["10%","25%","15%","20%"]', '20%', 'Loss is £91. Percentage loss = (91 / 455) × 100 = 20%.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:20:58.347Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2912, 6, 'TEXT', 'Solve for x: 3x + 9 = 24', NULL, '["5","3","7","6"]', '5', 'Subtracting 9 gives 3x = 15. Dividing by 3 gives x = 5.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:59.348Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1146, 26, 'TEXT', 'Three taps fill a tank in 6, 8, and 12 hours. All three are opened. After 2 hours, the first tap is closed. How much longer to fill the tank?', NULL, '["105 min","120 min","80 min","90 min"]', '105 min', NULL, 'HARD', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:21:00.397Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6286, 26, 'TEXT', 'A car travels at a speed of 45 mph for 1.5 hours. What is the total distance traveled in miles? (Variation: 146)', NULL, '["90","72.5","67.5","57.5"]', '67.5', 'Distance = Speed × Time = 45 × 1.5 = 67.5 miles.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:21:00.400Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2563, 7, 'TEXT', 'A number x is multiplied by 7 and then increased by 7. Which formula represents this statement?', NULL, '["7x + 7","x + 14","7(x + 7)","7x - 7"]', '7x + 7', 'Multiplying x by 7 gives 7x. Increasing by 7 gives 7x + 7.', 'EASY', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:21:00.402Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2677, 7, 'TEXT', 'A shopkeeper sells notebooks for £121 each and pens for £2 each. What is the total cost (C) of n notebooks and p pens?', NULL, '["C = 123(n + p)","C = 121np","C = 121n + 2p","C = 2n + 121p"]', 'C = 121n + 2p', 'notebooks cost 121n, pens cost 2p. The sum is 121n + 2p.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:21:01.380Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2398, 32, 'TEXT', 'A large flask has a capacity of 218 L. How many full cups of 250 mL can be filled from this flask?', NULL, '["876","870","872","874"]', '872', '218 L = 218000 mL. 218000 ÷ 250 = 872 cups.', 'HARD', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:56.115Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3677, 31, 'TEXT', 'The temperature was 16°C and fell by 41°C. What is the new temperature?', NULL, '["-27°C","-24°C","-29°C","-25°C"]', '-25°C', '16 - 41 = -25°C.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:57.169Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3747, 31, 'TEXT', 'Find the average temperature of: 11°C, 18°C, 7°C, and -18°C.', NULL, '["3.5°C","6°C","5°C","4.5°C"]', '4.5°C', 'Sum of temperatures is 18. Dividing by 4 gives 4.5°C.', 'HARD', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:20:57.171Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2157, 29, 'TEXT', 'What number is represented by these tally marks? <s>||||</s> <s>||||</s> <s>||||</s> |||', NULL, '["20","18","19","17"]', '18', 'Counting each group of 5 (<s>||||</s>) and individual marks (|) gives 18.', 'EASY', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:57.172Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2225, 29, 'TEXT', 'Calculate the sum represented by: <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> | + <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s> <s>||||</s>', NULL, '["178","181","171","176"]', '176', '86 + 90 equals 176.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:57.173Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4154, 28, 'TEXT', 'A bicycle was bought for £270 and sold for £216. What is the percentage loss?', NULL, '["20%","25%","15%","10%"]', '20%', 'Loss is £54. Percentage loss = (54 / 270) × 100 = 20%.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:30.140Z', '2026-07-18T06:20:58.345Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (303, 6, 'TEXT', 'Solve: 5x + 2 = 3x + 14.', NULL, '["x = 16","x = 8","x = 12","x = 6"]', 'x = 6', NULL, 'MEDIUM', 1, TRUE, '2026-07-11T13:21:37.901Z', '2026-07-18T06:20:59.347Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2897, 6, 'TEXT', 'Solve for x: 4x + 8 = 48', NULL, '["11","10","8","12"]', '10', 'Subtracting 8 gives 4x = 40. Dividing by 4 gives x = 10.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:20:59.347Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2967, 26, 'TEXT', 'Sarah has 4 packs of pencils. Each pack has 10 pencils. She gives 3 pencils to her brother. How many does she have left?', NULL, '["41","35","37","33"]', '37', 'Total pencils is 4 × 10 = 40. Subtracting 3 leaves 37.', 'EASY', 1, TRUE, '2026-07-11T13:34:28.841Z', '2026-07-18T06:21:00.398Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6279, 26, 'TEXT', 'A car travels at a speed of 60 mph for 1.5 hours. What is the total distance traveled in miles? (Variation: 139)', NULL, '["90","120","80","95"]', '90', 'Distance = Speed × Time = 60 × 1.5 = 90 miles.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:21:00.400Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6330, 26, 'TEXT', 'If 4 workers take 3 days to construct a brick frame, how long will it take 6 workers to do same work? (Variation: 190)', NULL, '["2.0 days","2.0 days_alt_1","4.0 days","3.5 days"]', '2.0 days', 'Man-days = 4 * 3 = 12. 6 workers need 12 ÷ 6 = 2.0 days.', 'HARD', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:21:00.400Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2691, 7, 'TEXT', 'Two times a number x is subtracted from the square of y, and the result is divided by 135. Write the formula.', NULL, '["(y² - 2x) / 135","(y - 2x)² / 135","(2x - y²) / 135","(y² - x) / 135"]', '(y² - 2x) / 135', 'Subtracting 2x from y² gives y² - 2x. Dividing by 135 gives (y² - 2x) / 135.', 'HARD', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:21:01.381Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6409, 27, 'TEXT', 'A mother is five times as old as her daughter. If their combined age is 42, how old is the daughter? (Variation: 141)', NULL, '["10","6","7","9"]', '7', 'd + 5d = 6d = 42. Daughter is 7.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:21:01.384Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1138, 26, 'TEXT', 'A rope is cut such that the shorter piece is 2/3 of the longer. The total length is 60 cm. How long is the shorter piece?', NULL, '["24 cm","28 cm","22 cm","20 cm"]', '24 cm', NULL, 'HARD', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:21:00.397Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6334, 26, 'TEXT', 'If 4 workers take 3 days to construct a brick frame, how long will it take 6 workers to do same work? (Variation: 194)', NULL, '["2.0 days_alt_1","3.5 days","2.0 days","4.0 days"]', '2.0 days', 'Man-days = 4 * 3 = 12. 6 workers need 12 ÷ 6 = 2.0 days.', 'HARD', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:21:00.401Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2572, 7, 'TEXT', 'A number x is multiplied by 16 and then increased by 7. Which formula represents this statement?', NULL, '["16(x + 7)","16x - 7","x + 23","16x + 7"]', '16x + 7', 'Multiplying x by 16 gives 16x. Increasing by 7 gives 16x + 7.', 'EASY', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:21:00.402Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2653, 7, 'TEXT', 'A shopkeeper sells notebooks for £97 each and pens for £2 each. What is the total cost (C) of n notebooks and p pens?', NULL, '["C = 97n + 2p","C = 99(n + p)","C = 2n + 97p","C = 97np"]', 'C = 97n + 2p', 'notebooks cost 97n, pens cost 2p. The sum is 97n + 2p.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:21:01.379Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6370, 27, 'TEXT', 'Sarah is 8 years old. Her sister is 3 years younger. What will be the sum of their ages in 2 years? (Variation: 102)', NULL, '["18","15","13","17"]', '17', 'Sarah in 2 years: 10. Sister in 2 years: 7. Sum is 17.', 'EASY', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:21:01.384Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6463, 27, 'TEXT', 'A father is 26 years old and his son is 8 years old. After how many years will father be twice as old as the son? (Variation: 195)', NULL, '["11","12","9","10"]', '10', '26 + x = 2*(8 + x). Solving yields x = 10.', 'HARD', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:21:01.385Z') ON CONFLICT DO NOTHING;
