INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2687, 7, 'TEXT', 'Two times a number x is subtracted from the square of y, and the result is divided by 131. Write the formula.', NULL, '["(y² - x) / 131","(2x - y²) / 131","(y - 2x)² / 131","(y² - 2x) / 131"]', '(y² - 2x) / 131', 'Subtracting 2x from y² gives y² - 2x. Dividing by 131 gives (y² - 2x) / 131.', 'HARD', 1, TRUE, '2026-07-11T13:34:27.139Z', '2026-07-18T06:21:01.381Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1035, 27, 'TEXT', 'Leo is 3 times as old as his cat. The cat is 4. How old is Leo?', NULL, '["14","12","9","10"]', '12', NULL, 'EASY', 1, TRUE, '2026-07-11T13:34:25.213Z', '2026-07-18T06:21:01.382Z') ON CONFLICT DO NOTHING;
INSERT INTO "maths_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (6421, 27, 'TEXT', 'A mother is five times as old as her daughter. If their combined age is 54, how old is the daughter? (Variation: 153)', NULL, '["8","11","12","9"]', '9', 'd + 5d = 6d = 54. Daughter is 9.', 'MEDIUM', 1, TRUE, '2026-07-11T13:34:33.244Z', '2026-07-18T06:21:01.384Z') ON CONFLICT DO NOTHING;
