INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3061, 19, 'TEXT', '"___ is a beautiful flower." (a) It (b) He (c) She (d) They', NULL, '[]', '(a) It', NULL, 'EASY', 1, TRUE, '2026-07-16T09:24:20.344Z', '2026-07-16T09:24:20.344Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1906, 13, 'TEXT', 'Which sentence correctly uses speech marks for an exclamation that is a single word?', NULL, '["\"Wait!\" she cried.","\"Wait! she cried.\"","\"Wait!\" She cried.","\"Wait\"! she cried."]', 'A) "Wait!" she cried.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T07:49:09.327Z', '2026-07-16T07:49:09.327Z') ON CONFLICT DO NOTHING;
