INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1910, 13, 'TEXT', 'Which sentence correctly uses speech marks with a reporting clause that interrupts a word?', NULL, '["\"This is un\" he started \"believable.\"","\"This is un-\" he started, \"believable.\"","\"This is un-\" he started, \"Believable.\"","\"This is un-\" he started \"believable.\""]', 'B) "This is un-" he started, "believable."', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T07:49:09.943Z', '2026-07-16T07:49:09.943Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1911, 13, 'TEXT', 'Which sentence correctly uses speech marks for a paragraph of speech?', NULL, '["\"I have a dream,\" he said, \"i want to travel.\"","\"I have a dream,\" he said, \"I want to travel.\"","\"I have a dream\" he said. \"I want to travel.\"","\"I have a dream,\" he said. \"I want to travel.\""]', 'D) "I have a dream," he said. "I want to travel."', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T07:49:10.097Z', '2026-07-16T07:49:10.097Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1912, 13, 'TEXT', 'Which sentence correctly uses speech marks with a reporting clause that comes before a fragment?', NULL, '["He said, \"No way\".","He said, \"no way.\"","He said \"No way.\"","He said, \"No way.\""]', 'D) He said, "No way."', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T07:49:10.252Z', '2026-07-16T07:49:10.252Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1913, 13, 'TEXT', 'Which sentence correctly uses speech marks for a quote that is an imperative?', NULL, '["\"Sit down, said the teacher.\"","\"Sit down,\" said the teacher.","\"Sit down\" said the teacher.","\"Sit down,\" said the Teacher."]', 'B) "Sit down," said the teacher.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T07:49:10.408Z', '2026-07-16T07:49:10.408Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1914, 13, 'TEXT', 'Which sentence correctly uses speech marks for a question that has a reporting clause after?', NULL, '["\"Are you coming\" asked John?","\"Are you coming?\" asked John.","\"Are you coming\"? asked John.","\"Are you coming?\" asked john."]', 'B) "Are you coming?" asked John.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T07:49:10.563Z', '2026-07-16T07:49:10.563Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1915, 13, 'TEXT', 'Which sentence correctly uses speech marks for an exclamation that has a reporting clause after?', NULL, '["\"Help me!\" she cried.","\"Help me\"! she cried.","\"Help me!\" She cried.","\"Help me! she cried.\""]', 'A) "Help me!" she cried.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T07:49:10.719Z', '2026-07-16T07:49:10.719Z') ON CONFLICT DO NOTHING;
