INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1917, 13, 'TEXT', 'Which sentence correctly uses speech marks where the reporting clause is a noun phrase?', NULL, '["\"This is mine, my brother said.\"","\"This is mine\" my brother said.","\"This is mine,\" my brother said","\"This is mine,\" my brother said."]', 'D) "This is mine," my brother said.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T07:49:11.032Z', '2026-07-16T07:49:11.032Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1918, 13, 'TEXT', 'Which sentence correctly uses speech marks for a quote inside a question?', NULL, '["Did he say, \"I am coming\"?","Did he say, \"I am coming\"?","Did he say, \"I am coming?\"","Did he say, \"I am coming\"?"]', 'D) Did he say, "I am coming"?', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T07:49:11.186Z', '2026-07-16T07:49:11.186Z') ON CONFLICT DO NOTHING;
