INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1921, 13, 'TEXT', 'Which sentence correctly uses speech marks for a title of a short story?', NULL, '["I read The Necklace in class.","I read \"The Necklace\" in class.","I read \"The Necklace\" in class.","I read ''The Necklace\" in class."]', 'B) I read "The Necklace" in class.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T07:49:11.653Z', '2026-07-16T07:49:11.653Z') ON CONFLICT DO NOTHING;
