INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2233, 15, 'TEXT', 'Which word is a concrete noun?', NULL, '["freedom  b) happiness  c) apple  d) truth"]', 'c) apple', NULL, 'EASY', 1, TRUE, '2026-07-16T08:31:33.529Z', '2026-07-16T08:31:33.529Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1928, 13, 'TEXT', 'Which sentence correctly uses speech marks with a long reporting clause?', NULL, '["\"I don''t know, the tired old man replied slowly.\"","\"I don''t know,\" the tired old man replied slowly","\"I don''t know,\" the tired old man replied slowly.","\"I don''t know\" the tired old man replied slowly."]', 'C) "I don''t know," the tired old man replied slowly.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T07:49:12.734Z', '2026-07-16T07:49:12.734Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1929, 13, 'TEXT', 'Which sentence correctly uses speech marks for a quote that is a single word?', NULL, '["\"Go.\" he said.","\"Go, he said.\"","\"Go,\" he said.","\"Go\", he said."]', 'C) "Go," he said.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T07:49:12.889Z', '2026-07-16T07:49:12.889Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1930, 13, 'TEXT', 'Which sentence correctly uses speech marks for a direct quote of a rhetorical question?', NULL, '["\"Who knows\" she shrugged?","\"Who knows?\" She shrugged.","\"Who knows?\" she shrugged.","\"Who knows\"? she shrugged."]', 'C) "Who knows?" she shrugged.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T07:49:13.044Z', '2026-07-16T07:49:13.044Z') ON CONFLICT DO NOTHING;
