INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (1935, 13, 'TEXT', 'Which sentence correctly uses speech marks for a quote within a quote within a quote?', NULL, '["She said, ''He told me, \"She said, ''Hello.''\"\"","She said, \"He told me, ''She said, \"Hello.\"''\"","She said, \"He told me, ''She said, \"Hello.\"''\"","She said, \"He told me, \"She said, ''Hello.''\"\""]', 'C) She said, "He told me, ''She said, "Hello."''"', NULL, 'HARD', 1, TRUE, '2026-07-16T07:49:13.819Z', '2026-07-16T07:49:13.819Z') ON CONFLICT DO NOTHING;
