INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2699, 17, 'TEXT', 'Choose the correct order of adjectives: "He bought a ___ table."', NULL, '["round wooden small  b) wooden small round  c) wooden round small  d) small round wooden"]', 'd) small round wooden', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:06.434Z', '2026-07-16T08:43:06.434Z') ON CONFLICT DO NOTHING;
