INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2701, 17, 'TEXT', 'Identify the predicative adjective: "The soup is hot."', NULL, '["the  b) is  c) soup  d) hot"]', 'd) hot', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:06.832Z', '2026-07-16T08:43:06.832Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2702, 17, 'TEXT', 'Identify the attributive adjective: "The hot soup burned my tongue."', NULL, '["soup  b) tongue  c) burned  d) hot"]', 'd) hot', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:07.031Z', '2026-07-16T08:43:07.031Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2703, 17, 'TEXT', 'Which sentence uses an adjective attributively (before the noun)?', NULL, '["The tree fell tall.  b) The tall tree fell.  c) Tall, the tree fell.  d) The tree is tall."]', 'b) The tall tree fell.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:07.230Z', '2026-07-16T08:43:07.230Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2704, 17, 'TEXT', 'Which sentence uses an adjective predicatively (after a linking verb)?', NULL, '["A tall tree fell.  b) The tall tree fell.  c) The tree is tall.  d) The tall, old tree fell."]', 'c) The tree is tall.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:07.428Z', '2026-07-16T08:43:07.428Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2705, 17, 'TEXT', 'Choose the correct adjective form: "This is the ___ book I have ever read." (extreme, one of many)', NULL, '["interestingest  b) most interesting  c) interestinger  d) more interesting"]', 'b) most interesting', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:07.627Z', '2026-07-16T08:43:07.627Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2706, 17, 'TEXT', 'Choose the correct comparative structure using "as...as": "She is ___ tall as her brother."', NULL, '["most  b) more  c) so  d) as"]', 'd) as', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:07.828Z', '2026-07-16T08:43:07.828Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2707, 17, 'TEXT', 'Which sentence correctly uses "as...as" for equal comparison?', NULL, '["He is as strong than his father.  b) He is strong as than his father.  c) He is more strong as his father.  d) He is as strong as his father."]', 'd) He is as strong as his father.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:08.027Z', '2026-07-16T08:43:08.027Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2708, 17, 'TEXT', 'Which sentence correctly uses "not as...as" for a negative comparison?', NULL, '["She is not as fast than him.  b) She is not as fast as him.  c) She is not so fast than him.  d) She is not fast as him."]', 'b) She is not as fast as him.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:08.228Z', '2026-07-16T08:43:08.228Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2709, 17, 'TEXT', 'Choose the correct adjective: "The weather is getting ___ and ___." (progressive comparative)', NULL, '["colder and colder  b) cold and cold  c) coldest and coldest  d) more cold and more cold"]', 'a) colder and colder', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:08.429Z', '2026-07-16T08:43:08.429Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2710, 17, 'TEXT', 'Which sentence shows correct use of a progressive comparative?', NULL, '["The traffic is getting bad and bad.  b) The traffic is getting worse and worse.  c) The traffic is getting more bad and more bad.  d) The traffic is getting worst and worst."]', 'b) The traffic is getting worse and worse.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:08.631Z', '2026-07-16T08:43:08.631Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2711, 17, 'TEXT', 'Choose the correct structure: "The ___ you practise, the ___ you become." (parallel comparatives)', NULL, '["most, best  b) more, better  c) most, better  d) more, best"]', 'b) more, better', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:08.832Z', '2026-07-16T08:43:08.832Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2712, 17, 'TEXT', 'Identify the adjective that describes origin/nationality: "She bought an Italian handbag."', NULL, '["she  b) bought  c) handbag  d) Italian"]', 'd) Italian', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:09.030Z', '2026-07-16T08:43:09.030Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2713, 17, 'TEXT', 'Identify the adjective that describes material: "He wore a leather jacket."', NULL, '["leather  b) jacket  c) he  d) wore"]', 'a) leather', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:09.230Z', '2026-07-16T08:43:09.230Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2714, 17, 'TEXT', 'Identify the adjective that describes purpose: "She has a sewing machine."', NULL, '["she  b) has  c) machine  d) sewing"]', 'd) sewing', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:09.432Z', '2026-07-16T08:43:09.432Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2715, 17, 'TEXT', 'Which noun is being used as an adjective in: "The kitchen table wobbled."', NULL, '["kitchen  b) table  c) wobbled  d) the"]', 'a) kitchen', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:09.637Z', '2026-07-16T08:43:09.637Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2716, 17, 'TEXT', 'Choose the correct absolute adjective (usually not used in comparative/superlative form).', NULL, '["big  b) unique  c) tall  d) fast"]', 'b) unique', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:09.841Z', '2026-07-16T08:43:09.841Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2717, 17, 'TEXT', 'Which sentence contains a grammatical error with an absolute adjective?', NULL, '["This is the most unique painting I''ve seen.  b) This painting is rare.  c) This painting is unique.  d) This painting is quite unusual."]', 'a) This is the most unique painting I''ve seen.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:10.044Z', '2026-07-16T08:43:10.044Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2718, 17, 'TEXT', 'Choose the correct adjective form for "many" used with countable nouns.', NULL, '["many book  b) much books  c) much book  d) many books"]', 'd) many books', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:10.254Z', '2026-07-16T08:43:10.254Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2719, 17, 'TEXT', 'Choose the correct adjective form for "much" used with uncountable nouns.', NULL, '["many water  b) much water  c) much waters  d) many waters"]', 'b) much water', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:10.460Z', '2026-07-16T08:43:10.460Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2720, 17, 'TEXT', 'Which sentence correctly uses "fewer" with a countable noun?', NULL, '["There are fewer apples today.  b) There are less apples today.  c) There is less apples today.  d) There is fewer apples today."]', 'a) There are fewer apples today.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:10.663Z', '2026-07-16T08:43:10.663Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2721, 17, 'TEXT', 'Which sentence correctly uses "less" with an uncountable noun?', NULL, '["There are fewer sugar in this recipe.  b) There is fewer sugar in this recipe.  c) There are less sugar in this recipe.  d) There is less sugar in this recipe."]', 'd) There is less sugar in this recipe.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:10.865Z', '2026-07-16T08:43:10.865Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2722, 17, 'TEXT', 'Identify the adjective functioning as a noun complement: "The room felt empty."', NULL, '["room  b) empty  c) felt  d) the"]', 'b) empty', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:11.065Z', '2026-07-16T08:43:11.065Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2723, 17, 'TEXT', 'Identify the adjective describing emotion: "The frightened cat hid under the bed."', NULL, '["hid  b) cat  c) bed  d) frightened"]', 'd) frightened', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:11.272Z', '2026-07-16T08:43:11.272Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2724, 17, 'TEXT', 'Which sentence correctly places two coordinate adjectives with a comma?', NULL, '["It was a long tiring journey no comma needed here since they are cumulative.  b) It was a, long tiring journey.  c) It was a long, tiring journey.  d) It was a long tiring, journey."]', 'c) It was a long, tiring journey.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:11.473Z', '2026-07-16T08:43:11.473Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2725, 17, 'TEXT', 'Which sentence correctly places cumulative adjectives without a comma?', NULL, '["She bought two, small red bags.  b) She bought two small red bags.  c) She bought two, small, red bags.  d) She bought two small, red bags is also fully correct."]', 'b) She bought two small red bags.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:11.672Z', '2026-07-16T08:43:11.672Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2726, 17, 'TEXT', 'Choose the correct adjective: "It''s an ___ hour to travel." (referring to time of day, one syllable difference matters)', NULL, '["early  b) earlily  c) earliness  d) earlier only"]', 'a) early', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:11.876Z', '2026-07-16T08:43:11.876Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2727, 17, 'TEXT', 'Which sentence uses "enough" correctly as an adjective (before the noun)?', NULL, '["We have time enough only in poetic use commonly cited but standard is before.  b) We have a enough time.  c) We have times enough.  d) We have enough time."]', 'd) We have enough time.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:12.087Z', '2026-07-16T08:43:12.087Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2728, 17, 'TEXT', 'Choose the correct adjective: "This is a ___ problem to solve." (meaning very hard)', NULL, '["difficultly  b) difficulted  c) difficulty  d) difficult"]', 'd) difficult', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:12.288Z', '2026-07-16T08:43:12.288Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2729, 17, 'TEXT', 'Which sentence correctly uses an adjective after "seem"?', NULL, '["She seeming tired.  b) She seems tiredly.  c) She seem tired.  d) She seems tired."]', 'd) She seems tired.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:12.489Z', '2026-07-16T08:43:12.489Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2730, 17, 'TEXT', 'Which sentence correctly uses an adjective after "become"?', NULL, '["The sky become dark.  b) The sky became dark.  c) The sky becoming dark.  d) The sky became darkly."]', 'b) The sky became dark.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:12.686Z', '2026-07-16T08:43:12.686Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2731, 17, 'TEXT', 'Identify the adjective clause (relative clause functioning as an adjective): "The man who lives next door is a doctor."', NULL, '["is a doctor  b) the man  c) next door  d) who lives next door"]', 'd) who lives next door', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:12.885Z', '2026-07-16T08:43:12.885Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2732, 17, 'TEXT', 'Identify the adjective clause: "The book that I borrowed was excellent."', NULL, '["was excellent  b) the book  c) I borrowed  d) that I borrowed"]', 'd) that I borrowed', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:13.083Z', '2026-07-16T08:43:13.083Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2733, 17, 'TEXT', 'Which sentence uses an adjective phrase (a phrase functioning as an adjective)?', NULL, '["The girl smiled.  b) The girl in the red dress is my sister.  c) The girl ran quickly.  d) The girl is smiling."]', 'b) The girl in the red dress is my sister.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:13.280Z', '2026-07-16T08:43:13.280Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2734, 17, 'TEXT', 'Identify the adjective in a possessive-descriptive structure: "It was a two-hour delay."', NULL, '["delay  b) two-hour  c) was  d) it"]', 'b) two-hour', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:43:13.477Z', '2026-07-16T08:43:13.477Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2735, 17, 'TEXT', 'Identify the correct comparative structure in a formal context: "Of the two candidates, she is the ___ qualified."', NULL, '["most  b) more  c) much  d) very"]', 'b) more', NULL, 'HARD', 1, TRUE, '2026-07-16T08:43:13.673Z', '2026-07-16T08:43:13.673Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2736, 17, 'TEXT', 'Which sentence correctly uses a superlative among more than two items?', NULL, '["Of the three books, this is more interesting.  b) Of the three books, this is the most interesting.  c) Of the three books, this is interesting more.  d) Of the three books, this is the more interesting."]', 'b) Of the three books, this is the most interesting.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:43:13.873Z', '2026-07-16T08:43:13.873Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2737, 17, 'TEXT', 'Identify the correct adjective form: "This is by far the ___ solution." (emphatic superlative)', NULL, '["better  b) most good  c) best  d) good"]', 'c) best', NULL, 'HARD', 1, TRUE, '2026-07-16T08:43:14.069Z', '2026-07-16T08:43:14.069Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2738, 17, 'TEXT', 'Which sentence correctly uses an adjective with "too" to express excess?', NULL, '["The tea is so hot to drink.  b) The tea is too hot for drink.  c) The tea is hot too to drink.  d) The tea is too hot to drink."]', 'd) The tea is too hot to drink.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:43:14.268Z', '2026-07-16T08:43:14.268Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2739, 17, 'TEXT', 'Which sentence correctly uses an adjective with "enough" after the adjective?', NULL, '["The tea is enough cool to drink.  b) The tea enough is cool to drink.  c) The tea is cool enough to drink.  d) The tea is enough cool for drink."]', 'c) The tea is cool enough to drink.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:43:14.498Z', '2026-07-16T08:43:14.498Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2740, 17, 'TEXT', 'Identify the correct structure for a "so...that" clause: "It was ___ cold that we stayed inside."', NULL, '["too  b) such  c) very  d) so"]', 'd) so', NULL, 'HARD', 1, TRUE, '2026-07-16T08:43:14.695Z', '2026-07-16T08:43:14.695Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2741, 17, 'TEXT', 'Identify the correct structure for a "such...that" clause: "It was ___ a cold day that we stayed inside."', NULL, '["too  b) such  c) so  d) very"]', 'b) such', NULL, 'HARD', 1, TRUE, '2026-07-16T08:43:14.895Z', '2026-07-16T08:43:14.895Z') ON CONFLICT DO NOTHING;
