INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2919, 18, 'TEXT', 'Which word is an adverb showing manner formed from the adjective "gentle"?', NULL, '["gently  b) gentleness  c) gentler  d) gentlest"]', 'a) gently', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:47:38.691Z', '2026-07-16T08:47:38.691Z') ON CONFLICT DO NOTHING;
