INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2924, 18, 'TEXT', 'Identify the correct adverb: "She looked at him ___." (angrily)', NULL, '["angry  b) angrily  c) anger  d) angering"]', 'b) angrily', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:47:39.480Z', '2026-07-16T08:47:39.480Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2925, 18, 'TEXT', 'Identify the correct adverb: "He explained the rules ___." (clearly)', NULL, '["clear  b) clearly  c) clearness  d) clearing"]', 'b) clearly', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:47:39.633Z', '2026-07-16T08:47:39.633Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2926, 18, 'TEXT', 'Which sentence correctly places a mid-position adverb of frequency before the main verb?', NULL, '["She often visits her grandmother.  b) She visits often her grandmother.  c) Often she visits her grandmother is used for emphasis but less standard mid-position.  d) She visits her grandmother often is also correct, end position."]', 'a) She often visits her grandmother.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:47:39.786Z', '2026-07-16T08:47:39.786Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2927, 18, 'TEXT', 'Which sentence correctly places an adverb of frequency after the verb "to be"?', NULL, '["She is always late.  b) She always is late.  c) Always she is late.  d) She late is always."]', 'a) She is always late.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:47:39.938Z', '2026-07-16T08:47:39.938Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2928, 18, 'TEXT', 'Identify the correct adverb order when both manner and place are present: "She sang beautifully ___." (in the hall)', NULL, '["in the hall  b) the hall in  c) hall the in  d) in hall the"]', 'a) in the hall', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:47:40.092Z', '2026-07-16T08:47:40.092Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2929, 18, 'TEXT', 'Which sentence correctly follows the usual order: manner before place?', NULL, '["She danced gracefully on the stage.  b) She danced on the stage gracefully is also acceptable but less typical.  c) Gracefully she danced on the stage is for emphasis.  d) On the stage she danced gracefully is for emphasis too."]', 'a) She danced gracefully on the stage.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:47:40.244Z', '2026-07-16T08:47:40.244Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2930, 18, 'TEXT', 'Which sentence correctly follows the usual order: place before time?', NULL, '["They met at the park yesterday.  b) They met yesterday at the park is also correct but less typical default order.  c) At the park they met yesterday is for emphasis.  d) Yesterday at the park they met is for emphasis."]', 'a) They met at the park yesterday.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:47:40.397Z', '2026-07-16T08:47:40.397Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2931, 18, 'TEXT', 'Identify the adverb of manner in a sentence with multiple adverbials: "She spoke calmly at the meeting this morning."', NULL, '["calmly  b) at the meeting  c) this morning  d) she"]', 'a) calmly', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:47:40.550Z', '2026-07-16T08:47:40.550Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2932, 18, 'TEXT', 'Identify the adverb of place in: "She spoke calmly at the meeting this morning."', NULL, '["calmly  b) at the meeting  c) this morning  d) she"]', 'b) at the meeting', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:47:40.702Z', '2026-07-16T08:47:40.702Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2933, 18, 'TEXT', 'Identify the adverb of time in: "She spoke calmly at the meeting this morning."', NULL, '["calmly  b) at the meeting  c) this morning  d) she"]', 'c) this morning', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:47:40.855Z', '2026-07-16T08:47:40.855Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2934, 18, 'TEXT', 'Which sentence correctly uses an adverb to modify a whole clause showing the speaker''s viewpoint?', NULL, '["Surprisingly, he passed the test.  b) He passed surprisingly the test wrong placement.  c) He passed the test surprising incorrect form.  d) Surprising, he passed the test incorrect form."]', 'a) Surprisingly, he passed the test.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T08:47:41.008Z', '2026-07-16T08:47:41.008Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2935, 18, 'TEXT', 'Identify the correct comparative adverb structure in a formal register: "She performed ___ than her rivals."', NULL, '["more skilfully  b) most skilfully  c) skilfullier  d) skilfullest"]', 'a) more skilfully', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:41.161Z', '2026-07-16T08:47:41.161Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2936, 18, 'TEXT', 'Identify the correct superlative adverb structure: "Of all the athletes, he ran ___."', NULL, '["more fastest  b) fastest  c) most fast  d) more fast"]', 'b) fastest', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:41.314Z', '2026-07-16T08:47:41.314Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2937, 18, 'TEXT', 'Which sentence correctly distinguishes "hardly" as a negative adverb requiring no additional negation?', NULL, '["I hardly know him.  b) I don''t hardly know him.  c) I hardly don''t know him.  d) I hardly not know him."]', 'a) I hardly know him.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:41.467Z', '2026-07-16T08:47:41.467Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2938, 18, 'TEXT', 'Which sentence correctly uses "scarcely...when" as a formal time construction?', NULL, '["Scarcely had she arrived when the phone rang.  b) Scarcely she had arrived when the phone rang.  c) Scarcely did she arrive when the phone rang is less standard.  d) Scarcely she arrived when the phone rang."]', 'a) Scarcely had she arrived when the phone rang.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:41.626Z', '2026-07-16T08:47:41.626Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2939, 18, 'TEXT', 'Which sentence correctly uses "no sooner...than" with inversion?', NULL, '["No sooner had he sat down than the phone rang.  b) No sooner he had sat down than the phone rang.  c) No sooner did he sat down than the phone rang.  d) No sooner he sat down than the phone rang."]', 'a) No sooner had he sat down than the phone rang.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:41.779Z', '2026-07-16T08:47:41.779Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2940, 18, 'TEXT', 'Identify the correct adverb of degree distinguishing "fairly" (moderately) from "fair" (adjective meaning just): "The test was ___ difficult."', NULL, '["fair  b) fairly  c) fairness  d) fairest"]', 'b) fairly', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:41.931Z', '2026-07-16T08:47:41.931Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2941, 18, 'TEXT', 'Which sentence correctly uses the flat adverb "close" versus "closely" (with different meanings)?', NULL, '["Stay close to me.  b) Stay closely to me means the same thing.  c) Stay close to me is wrong, must be closely.  d) Stay closing to me."]', 'a) Stay close to me.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:42.084Z', '2026-07-16T08:47:42.084Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2942, 18, 'TEXT', 'Which sentence correctly uses "closely" to mean "carefully/attentively"?', NULL, '["She watched the process closely.  b) She watched the process close, meaning the same in formal writing.  c) She watched closely the process is also standard placement.  d) She closely watched process the."]', 'a) She watched the process closely.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:42.238Z', '2026-07-16T08:47:42.238Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2943, 18, 'TEXT', 'Which sentence correctly distinguishes "deep" (flat adverb, physical depth) from "deeply" (figurative, emotional)?', NULL, '["She was deeply moved by the film.  b) She was deep moved by the film.  c) She dug deeply into the ground meaning figurative here incorrectly.  d) She was moved deep by the film informal only."]', 'a) She was deeply moved by the film.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:42.394Z', '2026-07-16T08:47:42.394Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2944, 18, 'TEXT', 'Which sentence correctly uses "deep" as a flat adverb of physical depth?', NULL, '["He dug deep into the soil.  b) He dug deeply into the soil is wrong here.  c) He dug deepness into the soil.  d) He deep dug into the soil."]', 'a) He dug deep into the soil.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:42.549Z', '2026-07-16T08:47:42.549Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2945, 18, 'TEXT', 'Identify the correct sentence distinguishing "wide" (flat adverb) from "widely" (figurative, extensively)?', NULL, '["The window was wide open.  b) The window was widely open meaning the same.  c) His research is wide respected should be widely.  d) The window was opening wide incorrect form."]', 'a) The window was wide open.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:42.708Z', '2026-07-16T08:47:42.708Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2946, 18, 'TEXT', 'Which sentence correctly uses "widely" in a figurative sense?', NULL, '["His theories are widely respected.  b) His theories are wide respected.  c) His theories are respected wide.  d) His theories widely are respected is awkward word order."]', 'a) His theories are widely respected.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:42.861Z', '2026-07-16T08:47:42.861Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2947, 18, 'TEXT', 'Identify the correct sentence distinguishing "high" (flat adverb, physical height) from "highly" (figurative, degree)?', NULL, '["The bird flew high above the trees.  b) The bird flew highly above the trees.  c) The bird flew height above trees.  d) The bird high flew above the trees."]', 'a) The bird flew high above the trees.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:43.014Z', '2026-07-16T08:47:43.014Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2948, 18, 'TEXT', 'Which sentence correctly uses "highly" in a figurative sense of degree?', NULL, '["She is a highly qualified doctor.  b) She is a high qualified doctor.  c) She is qualified high doctor.  d) She is a doctor high qualified."]', 'a) She is a highly qualified doctor.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:43.168Z', '2026-07-16T08:47:43.168Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2949, 18, 'TEXT', 'Which sentence correctly distinguishes "near" (flat adverb of place) from "nearly" (meaning almost)?', NULL, '["He lives near the station.  b) He lives nearly the station meaning the same.  c) He nearly lives the station.  d) He lives station near incorrect order."]', 'a) He lives near the station.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:43.321Z', '2026-07-16T08:47:43.321Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2950, 18, 'TEXT', 'Which sentence correctly uses "nearly" to mean "almost"?', NULL, '["She nearly missed the train.  b) She near missed the train meaning the same.  c) She missed nearly the train awkward.  d) She missed the train near."]', 'a) She nearly missed the train.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:43.474Z', '2026-07-16T08:47:43.474Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2951, 18, 'TEXT', 'Identify the correct adverb order describing manner, place, and frequency in a single complex sentence: "He drives ___ ___ ___." (carefully / on the motorway / every day)', NULL, '["carefully on the motorway every day  b) every day carefully on the motorway  c) on the motorway every day carefully  d) every day on the motorway carefully"]', 'a) carefully on the motorway every day', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:43.627Z', '2026-07-16T08:47:43.627Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2952, 18, 'TEXT', 'Which sentence correctly places a sentence adverb of viewpoint at the beginning for emphasis?', NULL, '["Frankly, I don''t agree with the decision.  b) I frankly don''t agree with the decision only mid-position, less emphatic.  c) I don''t agree with the decision frankly, ambiguous placement.  d) Frank, I don''t agree with the decision, wrong form."]', 'a) Frankly, I don''t agree with the decision.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:43.784Z', '2026-07-16T08:47:43.784Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2953, 18, 'TEXT', 'Which sentence correctly uses a viewpoint adverb "personally" to introduce an opinion?', NULL, '["Personally, I think the plan is flawed.  b) I personally think the plan is flawed is also correct, mid-position.  c) The plan personally is flawed I think, awkward.  d) I think personally the plan flawed is, wrong order."]', 'a) Personally, I think the plan is flawed.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:43.942Z', '2026-07-16T08:47:43.942Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2954, 18, 'TEXT', 'Identify the correct focus adverb placement to emphasise "even the smallest detail": "___ the smallest detail mattered to her."', NULL, '["Even  b) Only  c) Just  d) All of these could work depending on context, but \"even\" best fits emphasis on extremity"]', 'd) All of these could work depending on context, but "even" best fits emphasis on extremity', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:44.096Z', '2026-07-16T08:47:44.096Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2955, 18, 'TEXT', 'Which sentence correctly uses "just" as a focusing adverb meaning "only/simply"?', NULL, '["I just wanted to help.  b) I wanted just to help, awkward placement.  c) Just I wanted to help, wrong order.  d) I wanted to help just, wrong placement."]', 'a) I just wanted to help.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:44.256Z', '2026-07-16T08:47:44.256Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2956, 18, 'TEXT', 'Identify the correct adverb clause of reason introduced by "because": "She stayed home ___ she was ill."', NULL, '["because  b) although  c) unless  d) while"]', 'a) because', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:44.520Z', '2026-07-16T08:47:44.520Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2957, 18, 'TEXT', 'Identify the correct adverb clause of concession: "___ it was raining, they went for a walk."', NULL, '["Although  b) Because  c) Since  d) As"]', 'a) Although', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:44.684Z', '2026-07-16T08:47:44.684Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2958, 18, 'TEXT', 'Identify the correct adverb clause of condition: "___ you study hard, you will pass."', NULL, '["If  b) Although  c) Because  d) Whereas"]', 'a) If', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:44.840Z', '2026-07-16T08:47:44.840Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2959, 18, 'TEXT', 'Identify the correct adverb clause of contrast: "She is short, ___ her sister is tall."', NULL, '["whereas  b) because  c) if  d) since"]', 'a) whereas', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:44.996Z', '2026-07-16T08:47:44.996Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2960, 18, 'TEXT', 'Identify the correct adverb clause of purpose: "She studied hard ___ she could pass the exam."', NULL, '["so that  b) although  c) whereas  d) unless"]', 'a) so that', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:45.151Z', '2026-07-16T08:47:45.151Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2961, 18, 'TEXT', 'Identify the correct adverb clause of time: "She called me ___ she arrived."', NULL, '["as soon as  b) although  c) so that  d) unless"]', 'a) as soon as', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:45.304Z', '2026-07-16T08:47:45.304Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2962, 18, 'TEXT', 'Which sentence correctly uses an adverb clause reduced to a participial phrase?', NULL, '["Having finished her homework, she watched TV.  b) Finished her homework, she watched TV, incorrect participle form.  c) Having finish her homework, she watched TV, incorrect form.  d) Have finished her homework, she watched TV, incorrect form."]', 'a) Having finished her homework, she watched TV.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:45.456Z', '2026-07-16T08:47:45.456Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2963, 18, 'TEXT', 'Identify the correct use of "as" as a conjunctive/subordinating element introducing an adverb clause of time.', NULL, '["As the sun set, the sky turned orange.  b) As the sun setting, the sky turned orange.  c) As the sun sets it turned orange, tense mismatch.  d) As sun the set, the sky turned orange, wrong order."]', 'a) As the sun set, the sky turned orange.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:45.611Z', '2026-07-16T08:47:45.611Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2964, 18, 'TEXT', 'Choose the correct adverb intensifying an extreme/absolute adjective (not gradable, so avoid "very"): "The results were ___ perfect."', NULL, '["absolutely  b) very  c) quite (in the sense of ''somewhat'')  d) rather"]', 'a) absolutely', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:45.763Z', '2026-07-16T08:47:45.763Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3001, 19, 'TEXT', 'Choose the correct pronoun: "___ is my best friend." (a) Him (b) He (c) His (d) Her', NULL, '[]', '(b) He', NULL, 'EASY', 1, TRUE, '2026-07-16T09:24:10.773Z', '2026-07-16T09:24:10.773Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3002, 19, 'TEXT', 'Choose the correct pronoun: "___ went to the market." (a) Them (b) They (c) Their (d) Theirs', NULL, '[]', '(b) They', NULL, 'EASY', 1, TRUE, '2026-07-16T09:24:10.982Z', '2026-07-16T09:24:10.982Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2965, 18, 'TEXT', 'Which sentence correctly avoids the common error of intensifying an absolute adjective with "very"?', NULL, '["The evidence was completely conclusive.  b) The evidence was very conclusive, both are actually used but \"completely\" is more precise with absolute adjectives.  c) The evidence was very unique, incorrect usage.  d) The evidence was fairly unique, incorrect usage."]', 'c) The evidence was very unique, incorrect usage.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:45.916Z', '2026-07-16T08:47:45.916Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2966, 18, 'TEXT', 'Identify the correct downtoning (softening) adverb: "The film was ___ good, but not excellent."', NULL, '["rather  b) absolutely  c) completely  d) utterly"]', 'a) rather', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:46.068Z', '2026-07-16T08:47:46.068Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2967, 18, 'TEXT', 'Which sentence correctly uses "quite" to mean "fairly" (British usage, gradable adjective)?', NULL, '["The book was quite interesting.  b) The book was quite unique, less standard since unique is absolute.  c) The book was quite perfect, less standard.  d) The book was quite finished, less standard as an ungradable state."]', 'a) The book was quite interesting.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:46.220Z', '2026-07-16T08:47:46.220Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2968, 18, 'TEXT', 'Which sentence correctly uses "quite" to mean "completely" (with an absolute/ungradable adjective)?', NULL, '["I am quite certain about this.  b) I am quite tall about this, wrong pairing.  c) I am quite happy about this is gradable use, different sense.  d) I am quite big about this, wrong pairing."]', 'a) I am quite certain about this.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:46.373Z', '2026-07-16T08:47:46.373Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2969, 18, 'TEXT', 'Identify the correct adverb usage distinguishing "too" (excessive, negative) from "very" (neutral intensifier): "This coffee is ___ hot to drink."', NULL, '["too  b) very  c) so  d) quite"]', 'a) too', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:46.525Z', '2026-07-16T08:47:46.525Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2970, 18, 'TEXT', 'Which sentence correctly uses "enough" as a degree adverb placed after the adjective it modifies?', NULL, '["She is old enough to vote.  b) She is enough old to vote.  c) She is enough to vote old, wrong order.  d) She old enough is to vote, wrong order."]', 'a) She is old enough to vote.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:46.678Z', '2026-07-16T08:47:46.678Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2971, 18, 'TEXT', 'Identify the correct use of the adverb "indeed" for emphasis after an adjective: "The film was good, ___."', NULL, '["indeed  b) very  c) too  d) so"]', 'a) indeed', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:46.831Z', '2026-07-16T08:47:46.831Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2972, 18, 'TEXT', 'Which sentence correctly places the adverb "still" to indicate a continuing situation?', NULL, '["She still works at the hospital.  b) She works still at the hospital, awkward placement.  c) Still she works at the hospital, meaning emphasis/contrast, different nuance.  d) She works at the hospital still, less natural placement."]', 'a) She still works at the hospital.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:46.983Z', '2026-07-16T08:47:46.983Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2973, 18, 'TEXT', 'Which sentence correctly places "yet" in a negative sentence to mean "up to now"?', NULL, '["She hasn''t finished her homework yet.  b) She yet hasn''t finished her homework, unnatural placement.  c) Yet she hasn''t finished her homework, means something different, contrastive.  d) She hasn''t yet finished her homework is also correct mid-position with similar meaning."]', 'a) She hasn''t finished her homework yet.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:47.135Z', '2026-07-16T08:47:47.135Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2974, 18, 'TEXT', 'Identify the correct placement of "already" to indicate something happened before now, in an affirmative sentence.', NULL, '["She has already left.  b) She has left already is also correct, end position.  c) Already she has left, for emphasis, less common in standard prose.  d) All of the above are grammatically possible depending on emphasis"]', 'd) All of the above are grammatically possible depending on emphasis', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:47.289Z', '2026-07-16T08:47:47.289Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2975, 18, 'TEXT', 'Which sentence demonstrates the correct use of "so" as an intensifying adverb before an adjective?', NULL, '["The movie was so exciting!  b) The movie was such exciting, incorrect pairing.  c) The movie was so an exciting film, incorrect.  d) The movie so was exciting, wrong order."]', 'a) The movie was so exciting!', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:47.442Z', '2026-07-16T08:47:47.442Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2976, 18, 'TEXT', 'Which sentence correctly uses "such" before a noun phrase for emphasis (rather than "so")?', NULL, '["It was such an exciting movie!  b) It was so an exciting movie, incorrect.  c) It was such exciting movie, missing article.  d) It so was an exciting movie, wrong order."]', 'a) It was such an exciting movie!', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:47.594Z', '2026-07-16T08:47:47.594Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2977, 18, 'TEXT', 'Identify the correct adverb clause reduced with an -ing form showing simultaneous action: "___ walking home, she met an old friend."', NULL, '["While  b) Because  c) Although  d) Unless"]', 'a) While', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:47.749Z', '2026-07-16T08:47:47.749Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2978, 18, 'TEXT', 'Which sentence correctly uses "otherwise" as a conjunctive adverb showing consequence?', NULL, '["Hurry up, otherwise you''ll miss the bus.  b) Hurry up, however you''ll miss the bus, wrong connector for this meaning.  c) Hurry up, moreover you''ll miss the bus, wrong connector.  d) Hurry up, therefore you''ll miss the bus, less precise here."]', 'a) Hurry up, otherwise you''ll miss the bus.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:47.902Z', '2026-07-16T08:47:47.902Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2979, 18, 'TEXT', 'Which sentence correctly uses "nevertheless" as a conjunctive adverb showing contrast?', NULL, '["It was raining; nevertheless, they went hiking.  b) It was raining; therefore, they went hiking, wrong connector.  c) It was raining; moreover, they went hiking, wrong connector.  d) It was raining; consequently, they went hiking, wrong connector."]', 'a) It was raining; nevertheless, they went hiking.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:48.054Z', '2026-07-16T08:47:48.054Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2980, 18, 'TEXT', 'Which sentence correctly uses "furthermore" as a conjunctive adverb adding information?', NULL, '["The plan is cost-effective; furthermore, it is environmentally friendly.  b) The plan is cost-effective; however, it is environmentally friendly, wrong connector.  c) The plan is cost-effective; otherwise, it is environmentally friendly, wrong connector.  d) The plan is cost-effective; nevertheless, it is environmentally friendly, wrong connector."]', 'a) The plan is cost-effective; furthermore, it is environmentally friendly.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:48.206Z', '2026-07-16T08:47:48.206Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2981, 18, 'TEXT', 'Identify the correct punctuation with a conjunctive adverb joining two independent clauses.', NULL, '["She was tired; however, she kept working.  b) She was tired, however, she kept working, comma splice error.  c) She was tired however she kept working, missing punctuation.  d) She was tired; however she kept working, missing comma after however."]', 'a) She was tired; however, she kept working.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:48.359Z', '2026-07-16T08:47:48.359Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2982, 18, 'TEXT', 'Which sentence correctly uses the adverb "instead" to show substitution?', NULL, '["She didn''t go to the party; instead, she stayed home.  b) She didn''t go to the party; however, she stayed home, wrong connector.  c) She didn''t go to the party; therefore, she stayed home, wrong connector.  d) She didn''t go to the party; moreover, she stayed home, wrong connector."]', 'a) She didn''t go to the party; instead, she stayed home.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:48.512Z', '2026-07-16T08:47:48.512Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2983, 18, 'TEXT', 'Identify the correct adverb in a formal register meaning "in spite of this": "The team lost the match. ___, they remained optimistic."', NULL, '["Nonetheless  b) Moreover  c) Additionally  d) Consequently"]', 'a) Nonetheless', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:48.664Z', '2026-07-16T08:47:48.664Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3003, 19, 'TEXT', 'Fill in the blank: "This book is ___." (a) I (b) me (c) mine (d) my', NULL, '[]', '(c) mine', NULL, 'EASY', 1, TRUE, '2026-07-16T09:24:11.142Z', '2026-07-16T09:24:11.142Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3004, 19, 'TEXT', 'Choose the correct pronoun: "Give the ball to ___." (a) I (b) me (c) my (d) mine', NULL, '[]', '(b) me', NULL, 'EASY', 1, TRUE, '2026-07-16T09:24:11.300Z', '2026-07-16T09:24:11.300Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2984, 18, 'TEXT', 'Which sentence correctly uses "meanwhile" to show simultaneous events?', NULL, '["She cooked dinner; meanwhile, he set the table.  b) She cooked dinner; consequently, he set the table, wrong connector.  c) She cooked dinner; therefore, he set the table, wrong connector.  d) She cooked dinner; however, he set the table, wrong connector."]', 'a) She cooked dinner; meanwhile, he set the table.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:48.820Z', '2026-07-16T08:47:48.820Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2985, 18, 'TEXT', 'Identify the correct use of an adverb to modify a whole clause showing the manner in which something is stated: "Briefly, the project was a success."', NULL, '["Briefly  b) project  c) was  d) success"]', 'a) Briefly', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:48.973Z', '2026-07-16T08:47:48.973Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2986, 18, 'TEXT', 'Which sentence correctly distinguishes the adverb "presently" (soon, formal) from "currently" (now)?', NULL, '["The manager will be with you presently.  b) The manager is presently in a meeting, means the same as currently here in modern usage debated but traditionally \"presently\" means soon.  c) The manager will with you presently be, wrong order.  d) Presently manager will be with you, wrong order."]', 'a) The manager will be with you presently.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:49.127Z', '2026-07-16T08:47:49.127Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2987, 18, 'TEXT', 'Which sentence correctly uses the adverb "currently" to mean "at this time"?', NULL, '["She is currently studying for her exams.  b) She is presently studying for her exams meaning traditionally \"soon\" which is incorrect here.  c) She studying currently for her exams, wrong order.  d) Currently she is for her exams studying, wrong order."]', 'a) She is currently studying for her exams.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:49.280Z', '2026-07-16T08:47:49.280Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2988, 18, 'TEXT', 'Identify the correct use of the adverb "respectively" in a formal listing context: "John and Mary scored 90 and 85, ___."', NULL, '["respectively  b) individually  c) collectively  d) mutually"]', 'a) respectively', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:49.436Z', '2026-07-16T08:47:49.436Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2989, 18, 'TEXT', 'Which sentence demonstrates the correct formal use of the adverb "thereby" (meaning "by that means")?', NULL, '["She improved her diet, thereby boosting her energy levels.  b) She improved her diet, therefore boosting her energy levels, less formal/precise.  c) She improved her diet, moreover boosting her energy levels, wrong connector.  d) She improved her diet, however boosting her energy levels, wrong connector."]', 'a) She improved her diet, thereby boosting her energy levels.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:49.638Z', '2026-07-16T08:47:49.638Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2990, 18, 'TEXT', 'Identify the correct use of "hence" in formal academic writing to show a logical conclusion.', NULL, '["The data was inconclusive; hence, further research is needed.  b) The data was inconclusive; moreover, further research is needed, wrong connector.  c) The data was inconclusive; meanwhile, further research is needed, wrong connector.  d) The data was inconclusive; otherwise, further research is needed, wrong connector."]', 'a) The data was inconclusive; hence, further research is needed.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:49.794Z', '2026-07-16T08:47:49.794Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2991, 18, 'TEXT', 'Which sentence correctly uses the adverb "accordingly" to show a result following logically?', NULL, '["The rules changed; accordingly, the schedule was updated.  b) The rules changed; nevertheless, the schedule was updated, wrong connector.  c) The rules changed; meanwhile, the schedule was updated, wrong connector.  d) The rules changed; furthermore, the schedule was updated, wrong connector."]', 'a) The rules changed; accordingly, the schedule was updated.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:49.946Z', '2026-07-16T08:47:49.946Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2992, 18, 'TEXT', 'Identify the correct adverb clause of manner: "She behaved ___ her mother had taught her."', NULL, '["as  b) although  c) unless  d) so that"]', 'a) as', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:50.100Z', '2026-07-16T08:47:50.100Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2993, 18, 'TEXT', 'Which sentence correctly uses an adverb clause introduced by "provided that" to express condition?', NULL, '["You may leave early, provided that you finish your work.  b) You may leave early, although you finish your work, wrong connector.  c) You may leave early, because you finish your work, wrong connector.  d) You may leave early, so that you finish your work, wrong connector."]', 'a) You may leave early, provided that you finish your work.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:50.252Z', '2026-07-16T08:47:50.252Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2994, 18, 'TEXT', 'Identify the correct adverb clause introduced by "unless" to express a negative condition.', NULL, '["You won''t pass unless you study.  b) You won''t pass although you study, wrong connector for this meaning.  c) You won''t pass because you study, wrong connector.  d) You won''t pass provided you study, wrong connector for negative meaning."]', 'a) You won''t pass unless you study.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:50.407Z', '2026-07-16T08:47:50.407Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2995, 18, 'TEXT', 'Which sentence correctly reduces an adverb clause of time using a past participle?', NULL, '["Once completed, the report will be sent to the board.  b) Once completing, the report will be sent, incorrect participle.  c) Once complete the report, it will be sent, awkward.  d) Once to complete, the report will be sent, incorrect form."]', 'a) Once completed, the report will be sent to the board.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:50.561Z', '2026-07-16T08:47:50.561Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2996, 18, 'TEXT', 'Identify the correct formal adverb of degree describing a small amount: "The results were ___ different from expectations."', NULL, '["slightly  b) hugely  c) considerably  d) both a and c can describe degree, but \"slightly\" indicates a small amount specifically"]', 'd) both a and c can describe degree, but "slightly" indicates a small amount specifically', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:50.713Z', '2026-07-16T08:47:50.713Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2997, 18, 'TEXT', 'Which sentence correctly uses "considerably" to describe a large degree of difference?', NULL, '["Sales increased considerably this quarter.  b) Sales increased slightly, meaning a large amount incorrectly.  c) Sales considerably increased quarter this, wrong order.  d) Sales increased this considerably quarter, wrong order."]', 'a) Sales increased considerably this quarter.', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:50.866Z', '2026-07-16T08:47:50.866Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2998, 18, 'TEXT', 'Identify the correct viewpoint adverb showing the speaker evaluates something as lucky: "Luckily, the storm passed quickly."', NULL, '["Luckily  b) storm  c) passed  d) quickly"]', 'a) Luckily', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:51.019Z', '2026-07-16T08:47:51.019Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (2999, 18, 'TEXT', 'Which sentence correctly places two adverbials of different types without ambiguity: "She will meet him ___ ___." (at the station / at noon)', NULL, '["at the station at noon  b) at noon at the station, less natural but possible  c) at the at station noon, incorrect  d) noon at the station at, incorrect"]', 'a) at the station at noon', NULL, 'HARD', 1, TRUE, '2026-07-16T08:47:51.172Z', '2026-07-16T08:47:51.172Z') ON CONFLICT DO NOTHING;
