INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (3967, 23, 'TEXT', 'Which grammatical feature distinguishes an interjection from all other parts of speech in a sentence?', NULL, '["It does not have a grammatical relationship (like subject or object) with the rest of the sentence","It always functions as the subject of the sentence","It must always agree in number with the verb","It requires a direct object to complete its meaning"]', 'A. It does not have a grammatical relationship (like subject or object) with the rest of the sentence', NULL, 'HARD', 1, TRUE, '2026-07-16T09:40:21.113Z', '2026-07-16T09:40:21.113Z') ON CONFLICT DO NOTHING;
