INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4880, 28, 'TEXT', 'Which sentence uses correct inversion?', NULL, '["Only after the storm passed did we leave the shelter.","Did only after the storm passed we leave the shelter.","We only after the storm passed did leave the shelter.","Only after the storm passed we did leave the shelter."]', 'a) Only after the storm passed did we leave the shelter.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:51.962Z', '2026-07-16T11:18:51.962Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4881, 28, 'TEXT', 'Which sentence correctly places "only"?', NULL, '["Both a) and c) can be correct depending on meaning.","She only speaks French at home, not English.","Only she speaks French at home, not English.","She speaks only French at home, not English."]', 'a) Both a) and c) can be correct depending on meaning.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:52.119Z', '2026-07-16T11:18:52.119Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4882, 28, 'TEXT', 'Which sentence uses correct word order for the question tag?', NULL, '["You are coming, no?","You are coming, don''t you?","You are coming, aren''t you?","You are coming, isn''t it?"]', 'c) You are coming, aren''t you?', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:52.277Z', '2026-07-16T11:18:52.277Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4883, 28, 'TEXT', 'Which sentence is correctly ordered?', NULL, '["Hardly we had sat down when the fire alarm rang.","Had hardly we sat down when the fire alarm rang.","Hardly had we sat down when the fire alarm rang.","We hardly had sat down when the fire alarm rang."]', 'c) Hardly had we sat down when the fire alarm rang.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:52.434Z', '2026-07-16T11:18:52.434Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4884, 28, 'TEXT', 'Which sentence correctly places the phrase "in my opinion"?', NULL, '["The plan is flawed, in my opinion.","All of the above are correct.","In my opinion, the plan is flawed.","The plan, in my opinion, is flawed."]', 'b) All of the above are correct.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:52.591Z', '2026-07-16T11:18:52.591Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4885, 28, 'TEXT', 'Which sentence uses correct inversion?', NULL, '["The noise such was that no one could sleep.","Was such the noise that no one could sleep.","Such the noise was that no one could sleep.","Such was the noise that no one could sleep."]', 'd) Such was the noise that no one could sleep.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:52.745Z', '2026-07-16T11:18:52.745Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4886, 28, 'TEXT', 'Which sentence is correctly ordered?', NULL, '["Seldom I have seen such dedication among students.","I seldom have seen such dedication among students.","Have seldom I seen such dedication among students.","Seldom have I seen such dedication among students."]', 'd) Seldom have I seen such dedication among students.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:52.901Z', '2026-07-16T11:18:52.901Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4887, 28, 'TEXT', 'Which sentence correctly orders the indirect question?', NULL, '["I wonder what time is it.","I wonder what time it is.","I wonder is it what time.","I wonder it is what time."]', 'b) I wonder what time it is.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:53.056Z', '2026-07-16T11:18:53.056Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4888, 28, 'TEXT', 'Which sentence correctly places the negative adverbial for emphasis?', NULL, '["At no point did she consider giving up.","At no point she did consider giving up.","Did at no point she consider giving up.","She at no point did consider giving up."]', 'a) At no point did she consider giving up.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:53.213Z', '2026-07-16T11:18:53.213Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4889, 28, 'TEXT', 'Which sentence uses correct word order in reported speech?', NULL, '["She asked me I lived where.","She asked me where I lived.","She asked me where lived I.","She asked me where did I live."]', 'b) She asked me where I lived.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:53.367Z', '2026-07-16T11:18:53.367Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4890, 28, 'TEXT', 'Which sentence correctly places "even"?', NULL, '["The teacher even was surprised by the result.","Even the teacher was surprised by the result.","The teacher was surprised even by the result.","The even teacher was surprised by the result."]', 'b) Even the teacher was surprised by the result.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:53.576Z', '2026-07-16T11:18:53.576Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4891, 28, 'TEXT', 'Which sentence uses correct inversion after "so...that"?', NULL, '["So tired was he that he slept for twelve hours.","So he was tired that he slept for twelve hours.","So tired he was that he slept for twelve hours.","He was so tired that slept for twelve hours."]', 'a) So tired was he that he slept for twelve hours.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:53.736Z', '2026-07-16T11:18:53.736Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4892, 28, 'TEXT', 'Which sentence correctly places the relative clause?', NULL, '["The book which I borrowed from the library is overdue.","The book is overdue which I borrowed from the library.","Which I borrowed from the library, the book is overdue.","The book, overdue, which I borrowed from the library."]', 'a) The book which I borrowed from the library is overdue.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:53.893Z', '2026-07-16T11:18:53.893Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4893, 28, 'TEXT', 'Which sentence correctly uses cleft structure for emphasis?', NULL, '["It John was who broke the window.","It was John who broke the window.","John it was who broke the window.","Who broke the window it was John."]', 'b) It was John who broke the window.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:54.053Z', '2026-07-16T11:18:54.053Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4894, 28, 'TEXT', 'Which sentence is correctly ordered?', NULL, '["Not since the war prices have risen so quickly.","Have not since the war prices risen so quickly.","Prices not since the war have risen so quickly.","Not since the war have prices risen so quickly."]', 'd) Not since the war have prices risen so quickly.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:54.211Z', '2026-07-16T11:18:54.211Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4895, 28, 'TEXT', 'Which sentence correctly places the adverb "completely"?', NULL, '["She forgot completely about the meeting.","Completely she forgot about the meeting.","Both a) and b) are acceptable.","She completely forgot about the meeting."]', 'c) Both a) and b) are acceptable.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:54.424Z', '2026-07-16T11:18:54.424Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5201, 30, 'TEXT', 'Which sentence is more formal?', NULL, '["I apologise for the delay.","I''m sorry for the delay.","Sorry about the wait.","My bad for being late."]', 'a) I apologise for the delay.', NULL, 'EASY', 1, TRUE, '2026-07-16T11:30:59.925Z', '2026-07-16T11:30:59.925Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4896, 28, 'TEXT', 'Which sentence uses correct inversion?', NULL, '["Did not until the results came in she relax.","She not until the results came in did relax.","Not until the results came in she did relax.","Not until the results came in did she relax."]', 'd) Not until the results came in did she relax.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:54.579Z', '2026-07-16T11:18:54.579Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4897, 28, 'TEXT', 'Which sentence correctly orders the comparative structure?', NULL, '["Higher the mountain, colder it gets.","The mountain higher, the colder it gets.","The higher the mountain gets, the colder.","The higher the mountain, the colder it gets."]', 'd) The higher the mountain, the colder it gets.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:54.739Z', '2026-07-16T11:18:54.739Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4898, 28, 'TEXT', 'Which sentence correctly places "hardly...when"?', NULL, '["Hardly had the film started when the lights went out.","The film hardly had started when the lights went out.","Had hardly the film started when the lights went out.","Hardly the film had started when the lights went out."]', 'a) Hardly had the film started when the lights went out.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:54.894Z', '2026-07-16T11:18:54.894Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4899, 28, 'TEXT', 'Which sentence correctly places the participle phrase?', NULL, '["She, exhausted, fell from the journey asleep at once.","From the journey exhausted, she fell asleep at once and quick.","Exhausted from the journey, she fell asleep at once.","She fell asleep at once, exhausted from the journey she."]', 'c) Exhausted from the journey, she fell asleep at once.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:55.050Z', '2026-07-16T11:18:55.050Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4900, 28, 'TEXT', 'Which sentence correctly orders the sentence with "as well as"?', NULL, '["The manager was as well as his staff pleased with the results.","The manager, as well as his staff, was pleased with the results.","As well as his staff the manager was pleased with the results.","The manager, as well as his staff, were pleased with the results."]', 'b) The manager, as well as his staff, was pleased with the results.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:55.204Z', '2026-07-16T11:18:55.204Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4901, 28, 'TEXT', 'Which sentence correctly places the phrase "in the corner"?', NULL, '["Both a) and b) are correct.","In the corner of the room stood an old piano.","An old piano in the corner of the room stood.","An old piano stood in the corner of the room."]', 'a) Both a) and b) are correct.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:55.359Z', '2026-07-16T11:18:55.359Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4902, 28, 'TEXT', 'Which sentence uses correct inversion?', NULL, '["Never before the town had seen such devastation.","Had never before the town seen such devastation.","Never before had the town seen such devastation.","The town never before had seen such devastation."]', 'c) Never before had the town seen such devastation.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:55.515Z', '2026-07-16T11:18:55.515Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4903, 28, 'TEXT', 'Which sentence correctly places the modifying clause?', NULL, '["The house, which was built in 1800, is now a museum.","The house is now a museum, which was built in 1800.","Built in 1800, which the house is now a museum.","The house which is now a museum was built in 1800, museum."]', 'a) The house, which was built in 1800, is now a museum.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:55.671Z', '2026-07-16T11:18:55.671Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4904, 28, 'TEXT', 'Which sentence correctly orders the emphatic structure?', NULL, '["What she needs most is a good night''s sleep.","Most what she needs is a good night''s sleep.","She what needs most is a good night''s sleep.","What needs she most is a good night''s sleep."]', 'a) What she needs most is a good night''s sleep.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:55.830Z', '2026-07-16T11:18:55.830Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4905, 28, 'TEXT', 'Which sentence uses correct inversion?', NULL, '["Did only then I understand the true meaning.","Only then I did understand the true meaning.","Only then did I understand the true meaning.","I only then did understand the true meaning."]', 'c) Only then did I understand the true meaning.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:55.988Z', '2026-07-16T11:18:55.988Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4906, 28, 'TEXT', 'Which sentence correctly places the subordinate clause?', NULL, '["Although tired she was, she finished the race and won.","She was tired although, she finished the race.","She finished, although tired was she, the race.","Although she was tired, she finished the race."]', 'd) Although she was tired, she finished the race.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:56.145Z', '2026-07-16T11:18:56.145Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4907, 28, 'TEXT', 'Which sentence correctly orders the passive structure?', NULL, '["By her the letter was written last night.","Was the letter by her written last night.","The letter was written by her last night.","Last night by her was written the letter."]', 'c) The letter was written by her last night.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:56.301Z', '2026-07-16T11:18:56.301Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4908, 28, 'TEXT', 'Which sentence correctly places "such" for emphasis?', NULL, '["Was such her determination that nothing could stop her.","Her determination such was that nothing could stop her.","Such was her determination that nothing could stop her.","Such her determination was that nothing could stop her."]', 'c) Such was her determination that nothing could stop her.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:56.456Z', '2026-07-16T11:18:56.456Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4909, 28, 'TEXT', 'Which sentence correctly orders the reported question?', NULL, '["He asked whether had I finished my homework.","He asked whether I had finished my homework.","He asked whether finished I had my homework.","He asked I whether had finished my homework."]', 'b) He asked whether I had finished my homework.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:56.612Z', '2026-07-16T11:18:56.612Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4910, 28, 'TEXT', 'Which sentence uses correct inversion?', NULL, '["Not a single word he did say during the meeting.","Did not a single word he say during the meeting.","Not a single word did he say during the meeting.","He not a single word did say during the meeting."]', 'c) Not a single word did he say during the meeting.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:56.769Z', '2026-07-16T11:18:56.769Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4911, 28, 'TEXT', 'Which sentence correctly places the phrase for emphasis?', NULL, '["That matters most in life it is honesty.","It is honesty that matters most in life.","It honesty is that matters most in life.","Honesty it is that matters most in life."]', 'b) It is honesty that matters most in life.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:56.927Z', '2026-07-16T11:18:56.927Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4912, 28, 'TEXT', 'Which sentence correctly orders the concessive clause?', NULL, '["Much as I admire her, I disagree with her decision.","Admire her much as I, I disagree with her decision.","I admire her much as, I disagree with her decision.","As much I admire her, I disagree with her decision."]', 'a) Much as I admire her, I disagree with her decision.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:57.089Z', '2026-07-16T11:18:57.089Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4913, 28, 'TEXT', 'Which sentence uses correct inversion?', NULL, '["So great was the pressure that the pipe burst.","The pressure so great was that the pipe burst.","So the pressure was great that the pipe burst.","Was so great the pressure that the pipe burst."]', 'a) So great was the pressure that the pipe burst.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:57.245Z', '2026-07-16T11:18:57.245Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4914, 28, 'TEXT', 'Which sentence correctly places the appositive phrase?', NULL, '["Taught me to fly, my uncle, a retired pilot.","My uncle, a retired pilot, taught me to fly.","A retired pilot, my uncle taught me to fly.","My uncle taught me, a retired pilot, to fly."]', 'b) My uncle, a retired pilot, taught me to fly.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:57.401Z', '2026-07-16T11:18:57.401Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4915, 28, 'TEXT', 'Which sentence correctly orders the conditional inversion?', NULL, '["Known had I, I would have come earlier.","I had known, would have come earlier.","Had known I, I would have come earlier.","Had I known, I would have come earlier."]', 'd) Had I known, I would have come earlier.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:57.557Z', '2026-07-16T11:18:57.557Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4916, 28, 'TEXT', 'Which sentence correctly places "not only... but also"?', NULL, '["Not only she did win the race, but she also broke the record.","Did not only she win the race, but also broke the record.","Not only did she win the race, but she also broke the record.","She not only did win the race, but also broke the record."]', 'c) Not only did she win the race, but she also broke the record.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:57.713Z', '2026-07-16T11:18:57.713Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4917, 28, 'TEXT', 'Which sentence correctly places the introductory participle phrase?', NULL, '["Having finished her homework, she went out to play.","She having finished her homework went out to play.","Finished having her homework, she went out to play.","She went out to play, having finished her homework, quickly."]', 'a) Having finished her homework, she went out to play.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:57.869Z', '2026-07-16T11:18:57.869Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4918, 28, 'TEXT', 'Which sentence uses correct inversion?', NULL, '["Rarely does a day pass without complaint from him.","Does rarely a day pass without complaint from him.","A day rarely does pass without complaint from him.","Rarely a day does pass without complaint from him."]', 'a) Rarely does a day pass without complaint from him.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:58.043Z', '2026-07-16T11:18:58.043Z') ON CONFLICT DO NOTHING;
