INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4920, 28, 'TEXT', 'Which sentence correctly places the relative clause with a comma?', NULL, '["My sister is visiting next week, who lives in Leeds.","My sister, who lives in Leeds, is visiting next week.","Who lives in Leeds, my sister is visiting next week.","My sister who lives in Leeds is visiting, next week."]', 'b) My sister, who lives in Leeds, is visiting next week.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:58.357Z', '2026-07-16T11:18:58.357Z') ON CONFLICT DO NOTHING;
