INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4922, 28, 'TEXT', 'Which sentence correctly places the gerund phrase?', NULL, '["Her favourite pastime swimming in the lake is.","Swimming in the lake is her favourite pastime.","In the lake swimming is her favourite pastime.","Is swimming in the lake her favourite pastime."]', 'b) Swimming in the lake is her favourite pastime.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:58.674Z', '2026-07-16T11:18:58.674Z') ON CONFLICT DO NOTHING;
