INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4927, 28, 'TEXT', 'Which sentence uses correct inversion after a negative adverbial?', NULL, '["In no way he did intend to offend anyone.","In no way did he intend to offend anyone.","Did in no way he intend to offend anyone.","He in no way did intend to offend anyone."]', 'b) In no way did he intend to offend anyone.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:59.454Z', '2026-07-16T11:18:59.454Z') ON CONFLICT DO NOTHING;
