INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4929, 28, 'TEXT', 'Which sentence uses correct word order in the question?', NULL, '["Do you know where is the station?","Know you do where the station is?","Do you know where the station is?","You know where the station is?"]', 'c) Do you know where the station is?', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:18:59.770Z', '2026-07-16T11:18:59.770Z') ON CONFLICT DO NOTHING;
