INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4932, 28, 'TEXT', 'Which sentence uses correct inversion?', NULL, '["Not for a moment she did doubt his honesty.","Not for a moment did she doubt his honesty.","Did not for a moment she doubt his honesty.","She not for a moment did doubt his honesty."]', 'b) Not for a moment did she doubt his honesty.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:19:00.237Z', '2026-07-16T11:19:00.237Z') ON CONFLICT DO NOTHING;
