INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5259, 30, 'TEXT', 'Which sentence is informal?', NULL, '["I wish to bring to your attention.","FYI.","I want to highlight.","I''d like to point out."]', 'b) FYI.', NULL, 'EASY', 1, TRUE, '2026-07-16T11:31:08.847Z', '2026-07-16T11:31:08.847Z') ON CONFLICT DO NOTHING;
