INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4940, 28, 'TEXT', 'Which sentence uses correct inversion?', NULL, '["On no account should you reveal this secret.","On no account you should reveal this secret.","Should on no account you reveal this secret.","You should on no account reveal this secret and never."]', 'a) On no account should you reveal this secret.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:19:01.491Z', '2026-07-16T11:19:01.491Z') ON CONFLICT DO NOTHING;
