INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4952, 28, 'TEXT', 'Which sentence correctly orders the sentence with a fronted prepositional phrase and inversion?', NULL, '["A weathered stone bench beneath the old oak tree stood.","Stood beneath the old oak tree a weathered stone bench.","Beneath the old oak tree stood a weathered stone bench.","Beneath the old oak tree a weathered stone bench stood."]', 'c) Beneath the old oak tree stood a weathered stone bench.', NULL, 'HARD', 1, TRUE, '2026-07-16T11:19:03.470Z', '2026-07-16T11:19:03.470Z') ON CONFLICT DO NOTHING;
