INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4987, 28, 'TEXT', 'Which sentence correctly places the fronted concessive with "as" and inversion avoided?', NULL, '["Strange as it may seem, the theory was later proven correct.","It may seem strange as, the theory was later proven correct.","Strange it may as seem, the theory was later proven correct.","As strange it may seem, the theory was later proven correct."]', 'a) Strange as it may seem, the theory was later proven correct.', NULL, 'HARD', 1, TRUE, '2026-07-16T11:19:09.132Z', '2026-07-16T11:19:09.132Z') ON CONFLICT DO NOTHING;
