INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (4990, 28, 'TEXT', 'Which sentence correctly orders the sentence with a fronted causal clause and inversion?', NULL, '["So the demand was great that supplies quickly ran out.","So great was the demand that supplies quickly ran out.","The demand so great was that supplies quickly ran out.","Was so great the demand that supplies quickly ran out."]', 'b) So great was the demand that supplies quickly ran out.', NULL, 'HARD', 1, TRUE, '2026-07-16T11:19:09.597Z', '2026-07-16T11:19:09.597Z') ON CONFLICT DO NOTHING;
