INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5390, 30, 'TEXT', 'Which sentence is informal?', NULL, '["The company''s performance is going downhill.","The company''s performance is worsening.","The company''s performance has been declining.","The company''s performance has deteriorated."]', 'a) The company''s performance is going downhill.', NULL, 'HARD', 1, TRUE, '2026-07-16T11:31:29.448Z', '2026-07-16T11:31:29.448Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5391, 30, 'TEXT', 'Which phrase is more formal?', NULL, '["provided that","on condition that","if","as long as"]', 'a) provided that', NULL, 'HARD', 1, TRUE, '2026-07-16T11:31:29.599Z', '2026-07-16T11:31:29.599Z') ON CONFLICT DO NOTHING;
