INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5393, 30, 'TEXT', 'Which sentence is informal?', NULL, '["The solution is relatively simple.","The solution appears to be simple.","The solution looks pretty simple.","The solution seems to be straightforward."]', 'c) The solution looks pretty simple.', NULL, 'HARD', 1, TRUE, '2026-07-16T11:31:29.953Z', '2026-07-16T11:31:29.953Z') ON CONFLICT DO NOTHING;
