INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5396, 30, 'TEXT', 'Which sentence is informal?', NULL, '["I got your enquiry.","I have received your enquiry.","Your enquiry has been received.","I am in receipt of your enquiry."]', 'a) I got your enquiry.', NULL, 'HARD', 1, TRUE, '2026-07-16T11:31:30.412Z', '2026-07-16T11:31:30.412Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5397, 30, 'TEXT', 'Which phrase is more formal?', NULL, '["around","approximately","roughly","about"]', 'b) approximately', NULL, 'HARD', 1, TRUE, '2026-07-16T11:31:30.562Z', '2026-07-16T11:31:30.562Z') ON CONFLICT DO NOTHING;
