INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5399, 30, 'TEXT', 'Which sentence is informal?', NULL, '["The evidence indicates a different conclusion.","The evidence leads to a different conclusion.","The evidence suggests a different conclusion.","The evidence points to a different conclusion."]', 'd) The evidence points to a different conclusion.', NULL, 'HARD', 1, TRUE, '2026-07-16T11:31:30.865Z', '2026-07-16T11:31:30.865Z') ON CONFLICT DO NOTHING;
