INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5401, 31, 'TEXT', 'Which of the following is a simple sentence?', NULL, '["I went to the shop.","I went to the shop and bought some milk.","I went to the shop because I needed milk.","I went to the shop, but it was closed."]', 'a) I went to the shop.', NULL, 'EASY', 1, TRUE, '2026-07-16T11:45:35.716Z', '2026-07-16T11:45:35.716Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5402, 31, 'TEXT', 'Which of the following is a compound sentence?', NULL, '["She runs every morning.","She runs every morning and swims in the evening.","She runs every morning because she wants to stay fit.","She runs every morning, and she swims in the evening."]', 'd) She runs every morning, and she swims in the evening.', NULL, 'EASY', 1, TRUE, '2026-07-16T11:45:35.920Z', '2026-07-16T11:45:35.920Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5403, 31, 'TEXT', 'Which of the following is a complex sentence?', NULL, '["The dog barked.","The dog barked and chased the cat.","The dog barked because it was scared.","The dog barked, and the cat ran away."]', 'c) The dog barked because it was scared.', NULL, 'EASY', 1, TRUE, '2026-07-16T11:45:36.076Z', '2026-07-16T11:45:36.076Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5404, 31, 'TEXT', 'Which sentence contains a dependent clause?', NULL, '["I like ice cream.","I like ice cream and cake.","I like ice cream because it is sweet.","I like ice cream, and I like cake."]', 'c) I like ice cream because it is sweet.', NULL, 'EASY', 1, TRUE, '2026-07-16T11:45:36.234Z', '2026-07-16T11:45:36.234Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5405, 31, 'TEXT', 'Which of the following is a compound sentence?', NULL, '["He studied hard.","He studied hard for the exam.","He studied hard, so he passed the exam.","He studied hard because he wanted to pass."]', 'c) He studied hard, so he passed the exam.', NULL, 'EASY', 1, TRUE, '2026-07-16T11:45:36.404Z', '2026-07-16T11:45:36.404Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5406, 31, 'TEXT', 'Which of the following is a complex sentence?', NULL, '["She sang beautifully.","She sang and danced.","She sang beautifully, and everyone applauded.","She sang beautifully although she was nervous."]', 'd) She sang beautifully although she was nervous.', NULL, 'EASY', 1, TRUE, '2026-07-16T11:45:36.558Z', '2026-07-16T11:45:36.558Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5407, 31, 'TEXT', 'Which sentence is a simple sentence?', NULL, '["The sun set, and the moon rose.","The sun set behind the mountains.","The sun set because it was evening.","The sun set, so we went home."]', 'b) The sun set behind the mountains.', NULL, 'EASY', 1, TRUE, '2026-07-16T11:45:36.712Z', '2026-07-16T11:45:36.712Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5408, 31, 'TEXT', 'Which conjunction makes a compound sentence?', NULL, '["because","although","since","and"]', 'd) and', NULL, 'EASY', 1, TRUE, '2026-07-16T11:45:36.864Z', '2026-07-16T11:45:36.864Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5409, 31, 'TEXT', 'Which sentence is a compound sentence?', NULL, '["We went to the park.","We went to the park and played football.","We went to the park because it was sunny.","We went to the park, but it started raining."]', 'd) We went to the park, but it started raining.', NULL, 'EASY', 1, TRUE, '2026-07-16T11:45:37.016Z', '2026-07-16T11:45:37.016Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5410, 31, 'TEXT', 'Which sentence is a complex sentence?', NULL, '["The cat slept.","The cat slept on the sofa.","The cat slept on the sofa, and the dog played outside.","The cat slept on the sofa while the dog played outside."]', 'd) The cat slept on the sofa while the dog played outside.', NULL, 'EASY', 1, TRUE, '2026-07-16T11:45:37.168Z', '2026-07-16T11:45:37.168Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5411, 31, 'TEXT', 'Which sentence is a simple sentence?', NULL, '["The children played in the garden.","The children played in the garden, and their parents watched.","The children played in the garden while their parents watched.","The children played in the garden because it was sunny."]', 'a) The children played in the garden.', NULL, 'EASY', 1, TRUE, '2026-07-16T11:45:37.320Z', '2026-07-16T11:45:37.320Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5412, 31, 'TEXT', 'Which of the following is a complex sentence?', NULL, '["I read a book.","I read a book and watched TV.","I read a book, and I watched TV.","I read a book before I went to sleep."]', 'd) I read a book before I went to sleep.', NULL, 'EASY', 1, TRUE, '2026-07-16T11:45:37.473Z', '2026-07-16T11:45:37.473Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5413, 31, 'TEXT', 'Which sentence contains an independent clause only?', NULL, '["She laughed.","She laughed because she was happy.","She laughed when she heard the joke.","She laughed, and she clapped her hands."]', 'a) She laughed.', NULL, 'EASY', 1, TRUE, '2026-07-16T11:45:37.626Z', '2026-07-16T11:45:37.626Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5414, 31, 'TEXT', 'Which sentence is a compound sentence?', NULL, '["We had a picnic in the meadow.","We had a picnic because the weather was fine.","We had a picnic, and we played games.","We had a picnic that we had prepared carefully."]', 'c) We had a picnic, and we played games.', NULL, 'EASY', 1, TRUE, '2026-07-16T11:45:37.779Z', '2026-07-16T11:45:37.779Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5415, 31, 'TEXT', 'Which sentence is a complex sentence?', NULL, '["He opened the door.","He opened the door and walked in.","He opened the door, and he walked in.","He opened the door after he knocked."]', 'd) He opened the door after he knocked.', NULL, 'EASY', 1, TRUE, '2026-07-16T11:45:37.931Z', '2026-07-16T11:45:37.931Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5416, 31, 'TEXT', 'Which conjunction introduces a dependent clause?', NULL, '["but","and","so","although"]', 'd) although', NULL, 'EASY', 1, TRUE, '2026-07-16T11:45:38.094Z', '2026-07-16T11:45:38.094Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5417, 31, 'TEXT', 'Which sentence is a simple sentence?', NULL, '["She baked a cake.","She baked a cake and frosted it.","She baked a cake, and it was delicious.","She baked a cake because it was her birthday."]', 'a) She baked a cake.', NULL, 'EASY', 1, TRUE, '2026-07-16T11:45:38.248Z', '2026-07-16T11:45:38.248Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5418, 31, 'TEXT', 'Which sentence is a compound sentence?', NULL, '["The train arrived on time.","The train arrived on time, but it was crowded.","The train arrived on time because it was early.","The train arrived on time although it was crowded."]', 'b) The train arrived on time, but it was crowded.', NULL, 'EASY', 1, TRUE, '2026-07-16T11:45:38.404Z', '2026-07-16T11:45:38.404Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5419, 31, 'TEXT', 'Which sentence is a complex sentence?', NULL, '["He forgot his keys.","He forgot his keys and locked himself out.","He forgot his keys, so he was locked out.","He forgot his keys because he was in a hurry."]', 'd) He forgot his keys because he was in a hurry.', NULL, 'EASY', 1, TRUE, '2026-07-16T11:45:38.559Z', '2026-07-16T11:45:38.559Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5420, 31, 'TEXT', 'Which sentence contains a subordinate clause?', NULL, '["The teacher explained the lesson.","The teacher explained the lesson, and the students listened.","The teacher explained the lesson after the students had arrived.","The teacher explained the lesson, but the students were distracted."]', 'c) The teacher explained the lesson after the students had arrived.', NULL, 'EASY', 1, TRUE, '2026-07-16T11:45:38.714Z', '2026-07-16T11:45:38.714Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5421, 31, 'TEXT', 'Which sentence is a simple sentence?', NULL, '["She wore a red dress.","She wore a red dress and a hat.","She wore a red dress, but she forgot her shoes.","She wore a red dress because it was her favourite."]', 'a) She wore a red dress.', NULL, 'EASY', 1, TRUE, '2026-07-16T11:45:38.866Z', '2026-07-16T11:45:38.866Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5422, 31, 'TEXT', 'Which sentence is a compound sentence?', NULL, '["He ate the sandwich.","He ate the sandwich and drank some juice.","He ate the sandwich, and he drank some juice.","He ate the sandwich because he was hungry."]', 'c) He ate the sandwich, and he drank some juice.', NULL, 'EASY', 1, TRUE, '2026-07-16T11:45:39.020Z', '2026-07-16T11:45:39.020Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5423, 31, 'TEXT', 'Which sentence is a complex sentence?', NULL, '["The tree fell.","The tree fell and broke the fence.","The tree fell, and it broke the fence.","The tree fell because the wind was strong."]', 'd) The tree fell because the wind was strong.', NULL, 'EASY', 1, TRUE, '2026-07-16T11:45:39.172Z', '2026-07-16T11:45:39.172Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5424, 31, 'TEXT', 'Which word can join two independent clauses?', NULL, '["because","since","although","but"]', 'd) but', NULL, 'EASY', 1, TRUE, '2026-07-16T11:45:39.327Z', '2026-07-16T11:45:39.327Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5425, 31, 'TEXT', 'Which sentence is a simple sentence?', NULL, '["Birds fly.","Birds fly and sing.","Birds fly, and they sing.","Birds fly because they have wings."]', 'a) Birds fly.', NULL, 'EASY', 1, TRUE, '2026-07-16T11:45:39.481Z', '2026-07-16T11:45:39.481Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5426, 31, 'TEXT', 'Which sentence is a compound sentence?', NULL, '["She danced gracefully.","She danced gracefully and smiled.","She danced gracefully, and everyone watched.","She danced gracefully because she was happy."]', 'c) She danced gracefully, and everyone watched.', NULL, 'EASY', 1, TRUE, '2026-07-16T11:45:39.633Z', '2026-07-16T11:45:39.633Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5427, 31, 'TEXT', 'Which sentence is a complex sentence?', NULL, '["The baby slept peacefully.","The baby slept peacefully in her cot.","The baby slept peacefully, and her mother watched.","The baby slept peacefully until her mother returned."]', 'd) The baby slept peacefully until her mother returned.', NULL, 'EASY', 1, TRUE, '2026-07-16T11:45:39.787Z', '2026-07-16T11:45:39.787Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5428, 31, 'TEXT', 'Which sentence contains a dependent clause?', NULL, '["We went to the cinema.","We went to the cinema and watched a film.","We went to the cinema, but it was sold out.","We went to the cinema after we had dinner."]', 'd) We went to the cinema after we had dinner.', NULL, 'EASY', 1, TRUE, '2026-07-16T11:45:39.947Z', '2026-07-16T11:45:39.947Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5429, 31, 'TEXT', 'Which sentence is a simple sentence?', NULL, '["He wrote a letter.","He wrote a letter and posted it.","He wrote a letter, but he forgot to post it.","He wrote a letter because he missed his friend."]', 'a) He wrote a letter.', NULL, 'EASY', 1, TRUE, '2026-07-16T11:45:40.564Z', '2026-07-16T11:45:40.564Z') ON CONFLICT DO NOTHING;
