INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5473, 31, 'TEXT', 'Which sentence is a compound-complex sentence?', NULL, '["The dog barked.","The dog barked and chased the cat.","The dog barked, and the cat ran away.","The dog barked because it was scared, and the cat ran away."]', 'd) The dog barked because it was scared, and the cat ran away.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:47.502Z', '2026-07-16T11:45:47.502Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5474, 31, 'TEXT', 'Which sentence is a compound-complex sentence?', NULL, '["He studied hard.","He studied hard and passed the exam.","He studied hard, so he passed the exam.","He studied hard because he wanted to pass, and he succeeded."]', 'd) He studied hard because he wanted to pass, and he succeeded.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:47.661Z', '2026-07-16T11:45:47.661Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5475, 31, 'TEXT', 'Which sentence contains two independent clauses?', NULL, '["She sang.","She sang and danced.","She sang, and she danced.","She sang because she was happy."]', 'c) She sang, and she danced.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:47.815Z', '2026-07-16T11:45:47.815Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5476, 31, 'TEXT', 'Which sentence is a compound-complex sentence?', NULL, '["The sun set.","The sun set behind the mountains.","The sun set, and the moon rose.","The sun set while we were walking, and the moon rose."]', 'd) The sun set while we were walking, and the moon rose.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:47.974Z', '2026-07-16T11:45:47.974Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5477, 31, 'TEXT', 'Which sentence contains two independent clauses joined by a semicolon?', NULL, '["I went home; I was tired.","I went home because I was tired.","I went home and slept.","I went home, and I was tired."]', 'a) I went home; I was tired.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:48.128Z', '2026-07-16T11:45:48.128Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5478, 31, 'TEXT', 'Which sentence is a compound-complex sentence?', NULL, '["We went to the park.","We went to the park and played.","We went to the park, and we played.","We went to the park because it was sunny, and we played there."]', 'd) We went to the park because it was sunny, and we played there.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:48.286Z', '2026-07-16T11:45:48.286Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5479, 31, 'TEXT', 'Which sentence contains a dependent clause introduced by "although"?', NULL, '["He was tired, but he continued working.","He was tired, and he continued working.","Although he was tired, he continued working.","He was tired, so he continued working."]', 'c) Although he was tired, he continued working.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:48.441Z', '2026-07-16T11:45:48.441Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5480, 31, 'TEXT', 'Which sentence is a compound-complex sentence?', NULL, '["The cat slept.","The cat slept on the sofa.","The cat slept, and the dog played.","The cat slept while the dog played, and the children watched."]', 'd) The cat slept while the dog played, and the children watched.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:48.598Z', '2026-07-16T11:45:48.598Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5481, 31, 'TEXT', 'Which sentence contains a relative clause?', NULL, '["The man smiled.","The man smiled at the woman.","The man smiled at the woman, and she waved.","The man who was standing there smiled."]', 'd) The man who was standing there smiled.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:48.753Z', '2026-07-16T11:45:48.753Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5482, 31, 'TEXT', 'Which sentence is a compound-complex sentence?', NULL, '["I read a book.","I read a book and watched TV.","I read a book, and I watched TV.","I read a book before I went to sleep, and I enjoyed it."]', 'd) I read a book before I went to sleep, and I enjoyed it.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:48.909Z', '2026-07-16T11:45:48.909Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5483, 31, 'TEXT', 'Which sentence contains an independent clause and a relative clause?', NULL, '["She laughed.","She laughed at the joke.","She laughed, and she clapped.","She laughed at the joke that he told."]', 'd) She laughed at the joke that he told.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:49.064Z', '2026-07-16T11:45:49.064Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5484, 31, 'TEXT', 'Which sentence is a compound-complex sentence?', NULL, '["We had a picnic.","We had a picnic in the meadow.","We had a picnic, and we played games.","We had a picnic that we prepared carefully, and we enjoyed it."]', 'd) We had a picnic that we prepared carefully, and we enjoyed it.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:49.219Z', '2026-07-16T11:45:49.219Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5485, 31, 'TEXT', 'Which sentence contains a dependent clause introduced by "when"?', NULL, '["He opened the door.","He opened the door and walked in.","He opened the door, and he walked in.","He opened the door when he heard the knock."]', 'd) He opened the door when he heard the knock.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:49.376Z', '2026-07-16T11:45:49.376Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5486, 31, 'TEXT', 'Which sentence is a compound-complex sentence?', NULL, '["She baked a cake.","She baked a cake and frosted it.","She baked a cake, and it was delicious.","She baked a cake because it was her birthday, and everyone loved it."]', 'd) She baked a cake because it was her birthday, and everyone loved it.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:49.531Z', '2026-07-16T11:45:49.531Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5487, 31, 'TEXT', 'Which sentence contains two independent clauses joined by a semicolon with a conjunctive adverb?', NULL, '["I was tired; I went to bed.","I was tired; therefore, I went to bed.","I was tired because I went to bed.","I was tired, and I went to bed."]', 'b) I was tired; therefore, I went to bed.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:49.685Z', '2026-07-16T11:45:49.685Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5488, 31, 'TEXT', 'Which sentence is a compound-complex sentence?', NULL, '["The train arrived on time.","The train arrived on time, but it was crowded.","The train arrived on time because it was early.","The train arrived on time although it was crowded, and we boarded it."]', 'd) The train arrived on time although it was crowded, and we boarded it.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:49.842Z', '2026-07-16T11:45:49.842Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5489, 31, 'TEXT', 'Which sentence contains a dependent clause introduced by "after"?', NULL, '["He forgot his keys.","He forgot his keys and locked himself out.","He forgot his keys, so he was locked out.","He forgot his keys after he left the house."]', 'd) He forgot his keys after he left the house.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:49.996Z', '2026-07-16T11:45:49.996Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5490, 31, 'TEXT', 'Which sentence is a compound-complex sentence?', NULL, '["The teacher explained the lesson.","The teacher explained the lesson, and the students listened.","The teacher explained the lesson after the students had arrived.","The teacher explained the lesson after the students had arrived, and they understood it."]', 'd) The teacher explained the lesson after the students had arrived, and they understood it.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:50.151Z', '2026-07-16T11:45:50.151Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5491, 31, 'TEXT', 'Which sentence contains a non-defining relative clause?', NULL, '["The man who lives next door is a doctor.","My brother, who lives in London, is visiting us.","The man that I saw was tall.","She knows the woman who works there."]', 'b) My brother, who lives in London, is visiting us.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:50.306Z', '2026-07-16T11:45:50.306Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5492, 31, 'TEXT', 'Which sentence is a compound-complex sentence?', NULL, '["She wore a red dress.","She wore a red dress, but she forgot her shoes.","She wore a red dress because it was her favourite.","She wore a red dress because it was her favourite, but she forgot her shoes."]', 'd) She wore a red dress because it was her favourite, but she forgot her shoes.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:50.461Z', '2026-07-16T11:45:50.461Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5493, 31, 'TEXT', 'Which sentence contains a dependent clause introduced by "until"?', NULL, '["He ate the sandwich.","He ate the sandwich and drank some juice.","He ate the sandwich, and he drank some juice.","He ate the sandwich until he was full."]', 'd) He ate the sandwich until he was full.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:50.616Z', '2026-07-16T11:45:50.616Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5494, 31, 'TEXT', 'Which sentence is a compound-complex sentence?', NULL, '["The tree fell.","The tree fell and broke the fence.","The tree fell, and it broke the fence.","The tree fell because the wind was strong, and it broke the fence."]', 'd) The tree fell because the wind was strong, and it broke the fence.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:50.771Z', '2026-07-16T11:45:50.771Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5495, 31, 'TEXT', 'Which sentence contains a dependent clause introduced by "where"?', NULL, '["Birds fly.","Birds fly and sing.","Birds fly, and they sing.","Birds fly where the climate is warm."]', 'd) Birds fly where the climate is warm.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:50.928Z', '2026-07-16T11:45:50.928Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5496, 31, 'TEXT', 'Which sentence is a compound-complex sentence?', NULL, '["She danced gracefully.","She danced gracefully and smiled.","She danced gracefully, and everyone watched.","She danced gracefully because she was happy, and everyone watched."]', 'd) She danced gracefully because she was happy, and everyone watched.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:51.087Z', '2026-07-16T11:45:51.087Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5497, 31, 'TEXT', 'Which sentence contains a dependent clause introduced by "while"?', NULL, '["The baby slept peacefully.","The baby slept peacefully in her cot.","The baby slept peacefully, and her mother watched.","The baby slept peacefully while her mother watched."]', 'd) The baby slept peacefully while her mother watched.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:51.241Z', '2026-07-16T11:45:51.241Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5498, 31, 'TEXT', 'Which sentence is a compound-complex sentence?', NULL, '["We went to the cinema.","We went to the cinema and watched a film.","We went to the cinema, but it was sold out.","We went to the cinema after we had dinner, but it was sold out."]', 'd) We went to the cinema after we had dinner, but it was sold out.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:51.397Z', '2026-07-16T11:45:51.397Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5499, 31, 'TEXT', 'Which sentence contains a dependent clause introduced by "since"?', NULL, '["He wrote a letter.","He wrote a letter and posted it.","He wrote a letter, but he forgot to post it.","He wrote a letter since he missed his friend."]', 'd) He wrote a letter since he missed his friend.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:51.554Z', '2026-07-16T11:45:51.554Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5500, 31, 'TEXT', 'Which sentence is a compound-complex sentence?', NULL, '["The children played quietly.","The children played quietly in their room.","The children played quietly, but they made a mess.","The children played quietly because their parents were resting, but they made a mess."]', 'd) The children played quietly because their parents were resting, but they made a mess.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:51.713Z', '2026-07-16T11:45:51.713Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5501, 31, 'TEXT', 'Which sentence contains a dependent clause introduced by "whenever"?', NULL, '["The car stopped.","The car stopped suddenly.","The car stopped, and the driver got out.","The car stopped whenever the light turned red."]', 'd) The car stopped whenever the light turned red.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:51.869Z', '2026-07-16T11:45:51.869Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5502, 31, 'TEXT', 'Which sentence is a compound-complex sentence?', NULL, '["The clock struck twelve.","The clock struck twelve and chimed.","The clock struck twelve, and we celebrated.","The clock struck twelve because it was midnight, and we celebrated."]', 'd) The clock struck twelve because it was midnight, and we celebrated.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:52.024Z', '2026-07-16T11:45:52.024Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5503, 31, 'TEXT', 'Which sentence contains a dependent clause introduced by "before"?', NULL, '["She painted a picture.","She painted a picture and framed it.","She painted a picture, and she hung it on the wall.","She painted a picture before she hung it on the wall."]', 'd) She painted a picture before she hung it on the wall.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:52.179Z', '2026-07-16T11:45:52.179Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5504, 31, 'TEXT', 'Which sentence is a compound-complex sentence?', NULL, '["The bird sang.","The bird sang sweetly.","The bird sang, and the cat watched.","The bird sang although it was raining, but the cat still watched."]', 'd) The bird sang although it was raining, but the cat still watched.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:52.335Z', '2026-07-16T11:45:52.335Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5505, 31, 'TEXT', 'Which sentence contains a dependent clause introduced by "as"?', NULL, '["I like coffee.","I like coffee and tea.","I like coffee, and I like tea.","I like coffee as it wakes me up."]', 'd) I like coffee as it wakes me up.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:52.489Z', '2026-07-16T11:45:52.489Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5506, 31, 'TEXT', 'Which sentence is a compound-complex sentence?', NULL, '["The phone rang.","The phone rang loudly.","The phone rang, and I answered it.","The phone rang because someone was calling, and I answered it."]', 'd) The phone rang because someone was calling, and I answered it.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:52.644Z', '2026-07-16T11:45:52.644Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5507, 31, 'TEXT', 'Which sentence contains a dependent clause introduced by "so that"?', NULL, '["She walked to school.","She walked to school with her friend.","She walked to school, but she was late.","She walked to school so that she could meet her friend."]', 'd) She walked to school so that she could meet her friend.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:52.800Z', '2026-07-16T11:45:52.800Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5508, 31, 'TEXT', 'Which sentence is a compound-complex sentence?', NULL, '["The man smiled.","The man smiled warmly.","The man smiled, and the woman waved.","The man smiled when he saw his friend, and the woman waved."]', 'd) The man smiled when he saw his friend, and the woman waved.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:52.956Z', '2026-07-16T11:45:52.956Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5509, 31, 'TEXT', 'Which sentence contains a dependent clause introduced by "unless"?', NULL, '["She loves music.","She loves music and dancing.","She loves music, and she plays the piano.","She loves music unless it is too loud."]', 'd) She loves music unless it is too loud.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:53.110Z', '2026-07-16T11:45:53.110Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5510, 31, 'TEXT', 'Which sentence is a compound-complex sentence?', NULL, '["He ran quickly.","He ran quickly to the station.","He ran quickly, yet he missed the train.","He ran quickly because he was late, yet he missed the train."]', 'd) He ran quickly because he was late, yet he missed the train.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:53.267Z', '2026-07-16T11:45:53.267Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5511, 31, 'TEXT', 'Which sentence contains a dependent clause introduced by "although"?', NULL, '["The flowers bloomed.","The flowers bloomed in spring.","The flowers bloomed, and the bees came.","The flowers bloomed although it was still cold."]', 'd) The flowers bloomed although it was still cold.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:53.425Z', '2026-07-16T11:45:53.425Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (5512, 31, 'TEXT', 'Which sentence is a compound-complex sentence?', NULL, '["She stayed at home.","She stayed at home and read a book.","She stayed at home, but she was bored.","She stayed at home because she was tired, but she was bored."]', 'd) She stayed at home because she was tired, but she was bored.', NULL, 'MEDIUM', 1, TRUE, '2026-07-16T11:45:53.581Z', '2026-07-16T11:45:53.581Z') ON CONFLICT DO NOTHING;
