INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10262, 55, 'TEXT', 'Why does the author write, "She cried buckets of tears"?', NULL, '["To describe the tears","To say she was happy","To compare tears to buckets","To exaggerate how much she cried"]', 'D) To exaggerate how much she cried', NULL, 'EASY', 1, TRUE, '2026-07-17T12:18:51.849Z', '2026-07-17T12:18:51.849Z') ON CONFLICT DO NOTHING;
