INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10264, 55, 'TEXT', 'When Tom says, "I''m the king of the world," what does he really mean?', NULL, '["He owns the world.","He feels very proud and happy.","He is actually a king.","He is a ruler."]', 'B) He feels very proud and happy.', NULL, 'EASY', 1, TRUE, '2026-07-17T12:18:52.166Z', '2026-07-17T12:18:52.166Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10265, 55, 'TEXT', 'Which sentence contains hyperbole?', NULL, '["He was very rich.","He had a lot of money.","He had more money than the Queen.","He was wealthy."]', 'C) He had more money than the Queen.', NULL, 'EASY', 1, TRUE, '2026-07-17T12:18:52.320Z', '2026-07-17T12:18:52.320Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10266, 55, 'TEXT', 'Which phrase is an example of hyperbole?', NULL, '["As old as the hills","As quiet as a mouse","As brave as a lion","As slow as a snail"]', 'A) As old as the hills', NULL, 'EASY', 1, TRUE, '2026-07-17T12:18:52.474Z', '2026-07-17T12:18:52.474Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10267, 55, 'TEXT', 'Which sentence uses exaggeration for emphasis?', NULL, '["He ate a lot of food.","He ate everything in sight.","He could eat a horse.","He had a big meal."]', 'C) He could eat a horse.', NULL, 'EASY', 1, TRUE, '2026-07-17T12:18:52.628Z', '2026-07-17T12:18:52.628Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10268, 55, 'TEXT', '"My computer is a dinosaur." This is an example of:', NULL, '["Simile","Personification","Metaphor","Hyperbole"]', 'D) Hyperbole', NULL, 'EASY', 1, TRUE, '2026-07-17T12:18:52.786Z', '2026-07-17T12:18:52.786Z') ON CONFLICT DO NOTHING;
