INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10305, 55, 'TEXT', 'Why does the author write, "He was so proud he was bursting with it"?', NULL, '["To compare pride to a balloon","To describe his actual state","To exaggerate how proud he was","To say he was angry"]', 'C) To exaggerate how proud he was', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T12:18:59.052Z', '2026-07-17T12:18:59.052Z') ON CONFLICT DO NOTHING;
