INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10369, 55, 'TEXT', 'Which sentence contains hyperbole?', NULL, '["The building was older than time itself.","The building was old.","The building was ancient.","The building was very old."]', 'A) The building was older than time itself.', NULL, 'HARD', 1, TRUE, '2026-07-17T12:19:09.240Z', '2026-07-17T12:19:09.240Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10370, 55, 'TEXT', 'Which phrase is an example of hyperbole?', NULL, '["He walked slowly","As happy as Larry","A world of opportunity","The stars twinkled"]', 'C) A world of opportunity', NULL, 'HARD', 1, TRUE, '2026-07-17T12:19:09.392Z', '2026-07-17T12:19:09.392Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10371, 55, 'TEXT', 'Which sentence uses exaggeration for emphasis?', NULL, '["The mountain was huge.","The mountain was big.","The mountain was enormous.","The mountain was so big it blotted out the sun."]', 'D) The mountain was so big it blotted out the sun.', NULL, 'HARD', 1, TRUE, '2026-07-17T12:19:09.548Z', '2026-07-17T12:19:09.548Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10372, 55, 'TEXT', '"His temper was a volcano waiting to erupt." This is an example of:', NULL, '["Hyperbole","Metaphor","Simile","Personification"]', 'A) Hyperbole', NULL, 'HARD', 1, TRUE, '2026-07-17T12:19:09.702Z', '2026-07-17T12:19:09.702Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10373, 55, 'TEXT', 'Which sentence does NOT contain hyperbole?', NULL, '["I''ve been waiting for hours.","The room was very cold.","He could eat all day.","She could catch a fly with chopsticks."]', 'B) The room was very cold.', NULL, 'HARD', 1, TRUE, '2026-07-17T12:19:09.854Z', '2026-07-17T12:19:09.854Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10374, 55, 'TEXT', 'Choose the best phrase to complete the sentence. He was so rich that ______.', NULL, '["he could buy the entire city","he was wealthy","he could buy anything he wanted","he had a lot of money"]', 'A) he could buy the entire city', NULL, 'HARD', 1, TRUE, '2026-07-17T12:19:10.007Z', '2026-07-17T12:19:10.007Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10375, 55, 'TEXT', 'Why does the author write, "The rain was falling in buckets"?', NULL, '["To say it was dry","To compare rain to buckets","To describe the containers","To exaggerate how heavily it was raining"]', 'D) To exaggerate how heavily it was raining', NULL, 'HARD', 1, TRUE, '2026-07-17T12:19:10.159Z', '2026-07-17T12:19:10.159Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10376, 55, 'TEXT', 'Which sentence contains hyperbole rather than a simile?', NULL, '["He was as silent as the grave.","She ran like a cheetah.","I''m swimming in paperwork.","She was as white as a ghost."]', 'C) I''m swimming in paperwork.', NULL, 'HARD', 1, TRUE, '2026-07-17T12:19:10.315Z', '2026-07-17T12:19:10.315Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10377, 55, 'TEXT', 'When Katie says, "I''m going to need a crane to get out of bed," what does she really mean?', NULL, '["She needs a crane to move.","She is very tired.","She is energetic.","She has hurt her leg."]', 'B) She is very tired.', NULL, 'HARD', 1, TRUE, '2026-07-17T12:19:10.469Z', '2026-07-17T12:19:10.469Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10378, 55, 'TEXT', 'Which sentence contains hyperbole?', NULL, '["The flowers looked nice.","The flowers were beautiful.","The flowers were pretty.","The flowers were a sea of colour."]', 'D) The flowers were a sea of colour.', NULL, 'HARD', 1, TRUE, '2026-07-17T12:19:10.625Z', '2026-07-17T12:19:10.625Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10379, 55, 'TEXT', 'Which phrase is an example of hyperbole?', NULL, '["The rain fell","A mountain of evidence","He was hungry","As old as the hills"]', 'B) A mountain of evidence', NULL, 'HARD', 1, TRUE, '2026-07-17T12:19:10.790Z', '2026-07-17T12:19:10.790Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10380, 55, 'TEXT', 'Which sentence uses exaggeration for emphasis?', NULL, '["She has a lot of patience.","She waits well.","She has the patience of a saint.","She is patient."]', 'C) She has the patience of a saint.', NULL, 'HARD', 1, TRUE, '2026-07-17T12:19:10.950Z', '2026-07-17T12:19:10.950Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10381, 55, 'TEXT', '"I''m going to kill that spider." This is an example of:', NULL, '["Hyperbole","Personification","Metaphor","Simile"]', 'A) Hyperbole', NULL, 'HARD', 1, TRUE, '2026-07-17T12:19:11.117Z', '2026-07-17T12:19:11.117Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10382, 55, 'TEXT', 'Which sentence does NOT contain hyperbole?', NULL, '["She was as quiet as a mouse.","I could walk a thousand miles.","The food was delicious.","He could eat a elephant."]', 'C) The food was delicious.', NULL, 'HARD', 1, TRUE, '2026-07-17T12:19:11.271Z', '2026-07-17T12:19:11.271Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10383, 55, 'TEXT', 'Choose the best phrase to complete the sentence. The traffic was so bad that ______.', NULL, '["it would have been quicker to walk","it was congested","we were stuck","we were late"]', 'A) it would have been quicker to walk', NULL, 'HARD', 1, TRUE, '2026-07-17T12:19:11.423Z', '2026-07-17T12:19:11.423Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10384, 55, 'TEXT', 'Why does the author write, "He had an elephant''s memory"?', NULL, '["To compare his memory to an elephant","To exaggerate how good his memory was","To describe his actual memory","To say he forgot things"]', 'B) To exaggerate how good his memory was', NULL, 'HARD', 1, TRUE, '2026-07-17T12:19:11.575Z', '2026-07-17T12:19:11.575Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10385, 55, 'TEXT', 'Which sentence contains hyperbole rather than personification?', NULL, '["The wind howled all night.","The thunder roared with anger.","The sun kissed the horizon.","I''m so hungry I could eat a sandwich."]', 'D) I''m so hungry I could eat a sandwich.', NULL, 'HARD', 1, TRUE, '2026-07-17T12:19:11.732Z', '2026-07-17T12:19:11.732Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10386, 55, 'TEXT', 'When Grace says, "This bag is as heavy as lead," what does she really mean?', NULL, '["The bag is light.","The bag is made of lead.","The bag is very heavy.","The bag is filled with stones."]', 'C) The bag is very heavy.', NULL, 'HARD', 1, TRUE, '2026-07-17T12:19:11.884Z', '2026-07-17T12:19:11.884Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10387, 55, 'TEXT', 'Which sentence contains hyperbole?', NULL, '["He was tall for his age.","He was quite tall.","He was very tall.","He was so tall he could see the future."]', 'D) He was so tall he could see the future.', NULL, 'HARD', 1, TRUE, '2026-07-17T12:19:12.037Z', '2026-07-17T12:19:12.037Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10388, 55, 'TEXT', 'Which phrase is an example of hyperbole?', NULL, '["He walked home","A thousand apologies","As cunning as a fox","The stars were bright"]', 'B) A thousand apologies', NULL, 'HARD', 1, TRUE, '2026-07-17T12:19:12.238Z', '2026-07-17T12:19:12.238Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10389, 55, 'TEXT', 'Which sentence uses exaggeration for emphasis?', NULL, '["She could stop traffic with her beauty.","She was breathtakingly beautiful.","She was good-looking.","She was beautiful."]', 'A) She could stop traffic with her beauty.', NULL, 'HARD', 1, TRUE, '2026-07-17T12:19:12.393Z', '2026-07-17T12:19:12.393Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10390, 55, 'TEXT', '"My feet are on fire." This is an example of:', NULL, '["Simile","Personification","Hyperbole","Metaphor"]', 'C) Hyperbole', NULL, 'HARD', 1, TRUE, '2026-07-17T12:19:12.552Z', '2026-07-17T12:19:12.552Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10447, 56, 'TEXT', 'Which sentence uses imagery more effectively?', NULL, '["The dog was happy.","The dog barked.","The dog wagged its tail and jumped up and down.","The dog was excited."]', 'C) The dog wagged its tail and jumped up and down.', NULL, 'EASY', 1, TRUE, '2026-07-17T12:28:39.382Z', '2026-07-17T12:28:39.382Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (7802, 43, 'TEXT', ' Emma loved spending time in her grandmother''s garden. Every Saturday, she watered the flowers, removed weeds, and planted new seeds. By the end of summer, the garden was filled with colourful roses, daisies, and sunflowers. Question: What is the main idea of this passage?', NULL, '["Emma wants to buy a new garden.","Emma helps care for her grandmother''s garden.","Emma dislikes gardening.","Emma enjoys painting flowers."]', 'B) Emma helps care for her grandmother''s garden.', NULL, 'EASY', 1, TRUE, '2026-07-17T05:51:20.074Z', '2026-07-17T05:51:20.074Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (7803, 43, 'TEXT', ' Tom woke up early and packed his school bag. He put his books, pencils, and lunch box inside. Then he ate breakfast and walked to the bus stop. Question: What is the main idea of this passage?', NULL, '["Tom hates school.","Tom is going on holiday.","Tom is making dinner.","Tom is getting ready for school."]', 'D) Tom is getting ready for school.', NULL, 'EASY', 1, TRUE, '2026-07-17T05:51:20.290Z', '2026-07-17T05:51:20.290Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (7804, 43, 'TEXT', ' The sun was shining brightly. The birds were singing. Children were playing in the park. It was a perfect day for a picnic. Question: What is the main idea of this passage?', NULL, '["It was a beautiful day for outdoor activities.","The weather was cold and rainy.","The children were at school.","Everyone was inside watching TV."]', 'A) It was a beautiful day for outdoor activities.', NULL, 'EASY', 1, TRUE, '2026-07-17T05:51:20.450Z', '2026-07-17T05:51:20.450Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (7805, 43, 'TEXT', ' Sara''s dog, Max, loved to play fetch. Every evening, Sara would throw a ball, and Max would chase it and bring it back. They both enjoyed this time together. Question: What is the main idea of this passage?', NULL, '["Sara throws the ball for her cat.","Sara and Max enjoy playing fetch together.","Sara hates dogs.","Max doesn''t like playing."]', 'B) Sara and Max enjoy playing fetch together.', NULL, 'EASY', 1, TRUE, '2026-07-17T05:51:20.612Z', '2026-07-17T05:51:20.612Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (7806, 43, 'TEXT', ' The library was quiet. People were reading books and newspapers. Some students were studying for their exams. The librarian was organising the books on the shelves. Question: What is the main idea of this passage?', NULL, '["The library is a peaceful place for reading and studying.","The library is a noisy place.","People are cooking in the library.","The librarian is sleeping."]', 'A) The library is a peaceful place for reading and studying.', NULL, 'EASY', 1, TRUE, '2026-07-17T05:51:20.770Z', '2026-07-17T05:51:20.770Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (7807, 43, 'TEXT', ' Jack''s father taught him how to ride a bicycle. At first, Jack was scared and kept falling off. But he practised every day and soon became very good at it. Question: What is the main idea of this passage?', NULL, '["Jack''s father doesn''t help him.","Jack prefers walking.","Jack refuses to learn cycling.","Jack learns to ride a bicycle with practice."]', 'D) Jack learns to ride a bicycle with practice.', NULL, 'EASY', 1, TRUE, '2026-07-17T05:51:20.930Z', '2026-07-17T05:51:20.930Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (7808, 43, 'TEXT', ' The restaurant was crowded. People were waiting for tables. The waiters were rushing around. The kitchen was busy preparing delicious food. Question: What is the main idea of this passage?', NULL, '["The restaurant is very busy.","The waiters are lazy.","The food is terrible.","The restaurant is empty."]', 'A) The restaurant is very busy.', NULL, 'EASY', 1, TRUE, '2026-07-17T05:51:21.091Z', '2026-07-17T05:51:21.091Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (7809, 43, 'TEXT', ' Lily loved to draw. She would spend hours with her colouring pencils, creating pictures of animals, trees, and her family. Her mother hung all her drawings on the refrigerator. Question: What is the main idea of this passage?', NULL, '["Lily''s mother throws away her drawings.","Lily hates drawing.","Lily draws only in school.","Lily enjoys drawing and her mother displays her artwork."]', 'D) Lily enjoys drawing and her mother displays her artwork.', NULL, 'EASY', 1, TRUE, '2026-07-17T05:51:21.246Z', '2026-07-17T05:51:21.246Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (7810, 43, 'TEXT', ' The city was busy with traffic. Cars honked. People rushed to work. Shops opened early. Everyone seemed to be in a hurry. Question: What is the main idea of this passage?', NULL, '["The city is very busy and crowded.","People are sleeping in the city.","The city is quiet and peaceful.","The shops are closed."]', 'A) The city is very busy and crowded.', NULL, 'EASY', 1, TRUE, '2026-07-17T05:51:21.407Z', '2026-07-17T05:51:21.407Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (7811, 43, 'TEXT', ' Mia helped her mother bake a chocolate cake. She measured the flour, cracked the eggs, and stirred the mixture. When the cake was ready, everyone enjoyed it. Question: What is the main idea of this passage?', NULL, '["Mia is painting a picture.","Mia is going to the shop.","Mia is reading a book.","Mia is making a cake with her mother."]', 'D) Mia is making a cake with her mother.', NULL, 'EASY', 1, TRUE, '2026-07-17T05:51:21.565Z', '2026-07-17T05:51:21.565Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (7812, 43, 'TEXT', ' The cat sat on the windowsill, watching the birds outside. Every time a bird came close, the cat''s tail would twitch. It seemed very interested in the birds. Question: What is the main idea of this passage?', NULL, '["The cat is afraid of birds.","The cat is sleeping on the windowsill.","The cat is watching birds from the window.","The cat is eating the birds."]', 'C) The cat is watching birds from the window.', NULL, 'EASY', 1, TRUE, '2026-07-17T05:51:21.726Z', '2026-07-17T05:51:21.726Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (7813, 43, 'TEXT', ' Sam and his friends built a treehouse in his backyard. They used wood, nails, and paint. After two weekends, they had a special place where they could play and relax. Question: What is the main idea of this passage?', NULL, '["The treehouse is broken.","Sam lives in a treehouse.","Sam''s friends don''t help him.","Sam and his friends built a treehouse together."]', 'D) Sam and his friends built a treehouse together.', NULL, 'EASY', 1, TRUE, '2026-07-17T05:51:21.888Z', '2026-07-17T05:51:21.888Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10391, 55, 'TEXT', 'Which sentence does NOT contain hyperbole?', NULL, '["She has a heart as cold as ice.","The queue was a mile long.","His voice could shatter glass.","The weather was pleasant."]', 'D) The weather was pleasant.', NULL, 'HARD', 1, TRUE, '2026-07-17T12:19:12.706Z', '2026-07-17T12:19:12.706Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (7814, 43, 'TEXT', ' The park was filled with colourful flowers. Children were playing on the swings. Couples were walking on the paths. Everyone was enjoying the beautiful weather. Question: What is the main idea of this passage?', NULL, '["The weather is bad.","People are working in the park.","The park is empty.","The park is a lively and enjoyable place."]', 'D) The park is a lively and enjoyable place.', NULL, 'EASY', 1, TRUE, '2026-07-17T05:51:22.048Z', '2026-07-17T05:51:22.048Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (7815, 43, 'TEXT', ' Anna practiced playing the piano every afternoon. She learned to read music and play different songs. By the end of the year, she performed in her first concert. Question: What is the main idea of this passage?', NULL, '["Anna practices the piano and performs in a concert.","Anna doesn''t like music.","Anna gives up playing the piano.","Anna plays the guitar."]', 'A) Anna practices the piano and performs in a concert.', NULL, 'EASY', 1, TRUE, '2026-07-17T05:51:22.207Z', '2026-07-17T05:51:22.207Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (7816, 43, 'TEXT', ' The museum had many interesting exhibits. There were dinosaur skeletons, ancient tools, and beautiful paintings. Visitors spent hours exploring everything. Question: What is the main idea of this passage?', NULL, '["The museum has fascinating exhibits for visitors to enjoy.","The museum only has paintings.","The museum is closed.","The museum is boring."]', 'A) The museum has fascinating exhibits for visitors to enjoy.', NULL, 'EASY', 1, TRUE, '2026-07-17T05:51:22.363Z', '2026-07-17T05:51:22.363Z') ON CONFLICT DO NOTHING;
