INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10450, 56, 'TEXT', 'Which sense is mainly used in the sentence? "The blazing fire warmed my frozen fingers as the flames danced and crackled."', NULL, '["Sight","Both sight and hearing","Smell","Hearing"]', 'B) Both sight and hearing', NULL, 'EASY', 1, TRUE, '2026-07-17T12:28:39.843Z', '2026-07-17T12:28:39.843Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8052, 44, 'TEXT', ' Lucy has a pet cat named Snowball. Snowball is white with blue eyes. She is 3 years old. Snowball loves to sleep on Lucy''s bed and play with balls of yarn. Lucy got Snowball as a birthday gift. Question: How old is Lucy''s cat Snowball?', NULL, '["4 years old","2 years old","1 year old","3 years old"]', 'C) 3 years old', NULL, 'EASY', 1, TRUE, '2026-07-17T07:32:20.440Z', '2026-07-17T07:43:43.035Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8053, 44, 'TEXT', ' The museum has a new exhibition on dinosaurs. It features 15 full-size skeletons. There are also interactive displays where visitors can dig for fossils. The exhibition is open until the end of August. Question: How many full-size dinosaur skeletons are in the exhibition?', NULL, '["10","5","20","15"]', 'D) 15', NULL, 'EASY', 1, TRUE, '2026-07-17T07:32:20.594Z', '2026-07-17T07:43:43.263Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8054, 44, 'TEXT', ' Jacob''s dad is a pilot. He flies planes for an international airline. He has been a pilot for 18 years. He often travels to places like Dubai, Singapore, and Tokyo. Jacob wants to travel with his dad one day. Question: How long has Jacob''s dad been a pilot?', NULL, '["10 years","22 years","18 years","14 years"]', 'A) 18 years', NULL, 'EASY', 1, TRUE, '2026-07-17T07:32:20.749Z', '2026-07-17T07:43:43.494Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8055, 44, 'TEXT', ' The community centre offers yoga classes every Tuesday and Thursday. The class starts at 6 pm and lasts for 1 hour. It costs £5 per session. Participants need to bring their own mat. Question: How long does each yoga class last?', NULL, '["30 minutes","1.5 hours","45 minutes","1 hour"]', 'B) 1 hour', NULL, 'EASY', 1, TRUE, '2026-07-17T07:32:20.902Z', '2026-07-17T07:43:43.724Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8056, 44, 'TEXT', ' Ava is 8 years old. She has a sister named Bella who is 10 years old. They both go to the same school. Ava is in Year 3 and Bella is in Year 5. They walk to school together every day. Question: Which year is Ava in?', NULL, '["Year 3","Year 4","Year 2","Year 5"]', 'C) Year 3', NULL, 'EASY', 1, TRUE, '2026-07-17T07:32:21.053Z', '2026-07-17T07:43:43.952Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8057, 44, 'TEXT', ' The library holds a book sale every Saturday. Used books are sold for £1 each. All the money raised goes to buying new books for the library. Last week, they raised £100. Question: How much does each used book cost at the book sale?', NULL, '["50p","£2","£3","£1"]', 'D) £1', NULL, 'EASY', 1, TRUE, '2026-07-17T07:32:21.205Z', '2026-07-17T07:43:44.180Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8058, 44, 'TEXT', ' Nora has two best friends, Lucy and Zoe. Nora''s birthday is in June. Lucy''s birthday is in September, and Zoe''s birthday is in December. They always celebrate together by having a sleepover. Question: When is Zoe''s birthday?', NULL, '["December","June","March","September"]', 'A) December', NULL, 'EASY', 1, TRUE, '2026-07-17T07:32:21.361Z', '2026-07-17T07:43:44.409Z') ON CONFLICT DO NOTHING;
