INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8061, 44, 'TEXT', ' The recycling centre is open Monday to Saturday from 8 am to 6 pm. It is closed on Sundays and public holidays. People can recycle paper, glass, plastic, and metal. The centre is located on Green Lane. Question: On which day is the recycling centre closed?', NULL, '["Sunday","Monday","Saturday","Friday"]', 'D) Sunday', NULL, 'EASY', 1, TRUE, '2026-07-17T07:32:21.817Z', '2026-07-17T07:43:45.102Z') ON CONFLICT DO NOTHING;
