INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8064, 44, 'TEXT', ' Ava''s family is going on a camping trip. They will be camping for 3 days. They will stay at a campsite near the lake. Ava is excited to go fishing with her dad. She has never caught a fish before. Question: How long will Ava''s family be camping?', NULL, '["1 day","2 days","4 days","3 days"]', 'C) 3 days', NULL, 'EASY', 1, TRUE, '2026-07-17T07:32:22.273Z', '2026-07-17T07:43:46.154Z') ON CONFLICT DO NOTHING;
