INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10403, 56, 'TEXT', 'Which sentence creates the clearest picture in the reader''s mind?', NULL, '["The beach was busy.","We went to the beach.","The beach was beautiful.","Golden waves crashed against the white sand as seagulls circled overhead."]', 'D) Golden waves crashed against the white sand as seagulls circled overhead.', NULL, 'EASY', 1, TRUE, '2026-07-17T12:28:32.489Z', '2026-07-17T12:28:32.489Z') ON CONFLICT DO NOTHING;
