INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10411, 56, 'TEXT', 'Why does the author include these descriptions? "The crackling fire filled the room with warmth, while the smell of cinnamon drifted through the air. Outside, snowflakes floated gently beneath the pale moonlight."', NULL, '["To help readers experience the setting through their senses.","To explain how to build a fire.","To persuade readers to stay indoors.","To compare winter with summer."]', 'A) To help readers experience the setting through their senses.', NULL, 'EASY', 1, TRUE, '2026-07-17T12:28:33.745Z', '2026-07-17T12:28:33.745Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8202, 45, 'TEXT', ' Ravi woke up at 7 am. He brushed his teeth, then ate breakfast. After breakfast, he packed his school bag and left for school at 8:15 am. Question: What did Ravi do immediately after brushing his teeth?', NULL, '["Left for school","Ate breakfast","Packed his bag","Woke up"]', 'B) Ate breakfast', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:09.422Z', '2026-07-17T07:43:09.422Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8203, 45, 'TEXT', ' Mia planted a seed in a pot. She watered it daily. After two weeks, a small sprout appeared. A month later, the plant grew its first flower. Question: What happened right after Mia watered the seed daily?', NULL, '["The plant flowered","She planted the seed","A sprout appeared","The pot broke"]', 'C) A sprout appeared', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:09.628Z', '2026-07-17T07:43:09.628Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8204, 45, 'TEXT', ' Tom mixed the flour and sugar first. Then he added eggs and milk. After stirring the batter, he poured it into a baking tray and placed it in the oven. Question: What did Tom do before pouring the batter into the tray?', NULL, '["Added eggs and milk","Placed it in the oven","Mixed flour and sugar","Stirred the batter"]', 'D) Stirred the batter', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:09.781Z', '2026-07-17T07:43:09.781Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8205, 45, 'TEXT', ' The train left the station at 9 am. It stopped at Leeds at 10:30 am, then continued to Manchester, arriving at noon. Question: Which stop came right after the train left the station?', NULL, '["London","Birmingham","Manchester","Leeds"]', 'D) Leeds', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:09.938Z', '2026-07-17T07:43:09.938Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8206, 45, 'TEXT', ' Sara first cleaned her room. Then she did her homework. After finishing homework, she watched television before going to bed. Question: What did Sara do just before watching television?', NULL, '["Ate dinner","Did her homework","Cleaned her room","Went to bed"]', 'B) Did her homework', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:10.091Z', '2026-07-17T07:43:10.091Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8207, 45, 'TEXT', ' The builders dug the foundation first. Next, they built the walls. After the walls were up, they added the roof, and finally painted the house. Question: What was built immediately after the foundation?', NULL, '["The paint job","The roof","The walls","The garden"]', 'C) The walls', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:10.244Z', '2026-07-17T07:43:10.244Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8208, 45, 'TEXT', ' Leo woke up, showered, then got dressed. After getting dressed, he ate breakfast and left for work. Question: What did Leo do right after showering?', NULL, '["Got dressed","Woke up","Left for work","Ate breakfast"]', 'A) Got dressed', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:10.399Z', '2026-07-17T07:43:10.399Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8209, 45, 'TEXT', ' The chef chopped the vegetables first. Then he heated the oil in the pan. After the oil was hot, he added the vegetables and stirred them. Question: What did the chef do before adding the vegetables to the pan?', NULL, '["Stirred them","Served the dish","Chopped the vegetables","Heated the oil"]', 'D) Heated the oil', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:10.554Z', '2026-07-17T07:43:10.554Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8210, 45, 'TEXT', ' Anna packed her suitcase the night before. In the morning, she had breakfast, then called a taxi. The taxi arrived and took her to the airport. Question: What did Anna do right after having breakfast?', NULL, '["Called a taxi","Boarded the plane","Packed her suitcase","Went to the airport"]', 'A) Called a taxi', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:10.709Z', '2026-07-17T07:43:10.709Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8211, 45, 'TEXT', ' The gardener watered the plants first. Then he trimmed the hedges. After trimming, he raked the fallen leaves and finally swept the path. Question: What did the gardener do immediately after watering the plants?', NULL, '["Trimmed the hedges","Planted seeds","Swept the path","Raked the leaves"]', 'A) Trimmed the hedges', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:10.863Z', '2026-07-17T07:43:10.863Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8212, 45, 'TEXT', ' Ben brushed his teeth after dinner. Before dinner, he had finished his homework. Earlier in the day, he had played football with friends. Question: What did Ben do first in the day?', NULL, '["Finished his homework","Played football","Had dinner","Brushed his teeth"]', 'B) Played football', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:11.018Z', '2026-07-17T07:43:11.018Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8213, 45, 'TEXT', ' The plane taxied to the runway, then took off. After reaching cruising altitude, the pilot announced the flight time. Question: What happened immediately after the plane took off?', NULL, '["It taxied","It reached cruising altitude","It boarded passengers","It landed"]', 'B) It reached cruising altitude', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:11.171Z', '2026-07-17T07:43:11.171Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8194, 44, 'TEXT', ' The train station serves 100,000 passengers each day. It has 12 platforms. Trains run to 50 destinations. The station was renovated in 2020. It has 5 shops and 3 cafes. Question: How many platforms does the train station have?', NULL, '["14","10","12","8"]', 'C) 12', NULL, 'HARD', 1, TRUE, '2026-07-17T07:32:42.807Z', '2026-07-17T07:44:16.962Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8195, 44, 'TEXT', ' Tessa''s father is a winemaker. He owns a vineyard in France. He produces 50,000 bottles of wine each year. He has been making wine for 20 years. Tessa loves helping at harvest time. Question: How many bottles of wine does Tessa''s father produce each year?', NULL, '["50,000","75,000","10,000","25,000"]', 'D) 50,000', NULL, 'HARD', 1, TRUE, '2026-07-17T07:32:42.959Z', '2026-07-17T07:44:17.190Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8196, 44, 'TEXT', ' The air show had 100,000 visitors. There were 50 aircraft displays. The show lasted 2 days. Tickets cost £25 for adults and £15 for children. The show was held in June. Question: How much did children''s tickets cost?', NULL, '["£20","£25","£10","£15"]', 'A) £15', NULL, 'HARD', 1, TRUE, '2026-07-17T07:32:43.113Z', '2026-07-17T07:44:17.447Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8197, 44, 'TEXT', ' Arjun''s mother is a pharmacist. She works at a pharmacy on the high street. She has been a pharmacist for 18 years. She helps people with their medicines. Arjun is proud of her. Question: How long has Arjun''s mother been a pharmacist?', NULL, '["12 years","20 years","15 years","18 years"]', 'B) 18 years', NULL, 'HARD', 1, TRUE, '2026-07-17T07:32:43.267Z', '2026-07-17T07:44:17.676Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8198, 44, 'TEXT', ' The hospital has 500 beds. It has 20 operating theatres. It employs 2,000 staff members. The hospital was built in 2008. It is the largest hospital in the region. Question: How many staff members does the hospital employ?', NULL, '["1,500","1,000","2,500","2,000"]', 'C) 2,000', NULL, 'HARD', 1, TRUE, '2026-07-17T07:32:43.419Z', '2026-07-17T07:44:17.904Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8199, 44, 'TEXT', ' Alice''s brother is a pilot in the Royal Air Force. He flies fighter jets. He has flown 300 missions. He has been in the RAF for 12 years. Alice always watches the air shows he flies in. Question: How many missions has Alice''s brother flown?', NULL, '["100","200","400","300"]', 'D) 300', NULL, 'HARD', 1, TRUE, '2026-07-17T07:32:43.574Z', '2026-07-17T07:44:18.133Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8200, 44, 'TEXT', ' Priya joined a pottery class at the community centre. She attends every Wednesday evening after work. Her teacher, Mr. Adebayo, has been a potter for over 20 years. Priya has already made three bowls and is now learning to make a vase. Question: What is Priya currently learning to make?', NULL, '["A mug","A plate","A jug","A vase"]', 'B) A vase', NULL, 'HARD', 1, TRUE, '2026-07-17T07:32:43.728Z', '2026-07-17T07:44:18.363Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8215, 45, 'TEXT', ' The factory receives raw materials first. Workers then assemble the parts. After assembly, the products are tested, then packaged for shipping. Question: What happens right after the parts are assembled?', NULL, '["They are tested","They are packaged","Raw materials arrive","They are shipped"]', 'A) They are tested', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:11.478Z', '2026-07-17T07:43:11.478Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8216, 45, 'TEXT', ' James studied for two hours. He then took a short break. After the break, he practiced piano before going to bed. Question: What did James do immediately before going to bed?', NULL, '["Ate dinner","Studied","Took a break","Practiced piano"]', 'D) Practiced piano', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:11.632Z', '2026-07-17T07:43:11.632Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8217, 45, 'TEXT', ' The caterpillar ate leaves for weeks. It then formed a chrysalis. After some time inside the chrysalis, it emerged as a butterfly. Question: What happened right before the caterpillar became a butterfly?', NULL, '["It ate leaves","It hatched","It formed a chrysalis","It laid eggs"]', 'C) It formed a chrysalis', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:11.785Z', '2026-07-17T07:43:11.785Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8218, 45, 'TEXT', ' Ella arrived at the party at 6 pm. Dinner was served at 7 pm. The cake was cut at 8 pm, and dancing began at 9 pm. Question: What happened right after dinner was served?', NULL, '["The cake was cut","Dancing began","Guests left","Ella arrived"]', 'A) The cake was cut', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:11.939Z', '2026-07-17T07:43:11.939Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8219, 45, 'TEXT', ' Jack fed the dog first. Then he took the dog for a walk. After the walk, he gave the dog a bath and brushed its fur. Question: What did Jack do immediately after the walk?', NULL, '["Took the dog for a walk","Gave the dog a bath","Fed the dog","Brushed its fur"]', 'B) Gave the dog a bath', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:12.093Z', '2026-07-17T07:43:12.093Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8220, 45, 'TEXT', ' The seeds were sown in spring. The plants grew tall by summer. In autumn, the crops were harvested, and in winter the field lay empty. Question: What happened right after the plants grew tall?', NULL, '["Snow fell","Crops were harvested","Seeds were sown","The field lay empty"]', 'B) Crops were harvested', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:12.255Z', '2026-07-17T07:43:12.255Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8221, 45, 'TEXT', ' Priya opened her laptop first. She checked her emails, then joined the video call. After the call ended, she wrote a summary report. Question: What did Priya do right after checking her emails?', NULL, '["Opened her laptop","Joined the video call","Closed her laptop","Wrote a report"]', 'B) Joined the video call', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:12.423Z', '2026-07-17T07:43:12.423Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8222, 45, 'TEXT', ' The bakery mixed the dough at 5 am. It rose for an hour, then was baked at 6:30 am. The bread was sold starting at 8 am. Question: What happened right after the dough was mixed?', NULL, '["It was sliced","It rose for an hour","It was sold","It was baked"]', 'B) It rose for an hour', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:12.582Z', '2026-07-17T07:43:12.582Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8223, 45, 'TEXT', ' Sam tied his shoelaces first. Then he stretched for five minutes. After stretching, he started his morning run. Question: What did Sam do immediately before his run?', NULL, '["Cooled down","Ate breakfast","Stretched","Tied his shoelaces"]', 'C) Stretched', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:12.738Z', '2026-07-17T07:43:12.738Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8224, 45, 'TEXT', ' The nurse checked the patient''s temperature first. Then she measured blood pressure. After that, she recorded the results in the chart. Question: What did the nurse do right after measuring blood pressure?', NULL, '["Gave medicine","Recorded results","Checked temperature","Called the doctor"]', 'B) Recorded results', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:12.892Z', '2026-07-17T07:43:12.892Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8225, 45, 'TEXT', ' Lucy watered the flowers in the morning. In the afternoon, she pulled out the weeds. In the evening, she added fertiliser to the soil. Question: What did Lucy do between watering and adding fertiliser?', NULL, '["Watered again","Pulled out weeds","Planted new flowers","Mowed the lawn"]', 'B) Pulled out weeds', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:13.046Z', '2026-07-17T07:43:13.046Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8226, 45, 'TEXT', ' The librarian stamped the due date first. Then she scanned the book''s barcode. After scanning, she handed the book to the student. Question: What did the librarian do right after stamping the due date?', NULL, '["Handed the book over","Scanned the barcode","Shelved the book","Checked the student''s card"]', 'B) Scanned the barcode', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:13.206Z', '2026-07-17T07:43:13.206Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8227, 45, 'TEXT', ' The football match kicked off at 3 pm. A goal was scored in the 20th minute. Half-time began at 45 minutes, and the second half started at 60 minutes. Question: What happened right after the goal was scored?', NULL, '["Half-time began","The match kicked off","The match ended","The second half started"]', 'A) Half-time began', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:13.363Z', '2026-07-17T07:43:13.363Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8228, 45, 'TEXT', ' Grandma kneaded the dough first. She let it rest for 30 minutes. After resting, she rolled it out and cut it into shapes. Question: What did Grandma do right after letting the dough rest?', NULL, '["Cut it into shapes","Rolled it out","Baked it","Kneaded the dough"]', 'B) Rolled it out', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:13.520Z', '2026-07-17T07:43:13.520Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8229, 45, 'TEXT', ' The bus arrived at the stop at 8 am. Passengers boarded, and the doors closed at 8:05 am. The bus departed a minute later. Question: What happened right after passengers boarded?', NULL, '["The doors closed","Tickets were checked","The bus arrived","The bus departed"]', 'A) The doors closed', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:13.676Z', '2026-07-17T07:43:13.676Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8230, 45, 'TEXT', ' Daniel switched on the computer. He entered his password, then opened his email inbox. After reading his emails, he began writing a reply. Question: What did Daniel do right after opening his inbox?', NULL, '["Read his emails","Wrote a reply","Entered his password","Switched off the computer"]', 'A) Read his emails', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:13.833Z', '2026-07-17T07:43:13.833Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8231, 45, 'TEXT', ' The rocket engines ignited first. The rocket then lifted off the pad. After a few minutes, it separated from its boosters. Question: What happened right after the engines ignited?', NULL, '["It entered orbit","It separated from boosters","It landed","It lifted off"]', 'D) It lifted off', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:13.993Z', '2026-07-17T07:43:13.993Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8232, 45, 'TEXT', ' Chloe cut the vegetables first. She then boiled water in a pot. After the water boiled, she added the vegetables to cook. Question: What did Chloe do right before adding the vegetables to the pot?', NULL, '["Boiled water","Washed the pot","Served the soup","Cut the vegetables"]', 'A) Boiled water', NULL, 'EASY', 1, TRUE, '2026-07-17T07:43:14.145Z', '2026-07-17T07:43:14.145Z') ON CONFLICT DO NOTHING;
