INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8411, 46, 'TEXT', ' Ben did not water his garden for two weeks. The flowers wilted and died. Question: Why did the flowers die?', NULL, '["Ben did not water them","They were picked","It was too cold","Too much rain fell"]', 'A) Ben did not water them', NULL, 'EASY', 1, TRUE, '2026-07-17T08:14:57.727Z', '2026-07-17T08:14:57.727Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8412, 46, 'TEXT', ' The bakery ran out of flour. They could not bake any more bread that day. Question: Why could the bakery not bake more bread?', NULL, '["They closed early","The oven broke","They ran out of flour","There were no customers"]', 'C) They ran out of flour', NULL, 'EASY', 1, TRUE, '2026-07-17T08:14:57.921Z', '2026-07-17T08:14:57.921Z') ON CONFLICT DO NOTHING;
