INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8414, 46, 'TEXT', ' The football match was cancelled because of the thunderstorm. Question: Why was the football match cancelled?', NULL, '["The referee was ill","The stadium was full","There was a thunderstorm","The players were tired"]', 'C) There was a thunderstorm', NULL, 'EASY', 1, TRUE, '2026-07-17T08:14:58.305Z', '2026-07-17T08:14:58.305Z') ON CONFLICT DO NOTHING;
