INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8416, 46, 'TEXT', ' The bridge was closed for repairs. Traffic had to take a longer route. Question: Why did traffic take a longer route?', NULL, '["There was a parade","It was a holiday","The bridge was new","The bridge was closed for repairs"]', 'D) The bridge was closed for repairs', NULL, 'EASY', 1, TRUE, '2026-07-17T08:14:58.689Z', '2026-07-17T08:14:58.689Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8417, 46, 'TEXT', ' Grace forgot her umbrella at home. She got soaked walking to school in the rain. Question: Why did Grace get soaked?', NULL, '["She took the bus","It was sunny","She wore a raincoat","She forgot her umbrella"]', 'D) She forgot her umbrella', NULL, 'EASY', 1, TRUE, '2026-07-17T08:14:58.881Z', '2026-07-17T08:14:58.881Z') ON CONFLICT DO NOTHING;
