INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8419, 46, 'TEXT', ' Noah ran five miles every morning. He became much fitter over time. Question: Why did Noah become fitter?', NULL, '["He stopped exercising","He ate junk food","He ran every morning","He slept all day"]', 'C) He ran every morning', NULL, 'EASY', 1, TRUE, '2026-07-17T08:14:59.266Z', '2026-07-17T08:14:59.266Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8420, 46, 'TEXT', ' The milk was left out of the fridge overnight. It turned sour by morning. Question: Why did the milk turn sour?', NULL, '["It was left out overnight","It was heated","It was refrigerated","It was fresh"]', 'A) It was left out overnight', NULL, 'EASY', 1, TRUE, '2026-07-17T08:14:59.461Z', '2026-07-17T08:14:59.461Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8421, 46, 'TEXT', ' Chloe practiced her lines every day before the play. She performed confidently on stage. Question: Why did Chloe perform confidently?', NULL, '["She practiced every day","She skipped rehearsals","She was nervous","She forgot her lines"]', 'A) She practiced every day', NULL, 'EASY', 1, TRUE, '2026-07-17T08:14:59.653Z', '2026-07-17T08:14:59.653Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8422, 46, 'TEXT', ' The farmer did not rotate his crops. The soil became less fertile over the years. Question: Why did the soil become less fertile?', NULL, '["The farmer rotated crops well","It rained too much","New seeds were planted","The farmer did not rotate his crops"]', 'D) The farmer did not rotate his crops', NULL, 'EASY', 1, TRUE, '2026-07-17T08:14:59.848Z', '2026-07-17T08:14:59.848Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8423, 46, 'TEXT', ' Daniel left his phone in the sun for hours. The battery overheated and stopped working. Question: Why did the phone''s battery stop working?', NULL, '["It was left in the sun","It was charged normally","It was turned off","It was kept in a case"]', 'A) It was left in the sun', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:00.045Z', '2026-07-17T08:15:00.045Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8424, 46, 'TEXT', ' The dog barked loudly at the postman every day. The postman became afraid to approach the house. Question: Why did the postman become afraid?', NULL, '["The dog barked at him","The dog was friendly","The house was empty","The postman liked dogs"]', 'A) The dog barked at him', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:00.237Z', '2026-07-17T08:15:00.237Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8425, 46, 'TEXT', ' Emma ate a balanced diet and exercised regularly. She stayed healthy all year. Question: Why did Emma stay healthy?', NULL, '["She never left home","She ate junk food","She had a balanced diet and exercised","She slept very little"]', 'C) She had a balanced diet and exercised', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:00.430Z', '2026-07-17T08:15:00.430Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8426, 46, 'TEXT', ' The candle burned for hours. It eventually melted down completely. Question: Why did the candle melt down completely?', NULL, '["It was never lit","It was blown out immediately","It was frozen","It burned for hours"]', 'D) It burned for hours', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:00.622Z', '2026-07-17T08:15:00.622Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8427, 46, 'TEXT', ' Oliver did not wear his seatbelt. He was thrown forward when the car braked suddenly. Question: Why was Oliver thrown forward?', NULL, '["He was sitting still","The car was parked","He wore his seatbelt","He did not wear his seatbelt"]', 'D) He did not wear his seatbelt', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:00.817Z', '2026-07-17T08:15:00.817Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8429, 46, 'TEXT', ' Zoe shared her lunch with a hungry classmate. Her classmate felt grateful and happy. Question: Why did Zoe''s classmate feel grateful?', NULL, '["Zoe ate alone","Zoe left early","Zoe shared her lunch","Zoe ignored him"]', 'C) Zoe shared her lunch', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:01.211Z', '2026-07-17T08:15:01.211Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8430, 46, 'TEXT', ' The company cut its prices significantly. Sales increased rapidly. Question: Why did sales increase?', NULL, '["Prices were cut","The shop closed","Products were removed","Prices increased"]', 'A) Prices were cut', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:01.407Z', '2026-07-17T08:15:01.407Z') ON CONFLICT DO NOTHING;
