INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8432, 46, 'TEXT', ' Liam forgot to charge his laptop. It shut down during his presentation. Question: Why did the laptop shut down?', NULL, '["Liam forgot to charge it","It was plugged in","It was brand new","It was fully charged"]', 'A) Liam forgot to charge it', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:01.797Z', '2026-07-17T08:15:01.797Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8433, 46, 'TEXT', ' The team trained together every week. They won the championship at the end of the season. Question: Why did the team win the championship?', NULL, '["They had no coach","They played fewer games","They trained together every week","They skipped practice"]', 'C) They trained together every week', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:01.991Z', '2026-07-17T08:15:01.991Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8434, 46, 'TEXT', ' The pipe burst in the basement. Water flooded the entire floor. Question: Why did the basement flood?', NULL, '["The pipe burst","It was cleaned","The pipe was fixed","The basement was empty"]', 'A) The pipe burst', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:02.185Z', '2026-07-17T08:15:02.185Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8435, 46, 'TEXT', ' Ava did not proofread her essay. She lost marks for spelling mistakes. Question: Why did Ava lose marks?', NULL, '["She did not proofread her essay","She used a dictionary","She wrote too little","She proofread carefully"]', 'A) She did not proofread her essay', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:02.379Z', '2026-07-17T08:15:02.379Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8436, 46, 'TEXT', ' The forest had not seen rain for months. A wildfire broke out and spread quickly. Question: Why did the wildfire spread quickly?', NULL, '["Firefighters arrived early","The forest was very wet","It began to rain","The forest had not seen rain for months"]', 'D) The forest had not seen rain for months', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:02.571Z', '2026-07-17T08:15:02.571Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8437, 46, 'TEXT', ' Ryan apologised sincerely to his friend. His friend forgave him and they made up. Question: Why did Ryan''s friend forgive him?', NULL, '["Ryan argued more","Ryan apologised sincerely","Ryan left the room","Ryan ignored him"]', 'B) Ryan apologised sincerely', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:02.764Z', '2026-07-17T08:15:02.764Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8438, 46, 'TEXT', ' The store''s air conditioning broke on a hot day. Customers left quickly because of the heat. Question: Why did customers leave quickly?', NULL, '["There was a sale","The air conditioning broke","The store opened late","The store was cool"]', 'B) The air conditioning broke', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:02.956Z', '2026-07-17T08:15:02.956Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8439, 46, 'TEXT', ' Sophie recycled her waste every week. She reduced the amount of rubbish her family produced. Question: Why did Sophie''s family produce less rubbish?', NULL, '["She ignored the bins","She bought more products","She stopped recycling","She recycled every week"]', 'D) She recycled every week', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:03.149Z', '2026-07-17T08:15:03.149Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8440, 46, 'TEXT', ' The teacher spoke too quietly. Students at the back could not hear the lesson. Question: Why could students not hear the lesson?', NULL, '["The teacher spoke too quietly","The teacher used a microphone","Students sat at the front","The room was silent"]', 'A) The teacher spoke too quietly', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:03.344Z', '2026-07-17T08:15:03.344Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8441, 46, 'TEXT', ' The cyclist did not check his brakes before the ride. He was unable to stop in time and crashed. Question: Why did the cyclist crash?', NULL, '["He used a helmet","He rode slowly","He checked his brakes","He did not check his brakes"]', 'D) He did not check his brakes', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:03.536Z', '2026-07-17T08:15:03.536Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8442, 46, 'TEXT', ' The bees pollinated the flowers in the orchard. The trees produced a large harvest of fruit. Question: Why did the trees produce a large harvest?', NULL, '["The flowers were removed","It did not rain","The bees left the orchard","The bees pollinated the flowers"]', 'D) The bees pollinated the flowers', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:03.728Z', '2026-07-17T08:15:03.728Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8443, 46, 'TEXT', ' Jake spent all his allowance on video games. He had no money left for his friend''s birthday gift. Question: Why did Jake have no money for the gift?', NULL, '["He didn''t buy anything","He spent it on video games","He saved his allowance","He earned extra money"]', 'B) He spent it on video games', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:03.925Z', '2026-07-17T08:15:03.925Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8444, 46, 'TEXT', ' The company invested heavily in advertising. Its brand became widely recognised. Question: Why did the brand become widely recognised?', NULL, '["The company invested heavily in advertising","The company stopped advertising","The company reduced staff","The company closed down"]', 'A) The company invested heavily in advertising', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:04.118Z', '2026-07-17T08:15:04.118Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8445, 46, 'TEXT', ' The children left food out overnight. Ants swarmed into the kitchen the next morning. Question: Why did ants swarm the kitchen?', NULL, '["The kitchen was cleaned","It was winter","Food was left out overnight","The food was put away"]', 'C) Food was left out overnight', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:04.311Z', '2026-07-17T08:15:04.311Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8446, 46, 'TEXT', ' Maya wore sunscreen at the beach. She did not get sunburned. Question: Why did Maya not get sunburned?', NULL, '["She stayed indoors","It was cloudy all day","She avoided the beach","She wore sunscreen"]', 'D) She wore sunscreen', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:04.596Z', '2026-07-17T08:15:04.596Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8447, 46, 'TEXT', ' The city built more cycle lanes. More people started cycling to work. Question: Why did more people start cycling to work?', NULL, '["Petrol became cheaper","The city built more cycle lanes","Buses became free","The city removed cycle lanes"]', 'B) The city built more cycle lanes', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:04.790Z', '2026-07-17T08:15:04.790Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8448, 46, 'TEXT', ' The dog chewed through the electrical wire. The power in the house went out. Question: Why did the power go out?', NULL, '["The wire was replaced","The dog was asleep","The dog chewed the wire","A storm hit the house"]', 'C) The dog chewed the wire', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:04.982Z', '2026-07-17T08:15:04.982Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8449, 46, 'TEXT', ' The students worked together on the project. They finished it ahead of schedule. Question: Why did the students finish ahead of schedule?', NULL, '["They started late","They lost the materials","They worked together","They worked alone"]', 'C) They worked together', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:05.177Z', '2026-07-17T08:15:05.177Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8450, 46, 'TEXT', ' The river overflowed its banks after days of rain. Nearby homes were flooded. Question: Why were the homes flooded?', NULL, '["The river dried up","The river overflowed","A dam was built","It stopped raining"]', 'B) The river overflowed', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:05.375Z', '2026-07-17T08:15:05.375Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8451, 46, 'TEXT', ' Leo skipped breakfast before his exam. He felt tired and struggled to concentrate. Question: Why did Leo struggle to concentrate?', NULL, '["He slept well","He drank water","He skipped breakfast","He ate a big breakfast"]', 'C) He skipped breakfast', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:05.572Z', '2026-07-17T08:15:05.572Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8452, 46, 'TEXT', ' The shop offered a large discount on shoes. Many customers rushed in to buy them. Question: Why did many customers rush in?', NULL, '["Prices increased","The shop closed","A large discount was offered","Shoes were removed from sale"]', 'C) A large discount was offered', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:05.765Z', '2026-07-17T08:15:05.765Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8453, 46, 'TEXT', ' The children left their toys scattered on the floor. Their mother tripped over them in the dark. Question: Why did their mother trip?', NULL, '["The lights were on","The toys were scattered on the floor","The toys were put away","The floor was clean"]', 'B) The toys were scattered on the floor', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:05.957Z', '2026-07-17T08:15:05.957Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8454, 46, 'TEXT', ' Isla practiced her speech many times. She delivered it smoothly without any mistakes. Question: Why did Isla deliver her speech smoothly?', NULL, '["She read from a script","She skipped rehearsal","She practiced many times","She never practiced"]', 'C) She practiced many times', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:06.149Z', '2026-07-17T08:15:06.149Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8455, 46, 'TEXT', ' The factory released chemicals into the river. Fish in the river began to die. Question: Why did the fish die?', NULL, '["More fish were added","The river froze","Chemicals were released into the river","The river was clean"]', 'C) Chemicals were released into the river', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:06.342Z', '2026-07-17T08:15:06.342Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8456, 46, 'TEXT', ' Owen forgot his lunch at home. He felt hungry all afternoon at school. Question: Why did Owen feel hungry?', NULL, '["He forgot his lunch at home","He ate two lunches","He brought a big lunch","He wasn''t at school"]', 'A) He forgot his lunch at home', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:06.534Z', '2026-07-17T08:15:06.534Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8457, 46, 'TEXT', ' The team practiced their fire drill regularly. Everyone evacuated safely and quickly during the real emergency. Question: Why did everyone evacuate safely?', NULL, '["They practiced the fire drill regularly","The building had no exits","They never practiced drills","The alarm did not sound"]', 'A) They practiced the fire drill regularly', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:06.727Z', '2026-07-17T08:15:06.727Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8458, 46, 'TEXT', ' The garden was not weeded for months. Weeds took over and choked the vegetables. Question: Why did the weeds choke the vegetables?', NULL, '["It rained every day","The garden was weeded often","New vegetables were planted","The garden was not weeded for months"]', 'D) The garden was not weeded for months', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:06.920Z', '2026-07-17T08:15:06.920Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8459, 46, 'TEXT', ' Nina saved a portion of her salary every month. She was able to afford a holiday within a year. Question: Why could Nina afford a holiday?', NULL, '["She borrowed money","She spent all her salary","She lost her job","She saved a portion every month"]', 'D) She saved a portion every month', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:07.112Z', '2026-07-17T08:15:07.112Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8460, 46, 'TEXT', ' The bridge''s supports rusted over decades without maintenance. It eventually collapsed. Question: Why did the bridge collapse?', NULL, '["Its supports rusted from lack of maintenance","It was newly built","It was well maintained","Traffic was light"]', 'A) Its supports rusted from lack of maintenance', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:07.303Z', '2026-07-17T08:15:07.303Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8461, 46, 'TEXT', ' The teacher praised the students'' hard work. The students felt motivated to work even harder. Question: Why did the students feel motivated?', NULL, '["The teacher criticised them","The teacher praised their hard work","The teacher ignored them","The teacher left the room"]', 'B) The teacher praised their hard work', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:07.497Z', '2026-07-17T08:15:07.497Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8462, 46, 'TEXT', ' The company failed to update its software. Hackers exploited the old system and stole data. Question: Why did hackers steal the data?', NULL, '["The software was updated regularly","No data was stored","The company failed to update its software","The system was replaced"]', 'C) The company failed to update its software', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:07.690Z', '2026-07-17T08:15:07.690Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8463, 46, 'TEXT', ' The runner trained on hills every week. She built strong leg muscles for the race. Question: Why did the runner build strong leg muscles?', NULL, '["She trained on hills every week","She ran on flat ground only","She avoided exercise","She rested all week"]', 'A) She trained on hills every week', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:07.886Z', '2026-07-17T08:15:07.886Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8464, 46, 'TEXT', ' The shopkeeper left the freezer door open overnight. All the frozen food spoiled by morning. Question: Why did the frozen food spoil?', NULL, '["The freezer door was closed","The freezer was very cold","The food was fresh","The freezer door was left open"]', 'D) The freezer door was left open', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:08.080Z', '2026-07-17T08:15:08.080Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8465, 46, 'TEXT', ' The students ignored the fire alarm, thinking it was a drill. They were late to evacuate during the real fire. Question: Why were the students late to evacuate?', NULL, '["They left early","The alarm was very loud","They responded immediately","They ignored the alarm, thinking it was a drill"]', 'D) They ignored the alarm, thinking it was a drill', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:08.274Z', '2026-07-17T08:15:08.274Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8466, 46, 'TEXT', ' The company reduced its carbon emissions. Air quality in the nearby town improved. Question: Why did air quality improve?', NULL, '["More cars were used","Emissions increased","The company reduced its carbon emissions","The factory closed"]', 'C) The company reduced its carbon emissions', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:08.468Z', '2026-07-17T08:15:08.468Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8467, 46, 'TEXT', ' Ethan left his bike unlocked outside the shop. It was stolen within minutes. Question: Why was the bike stolen?', NULL, '["It was locked securely","It was left unlocked","It was kept indoors","It had a tracker"]', 'B) It was left unlocked', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:08.663Z', '2026-07-17T08:15:08.663Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8468, 46, 'TEXT', ' The chef added too much salt to the soup. Customers complained about the taste. Question: Why did customers complain?', NULL, '["The soup had no salt","The chef used less salt","The chef added too much salt","The soup was perfect"]', 'C) The chef added too much salt', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:08.855Z', '2026-07-17T08:15:08.855Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8469, 46, 'TEXT', ' The students revised together in a study group. They understood the topic much better before the test. Question: Why did the students understand the topic better?', NULL, '["They revised together in a study group","They skipped revision","They did not attend class","They studied alone"]', 'A) They revised together in a study group', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:09.050Z', '2026-07-17T08:15:09.050Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8470, 46, 'TEXT', ' The farmer used too much fertiliser on his field. The excess washed into the river and caused pollution. Question: Why did the river become polluted?', NULL, '["The farmer used too much fertiliser","The field was left empty","The farmer used too little fertiliser","No fertiliser was used"]', 'A) The farmer used too much fertiliser', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:09.242Z', '2026-07-17T08:15:09.242Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8471, 46, 'TEXT', ' The child touched the hot stove without warning. He burned his hand instantly. Question: Why did the child burn his hand?', NULL, '["The stove was cold","He avoided the stove","He wore gloves","He touched the hot stove"]', 'D) He touched the hot stove', NULL, 'EASY', 1, TRUE, '2026-07-17T08:15:09.435Z', '2026-07-17T08:15:09.435Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8472, 46, 'TEXT', ' The government introduced a new tax on plastic bags. As a result, the use of reusable bags increased significantly across the country, and plastic waste in landfills decreased. Question: What was the effect of the new plastic bag tax?', NULL, '["Plastic waste increased","Plastic bags became free","Reusable bag use increased and plastic waste decreased","Landfills expanded"]', 'C) Reusable bag use increased and plastic waste decreased', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:09.631Z', '2026-07-17T08:15:09.631Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (10454, 56, 'TEXT', 'Which sentence appeals to the sense of taste?', NULL, '["The music was beautiful.","The blanket was warm.","The sky was clear.","The chocolate was rich and creamy."]', 'D) The chocolate was rich and creamy.', NULL, 'EASY', 1, TRUE, '2026-07-17T12:28:40.457Z', '2026-07-17T12:28:40.457Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8473, 46, 'TEXT', ' Years of overfishing depleted the local fish population. Fishermen had to travel further out to sea, increasing their fuel costs and reducing their profits. Question: Why did fishermen''s profits decrease?', NULL, '["Fishermen stopped working","Fuel became cheaper","Fish populations grew","Overfishing depleted fish, raising fuel costs"]', 'D) Overfishing depleted fish, raising fuel costs', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:09.824Z', '2026-07-17T08:15:09.824Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8474, 46, 'TEXT', ' The city invested in a new public transport system. Traffic congestion decreased, and air pollution levels dropped noticeably within two years. Question: Why did air pollution levels drop?', NULL, '["The city banned buses","The new public transport system reduced traffic","Roads were closed permanently","More cars were bought"]', 'B) The new public transport system reduced traffic', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:10.016Z', '2026-07-17T08:15:10.016Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8475, 46, 'TEXT', ' A sudden frost damaged the citrus crops in Florida. This led to a shortage of oranges, causing prices to rise sharply across the country. Question: Why did orange prices rise?', NULL, '["There was a surplus of oranges","A frost damaged the crops, causing a shortage","Prices were fixed by law","Farmers grew more oranges"]', 'B) A frost damaged the crops, causing a shortage', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:10.210Z', '2026-07-17T08:15:10.210Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8476, 46, 'TEXT', ' The company failed to train its new employees properly. This resulted in frequent errors, which damaged the company''s reputation and led to a loss of customers. Question: Why did the company lose customers?', NULL, '["Customers received discounts","The company hired fewer staff","Employees were well trained","Poor training led to errors that damaged its reputation"]', 'D) Poor training led to errors that damaged its reputation', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:10.466Z', '2026-07-17T08:15:10.466Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8477, 46, 'TEXT', ' Deforestation in the region removed trees that once absorbed rainfall. Consequently, the area became prone to severe flooding during heavy rains. Question: Why did the area become prone to flooding?', NULL, '["Deforestation removed trees that absorbed rainfall","More trees were planted","Rainfall decreased","A dam was constructed"]', 'A) Deforestation removed trees that absorbed rainfall', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:10.658Z', '2026-07-17T08:15:10.658Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8478, 46, 'TEXT', ' The museum extended its opening hours and lowered ticket prices. Visitor numbers doubled within six months. Question: Why did visitor numbers double?', NULL, '["The museum closed early","Ticket prices increased","Opening hours were extended and prices lowered","Exhibits were removed"]', 'C) Opening hours were extended and prices lowered', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:10.852Z', '2026-07-17T08:15:10.852Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8479, 46, 'TEXT', ' The athlete ignored her coach''s advice about rest and continued training intensely. She suffered a serious injury that kept her out of competition for a year. Question: Why was the athlete out of competition for a year?', NULL, '["She followed her coach''s advice","She ignored advice about rest and got injured","She retired early","She won a medal"]', 'B) She ignored advice about rest and got injured', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:11.045Z', '2026-07-17T08:15:11.045Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8480, 46, 'TEXT', ' Interest rates were raised by the central bank to control inflation. Borrowing became more expensive, and consumer spending slowed down as a result. Question: Why did consumer spending slow down?', NULL, '["Inflation disappeared","Interest rates were raised, making borrowing expensive","Interest rates were lowered","Spending was encouraged"]', 'B) Interest rates were raised, making borrowing expensive', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:11.237Z', '2026-07-17T08:15:11.237Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8481, 46, 'TEXT', ' The school introduced a mentoring programme for struggling students. Attendance and grades improved significantly across the affected classes. Question: Why did grades improve?', NULL, '["Homework was removed","Classes were made larger","The mentoring programme was cancelled","The mentoring programme supported struggling students"]', 'D) The mentoring programme supported struggling students', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:11.429Z', '2026-07-17T08:15:11.429Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8482, 46, 'TEXT', ' A software bug caused the company''s servers to crash during peak usage. Customers were unable to access their accounts for several hours, leading to widespread complaints. Question: Why were customers unable to access their accounts?', NULL, '["The company added more servers","A software bug caused the servers to crash","Usage was low that day","The servers were upgraded"]', 'B) A software bug caused the servers to crash', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:11.621Z', '2026-07-17T08:15:11.621Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8483, 46, 'TEXT', ' The introduction of an invasive species disrupted the local ecosystem. Native species declined rapidly as they competed for the same limited resources. Question: Why did native species decline?', NULL, '["Resources became abundant","The invasive species left the area","The invasive species competed for limited resources","A new native species arrived"]', 'C) The invasive species competed for limited resources', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:11.817Z', '2026-07-17T08:15:11.817Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8484, 46, 'TEXT', ' The airline overbooked several flights to maximise profit. Passengers were frequently denied boarding, resulting in numerous complaints and a damaged public image. Question: Why did the airline''s public image suffer?', NULL, '["Flights were underbooked","Flights were cancelled by weather","Overbooking led to denied boarding and complaints","Ticket prices were lowered"]', 'C) Overbooking led to denied boarding and complaints', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:12.012Z', '2026-07-17T08:15:12.012Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8485, 46, 'TEXT', ' Regular exercise improved the patient''s cardiovascular health over several months. Her doctor reduced her blood pressure medication as a result. Question: Why was the patient''s medication reduced?', NULL, '["She stopped exercising","Her health worsened","Regular exercise improved her cardiovascular health","She changed doctors"]', 'C) Regular exercise improved her cardiovascular health', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:12.204Z', '2026-07-17T08:15:12.204Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8486, 46, 'TEXT', ' A prolonged drought reduced water levels in the reservoir. The city had to introduce water rationing to conserve the remaining supply. Question: Why did the city introduce water rationing?', NULL, '["Water levels were too high","It rained excessively","A drought reduced reservoir water levels","A new reservoir was built"]', 'C) A drought reduced reservoir water levels', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:12.406Z', '2026-07-17T08:15:12.406Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8487, 46, 'TEXT', ' The factory automated much of its production line. Output increased, but many workers lost their jobs as a result. Question: Why did many workers lose their jobs?', NULL, '["Production was automated","The factory closed completely","Output decreased","The factory hired more staff"]', 'A) Production was automated', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:12.603Z', '2026-07-17T08:15:12.603Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8488, 46, 'TEXT', ' Excessive use of antibiotics in farming contributed to the rise of drug-resistant bacteria. This made certain infections much harder to treat in hospitals. Question: Why did infections become harder to treat?', NULL, '["Excessive antibiotic use led to drug-resistant bacteria","Antibiotic use decreased","New antibiotics were discovered","Farming practices improved"]', 'A) Excessive antibiotic use led to drug-resistant bacteria', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:12.798Z', '2026-07-17T08:15:12.798Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8623, 47, 'TEXT', ' Nisha was scolded unfairly by a teacher in front of the whole class. Question: How did Nisha most likely feel?', NULL, '["Thrilled","Upset","Bored","Confident"]', 'B) Upset', NULL, 'EASY', 1, TRUE, '2026-07-17T08:25:15.969Z', '2026-07-17T08:25:15.969Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8489, 46, 'TEXT', ' The company launched an aggressive social media marketing campaign. Brand awareness rose sharply, leading to a significant increase in sales. Question: Why did sales increase significantly?', NULL, '["Prices were raised sharply","The marketing campaign was cancelled","An aggressive marketing campaign raised brand awareness","The company reduced advertising"]', 'C) An aggressive marketing campaign raised brand awareness', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:12.992Z', '2026-07-17T08:15:12.992Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8490, 46, 'TEXT', ' Heavy industrial activity released large amounts of sulphur dioxide into the atmosphere. This led to acid rain that damaged forests and lakes downwind. Question: Why were forests and lakes damaged?', NULL, '["Forests were newly planted","Lakes were drained","Sulphur dioxide caused acid rain","Industrial activity decreased"]', 'C) Sulphur dioxide caused acid rain', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:13.190Z', '2026-07-17T08:15:13.190Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8491, 46, 'TEXT', ' The hospital implemented stricter hygiene protocols after an infection outbreak. Infection rates dropped significantly within weeks. Question: Why did infection rates drop?', NULL, '["Fewer patients were treated","Hygiene protocols were relaxed","The hospital closed","Stricter hygiene protocols were implemented"]', 'D) Stricter hygiene protocols were implemented', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:13.389Z', '2026-07-17T08:15:13.389Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8492, 46, 'TEXT', ' A currency devaluation made the country''s exports cheaper for foreign buyers. Export volumes rose substantially over the following year. Question: Why did export volumes rise?', NULL, '["Exports were banned","The currency devaluation made exports cheaper","Import taxes increased","The currency strengthened"]', 'B) The currency devaluation made exports cheaper', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:13.586Z', '2026-07-17T08:15:13.586Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8493, 46, 'TEXT', ' The city planted thousands of trees along its streets. Over the following decade, average summer temperatures in the city centre decreased. Question: Why did summer temperatures decrease?', NULL, '["Roads were widened","Thousands of trees were planted, providing shade","More buildings were constructed","Trees were removed"]', 'B) Thousands of trees were planted, providing shade', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:13.779Z', '2026-07-17T08:15:13.779Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8494, 46, 'TEXT', ' The airline reduced its fuel efficiency standards to cut costs. As a result, its carbon emissions increased, drawing criticism from environmental groups. Question: Why did the airline''s carbon emissions increase?', NULL, '["Fewer flights were operated","The airline used renewable energy","Fuel efficiency standards were reduced to cut costs","Fuel efficiency standards improved"]', 'C) Fuel efficiency standards were reduced to cut costs', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:13.975Z', '2026-07-17T08:15:13.975Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8495, 46, 'TEXT', ' The teacher used more visual aids and hands-on activities in class. Student engagement and test scores improved noticeably. Question: Why did student engagement improve?', NULL, '["Visual aids and activities were removed","Tests were cancelled","The teacher used more visual aids and hands-on activities","Class sizes increased"]', 'C) The teacher used more visual aids and hands-on activities', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:14.169Z', '2026-07-17T08:15:14.169Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8496, 46, 'TEXT', ' Poor waste management in the city led to blocked drains. During heavy rainfall, this caused severe flooding in low-lying areas. Question: Why did severe flooding occur?', NULL, '["It did not rain that season","Drains were well maintained","New drains were installed","Poor waste management blocked the drains"]', 'D) Poor waste management blocked the drains', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:14.436Z', '2026-07-17T08:15:14.436Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8497, 46, 'TEXT', ' The company offered flexible working hours to its employees. Job satisfaction increased, and staff turnover fell considerably. Question: Why did staff turnover fall?', NULL, '["Salaries were cut","Flexible working hours increased job satisfaction","The office relocated","Working hours became stricter"]', 'B) Flexible working hours increased job satisfaction', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:14.662Z', '2026-07-17T08:15:14.662Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8498, 46, 'TEXT', ' A prolonged heatwave caused crops to wither across the region. Farmers reported one of the poorest harvests in decades. Question: Why did farmers report a poor harvest?', NULL, '["A prolonged heatwave caused crops to wither","New crops were planted","There was excessive rainfall","The heatwave ended quickly"]', 'A) A prolonged heatwave caused crops to wither', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:14.858Z', '2026-07-17T08:15:14.858Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8499, 46, 'TEXT', ' The government subsidised solar panel installation for homeowners. Adoption of solar energy increased dramatically across the country. Question: Why did solar energy adoption increase?', NULL, '["Solar panels became illegal","Subsidies were removed","Electricity became free","The government subsidised solar panel installation"]', 'D) The government subsidised solar panel installation', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:15.051Z', '2026-07-17T08:15:15.051Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8500, 46, 'TEXT', ' The company ignored early warning signs of declining quality. Customer complaints piled up, and eventually sales collapsed. Question: Why did sales eventually collapse?', NULL, '["The company improved quality immediately","Quality warning signs were addressed","The company ignored declining quality, causing complaints","Sales were consistently high"]', 'C) The company ignored declining quality, causing complaints', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:15.249Z', '2026-07-17T08:15:15.249Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8501, 46, 'TEXT', ' The introduction of stricter emissions standards forced car manufacturers to develop more efficient engines. Fuel consumption across the industry fell over the following decade. Question: Why did fuel consumption fall across the industry?', NULL, '["Fuel prices dropped","Stricter emissions standards led to more efficient engines","Emissions standards were relaxed","Car production stopped"]', 'B) Stricter emissions standards led to more efficient engines', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:15.442Z', '2026-07-17T08:15:15.442Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8502, 46, 'TEXT', ' A miscommunication between departments caused a delay in the product launch. This gave a competitor time to release a similar product first, damaging the company''s market position. Question: Why did the company''s market position suffer?', NULL, '["Communication improved","The competitor delayed their launch","The launch happened early","A miscommunication delayed the launch, letting a competitor go first"]', 'D) A miscommunication delayed the launch, letting a competitor go first', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:15.638Z', '2026-07-17T08:15:15.638Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8503, 46, 'TEXT', ' The reduction in predator populations allowed the deer population to grow unchecked. Overgrazing damaged the forest''s undergrowth significantly. Question: Why was the forest''s undergrowth damaged?', NULL, '["Fewer predators allowed deer to overgraze","The forest was replanted","Predator populations increased","The deer population declined"]', 'A) Fewer predators allowed deer to overgraze', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:15.830Z', '2026-07-17T08:15:15.830Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8504, 46, 'TEXT', ' The company switched to biodegradable packaging after customer pressure. Its reputation for sustainability improved, attracting environmentally conscious customers. Question: Why did the company attract more environmentally conscious customers?', NULL, '["It switched to biodegradable packaging","It increased plastic use","It stopped using packaging","It ignored customer pressure"]', 'A) It switched to biodegradable packaging', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:16.030Z', '2026-07-17T08:15:16.030Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8624, 47, 'TEXT', ' Daniel said goodbye to a close friend who was moving abroad for good. Question: How did Daniel most likely feel?', NULL, '["Grateful","Bored","Proud","Sad"]', 'D) Sad', NULL, 'EASY', 1, TRUE, '2026-07-17T08:25:16.123Z', '2026-07-17T08:25:16.123Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8505, 46, 'TEXT', ' Years of unchecked erosion stripped the topsoil from the hillside. Farmers found it increasingly difficult to grow crops there. Question: Why did farmers struggle to grow crops on the hillside?', NULL, '["New irrigation was installed","Topsoil was replenished","The hillside was flattened","Erosion stripped away the topsoil"]', 'D) Erosion stripped away the topsoil', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:16.222Z', '2026-07-17T08:15:16.222Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8506, 46, 'TEXT', ' The city introduced congestion charges for vehicles entering the centre. Traffic volumes fell, and public transport usage rose accordingly. Question: Why did public transport usage rise?', NULL, '["Public transport became more expensive","Congestion charges reduced traffic, shifting people to public transport","Congestion charges were removed","More roads were built"]', 'B) Congestion charges reduced traffic, shifting people to public transport', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:16.417Z', '2026-07-17T08:15:16.417Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8507, 46, 'TEXT', ' The startup underestimated its cash flow needs during expansion. It ran out of funds within a year and had to shut down operations. Question: Why did the startup shut down?', NULL, '["It had excess cash","It underestimated cash flow needs during expansion","Investors provided extra funding","It expanded too slowly"]', 'B) It underestimated cash flow needs during expansion', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:16.608Z', '2026-07-17T08:15:16.608Z') ON CONFLICT DO NOTHING;
