INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8522, 46, 'TEXT', ' A prolonged period of low interest rates encouraged excessive borrowing. This contributed to a housing bubble that eventually burst, causing a financial crisis. Question: Why did a financial crisis eventually occur?', NULL, '["Interest rates were too high","Low interest rates encouraged borrowing, creating a housing bubble","Housing prices remained stable","Borrowing was restricted"]', 'B) Low interest rates encouraged borrowing, creating a housing bubble', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:19.505Z', '2026-07-17T08:15:19.505Z') ON CONFLICT DO NOTHING;
