INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8540, 46, 'TEXT', ' A prolonged power outage during the storm caused the hospital''s backup generators to activate. Critical medical equipment continued to function without interruption. Question: Why did critical medical equipment continue functioning?', NULL, '["The backup generators failed","The storm was mild","Backup generators activated during the outage","The hospital had no equipment"]', 'C) Backup generators activated during the outage', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T08:15:22.991Z', '2026-07-17T08:15:22.991Z') ON CONFLICT DO NOTHING;
