INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8587, 46, 'TEXT', ' The systematic removal of apex predators from a national park decades ago allowed herbivore populations to grow unchecked, leading to overgrazing that altered river courses and reduced biodiversity across the entire ecosystem. Question: Why did biodiversity decline across the ecosystem?', NULL, '["Herbivore populations declined","Apex predator populations grew significantly","Removing apex predators allowed herbivore overgrazing, altering the ecosystem","River courses remained unchanged"]', 'C) Removing apex predators allowed herbivore overgrazing, altering the ecosystem', NULL, 'HARD', 1, TRUE, '2026-07-17T08:15:32.470Z', '2026-07-17T08:15:32.470Z') ON CONFLICT DO NOTHING;
