INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8589, 46, 'TEXT', ' A major bank''s failure to adequately assess the risks of a complex financial product led to massive losses when market conditions shifted unexpectedly, triggering a loss of confidence that spread to other financial institutions. Question: Why did a loss of confidence spread to other financial institutions?', NULL, '["Inadequate risk assessment led to massive losses when conditions shifted","The financial product performed as expected","Market conditions remained stable","The bank correctly assessed all risks"]', 'A) Inadequate risk assessment led to massive losses when conditions shifted', NULL, 'HARD', 1, TRUE, '2026-07-17T08:15:32.857Z', '2026-07-17T08:15:32.857Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8590, 46, 'TEXT', ' Decades of chronic underinvestment in a nation''s rail network resulted in ageing infrastructure that could not handle increasing freight volumes, forcing more goods onto roads and significantly increasing carbon emissions from transport. Question: Why did carbon emissions from transport increase significantly?', NULL, '["Road transport was banned","Freight volumes decreased","Underinvestment left rail unable to handle freight, shifting goods to roads","Rail infrastructure was heavily modernised"]', 'C) Underinvestment left rail unable to handle freight, shifting goods to roads', NULL, 'HARD', 1, TRUE, '2026-07-17T08:15:33.052Z', '2026-07-17T08:15:33.052Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8591, 46, 'TEXT', ' A pharmaceutical company''s early and substantial investment in vaccine research infrastructure allowed it to develop and distribute an effective vaccine far faster than competitors when a new pandemic emerged. Question: Why was the company able to develop a vaccine faster than competitors?', NULL, '["It had no vaccine research infrastructure","The pandemic delayed all vaccine development equally","Competitors had more advanced infrastructure","It had invested early and substantially in vaccine research infrastructure"]', 'D) It had invested early and substantially in vaccine research infrastructure', NULL, 'HARD', 1, TRUE, '2026-07-17T08:15:33.247Z', '2026-07-17T08:15:33.247Z') ON CONFLICT DO NOTHING;
