INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8593, 46, 'TEXT', ' A central government''s decision to decentralise decision-making power to local municipalities led, over time, to more tailored public services but also created significant disparities in service quality between wealthier and poorer regions. Question: Why did disparities in service quality emerge between regions?', NULL, '["All regions received identical funding","Local municipalities were abolished","Decision-making remained fully centralised","Decentralisation allowed tailored services but created disparities based on regional wealth"]', 'D) Decentralisation allowed tailored services but created disparities based on regional wealth', NULL, 'HARD', 1, TRUE, '2026-07-17T08:15:33.633Z', '2026-07-17T08:15:33.633Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8594, 46, 'TEXT', ' A technology company''s aggressive patent litigation strategy against smaller competitors, while protecting its intellectual property, ultimately stifled innovation in the industry as smaller firms became reluctant to develop new products for fear of lawsuits. Question: Why did smaller firms become reluctant to develop new products?', NULL, '["Aggressive patent litigation created fear of lawsuits among smaller firms","Larger firms stopped competing","Intellectual property protections were removed","Patent litigation decreased"]', 'A) Aggressive patent litigation created fear of lawsuits among smaller firms', NULL, 'HARD', 1, TRUE, '2026-07-17T08:15:33.829Z', '2026-07-17T08:15:33.829Z') ON CONFLICT DO NOTHING;
