INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8601, 46, 'TEXT', ' A scientific research team''s decision to share their raw data openly with the global community, rather than keeping it proprietary, accelerated the pace of related discoveries worldwide as other researchers built upon their findings. Question: Why did the pace of related discoveries accelerate worldwide?', NULL, '["The research findings were never published","Other researchers were barred from using the data","The data was kept proprietary","The team shared their raw data openly, allowing others to build on it"]', 'D) The team shared their raw data openly, allowing others to build on it', NULL, 'HARD', 1, TRUE, '2026-07-17T08:15:35.316Z', '2026-07-17T08:15:35.316Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8602, 47, 'TEXT', ' Maya could not remember a single answer during an important exam. Question: How did Maya most likely feel?', NULL, '["Confident","Excited","Worried","Confused"]', 'C) Worried', NULL, 'EASY', 1, TRUE, '2026-07-17T08:25:12.492Z', '2026-07-17T08:25:12.492Z') ON CONFLICT DO NOTHING;
