INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8766, 47, 'TEXT', ' Despite feeling utterly exhausted after the long shift, Poppy still stayed late to help a struggling colleague finish an urgent task. Question: Which best describes Poppy''s likely motivation for staying late?', NULL, '["Boredom with going home early","A sense of duty and care for a colleague that outweighed personal tiredness","A wish to appear better than the colleague","A requirement enforced by management"]', 'B) A sense of duty and care for a colleague that outweighed personal tiredness', NULL, 'HARD', 1, TRUE, '2026-07-17T08:25:38.913Z', '2026-07-17T08:25:38.913Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8767, 47, 'TEXT', ' Although Sam had trained harder than anyone else on the team, Sam downplayed personal effort whenever teammates mentioned it, quickly changing the subject each time. Question: What does this pattern most likely suggest about Sam''s feelings?', NULL, '["A discomfort with receiving attention, despite genuine pride in the effort made","A wish to be seen as lazy","Complete indifference to the training undertaken","Embarrassment about training too little"]', 'A) A discomfort with receiving attention, despite genuine pride in the effort made', NULL, 'HARD', 1, TRUE, '2026-07-17T08:25:39.069Z', '2026-07-17T08:25:39.069Z') ON CONFLICT DO NOTHING;
