INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8769, 47, 'TEXT', ' Wesley described the difficult diagnosis calmly to friends, using precise medical terms, yet avoided using the word "scared" even once during the entire conversation. Question: What does this careful avoidance most strongly suggest?', NULL, '["Confidence that no one would ask further questions","Total indifference to the diagnosis","Complete acceptance with no fear present","An attempt to maintain composure while masking genuine fear"]', 'D) An attempt to maintain composure while masking genuine fear', NULL, 'HARD', 1, TRUE, '2026-07-17T08:25:39.380Z', '2026-07-17T08:25:39.380Z') ON CONFLICT DO NOTHING;
