INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8783, 47, 'TEXT', ' Kian accepted the award graciously on stage, but later confided that the achievement felt hollow, since a close friend had missed out on the same recognition. Question: Which best describes Kian''s true feelings while accepting the award?', NULL, '["Genuine achievement dampened by concern for a friend''s disappointment","Pure, uncomplicated joy at winning","Resentment towards the judges","Complete indifference to the award itself"]', 'A) Genuine achievement dampened by concern for a friend''s disappointment', NULL, 'HARD', 1, TRUE, '2026-07-17T08:25:41.546Z', '2026-07-17T08:25:41.546Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8784, 47, 'TEXT', ' Selin agreed enthusiastically to join the new club, but found excuses to miss the first three meetings in a row. Question: Which is the most reasonable inference about Selin''s true feelings toward the club?', NULL, '["Complete excitement with no hesitation at all","A hidden reluctance that contradicts the outward enthusiasm shown earlier","A genuine scheduling problem every single week","Total indifference to whether the club continued"]', 'B) A hidden reluctance that contradicts the outward enthusiasm shown earlier', NULL, 'HARD', 1, TRUE, '2026-07-17T08:25:41.700Z', '2026-07-17T08:25:41.700Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8785, 47, 'TEXT', ' Gavin offered praise for a rival''s excellent performance in the competition, yet quietly reviewed footage of Gavin''s own performance late into the night, searching for flaws. Question: What does this behaviour most strongly suggest about Gavin''s underlying feelings?', NULL, '["Complete satisfaction with {n}''s own performance","Total indifference to the competition''s result","A competitive drive and self-doubt hidden behind gracious public praise","Genuine belief that the rival''s performance was poor"]', 'C) A competitive drive and self-doubt hidden behind gracious public praise', NULL, 'HARD', 1, TRUE, '2026-07-17T08:25:41.854Z', '2026-07-17T08:25:41.854Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8786, 47, 'TEXT', ' Nora smiled politely through the entire family gathering, but excused personal absence unusually early, later admitting to feeling completely overwhelmed by the crowd. Question: Which best describes Nora''s true feelings during the gathering?', NULL, '["Anger towards specific family members","Complete indifference to being around family","Genuine enjoyment of the crowded gathering","Social discomfort hidden behind a polite, composed exterior"]', 'D) Social discomfort hidden behind a polite, composed exterior', NULL, 'HARD', 1, TRUE, '2026-07-17T08:25:42.009Z', '2026-07-17T08:25:42.009Z') ON CONFLICT DO NOTHING;
