INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8789, 47, 'TEXT', ' Hector smiled and thanked everyone for the leaving gift, then quietly kept it wrapped in a drawer rather than displaying it like the other presents. Question: What might keeping the gift wrapped most likely suggest about Hector''s feelings?', NULL, '["Excitement about giving the gift away again","Dislike of the specific gift chosen","Complete indifference to the gift","A complicated mix of gratitude and sadness about the leaving itself"]', 'D) A complicated mix of gratitude and sadness about the leaving itself', NULL, 'HARD', 1, TRUE, '2026-07-17T08:25:42.522Z', '2026-07-17T08:25:42.522Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8790, 47, 'TEXT', ' Bianca agreed the new schedule change was "totally fine," but began arriving fifteen minutes early every single day, far earlier than had ever been necessary before. Question: What does arriving early every day most strongly suggest about Bianca''s true feelings toward the change?', NULL, '["An underlying anxiety about adjusting to the new schedule","Total indifference to arrival times","Complete comfort requiring no extra preparation","Excitement about the earlier start"]', 'A) An underlying anxiety about adjusting to the new schedule', NULL, 'HARD', 1, TRUE, '2026-07-17T08:25:42.677Z', '2026-07-17T08:25:42.677Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8791, 47, 'TEXT', ' Maya volunteered to give the closing speech at the ceremony, insisting there was nothing to be nervous about, while quietly asking a friend to stand at the very front of the room. Question: What does asking the friend to stand at the front most likely suggest?', NULL, '["A dislike of public speaking that had already been openly admitted","Complete confidence requiring no support at all","A hidden need for reassurance despite the confident words spoken","Indifference to who attended the ceremony"]', 'C) A hidden need for reassurance despite the confident words spoken', NULL, 'HARD', 1, TRUE, '2026-07-17T08:25:42.834Z', '2026-07-17T08:25:42.834Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8792, 47, 'TEXT', ' Tom practised the difficult conversation about ending the friendship for days, yet when the moment finally came, spoke only about the weather and school work instead. Question: What does this most strongly suggest about Tom''s feelings in that moment?', NULL, '["Complete confidence in raising the difficult topic","A fear of confrontation that overpowered the earlier intention to be honest","Excitement about avoiding the subject forever","Total indifference to the friendship''s future"]', 'B) A fear of confrontation that overpowered the earlier intention to be honest', NULL, 'HARD', 1, TRUE, '2026-07-17T08:25:42.987Z', '2026-07-17T08:25:42.987Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8793, 47, 'TEXT', ' Sara laughed when a classmate mispronounced Sara''s name in front of everyone, but corrected it quietly and firmly the moment the classmate approached alone later. Question: What does this contrast in behaviour most strongly suggest?', NULL, '["Genuine amusement at the mispronunciation itself","A wish to never have the name corrected","Complete indifference to how the name was said","A discomfort with public correction, despite caring about the mistake being fixed"]', 'D) A discomfort with public correction, despite caring about the mistake being fixed', NULL, 'HARD', 1, TRUE, '2026-07-17T08:25:43.141Z', '2026-07-17T08:25:43.141Z') ON CONFLICT DO NOTHING;
