INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8795, 47, 'TEXT', ' Grace agreed to let a younger sibling choose the family film every week "to be kind," but always suggested watching it a second time alone later that night. Question: What does watching the film again alone most likely suggest about Grace''s true feelings?', NULL, '["A genuine enjoyment of the films chosen, beyond simply being kind","Complete dislike of the sibling''s choices","Total indifference to the films themselves","Boredom with watching films in general"]', 'A) A genuine enjoyment of the films chosen, beyond simply being kind', NULL, 'HARD', 1, TRUE, '2026-07-17T08:25:43.451Z', '2026-07-17T08:25:43.451Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8796, 47, 'TEXT', ' Ethan spent the afternoon helping a rival team fix a broken piece of equipment before an important match against them. Question: Which best explains Ethan''s likely motivation, despite the upcoming competition?', NULL, '["A sense of sportsmanship that outweighs the desire to win at any cost","Complete indifference to fair play","A hope that the rival team would forget the favour","A secret wish for the rival team to lose"]', 'A) A sense of sportsmanship that outweighs the desire to win at any cost', NULL, 'HARD', 1, TRUE, '2026-07-17T08:25:43.607Z', '2026-07-17T08:25:43.607Z') ON CONFLICT DO NOTHING;
