INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8798, 47, 'TEXT', ' Lily spoke confidently about not being bothered by the unkind rumour spreading at school, yet avoided the group of classmates most likely responsible for an entire week. Question: What does Lily''s avoidance most strongly suggest?', NULL, '["Excitement about the attention received","Anger unrelated to the rumour","Complete indifference to the rumour","The rumour affected {n} more deeply than was openly admitted"]', 'D) The rumour affected {n} more deeply than was openly admitted', NULL, 'HARD', 1, TRUE, '2026-07-17T08:25:43.913Z', '2026-07-17T08:25:43.913Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8799, 47, 'TEXT', ' Jack calmly accepted the news of not being selected for the orchestra, then avoided walking past the music room for the following two weeks. Question: What does avoiding the music room most strongly suggest about Jack''s true feelings?', NULL, '["A general dislike of music that had always existed","A lingering disappointment that the calm acceptance did not fully reveal","Complete indifference to the orchestra","Relief at no longer needing to attend rehearsals"]', 'B) A lingering disappointment that the calm acceptance did not fully reveal', NULL, 'HARD', 1, TRUE, '2026-07-17T08:25:44.067Z', '2026-07-17T08:25:44.067Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8819, 48, 'TEXT', ' James always wears a helmet when cycling. He also wears bright clothing and has lights on his bike, even during the day. What can you conclude about James?', NULL, '["He is a reckless cyclist.","He doesn''t have a bike.","He is a careful cyclist.","He doesn''t like cycling."]', 'C) He is a careful cyclist.', NULL, 'EASY', 1, TRUE, '2026-07-17T08:44:17.642Z', '2026-07-17T08:44:17.642Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8800, 47, 'TEXT', ' Mia insisted on carrying the heaviest box during the house move, even after clearly straining a shoulder, refusing every offer of help from family members. Question: What does this behaviour most strongly suggest about Mia''s underlying motivation?', NULL, '["Enjoyment of physical pain","Complete indifference to the move","A genuine belief that no one else could help","A wish to prove capability, possibly masking insecurity about being seen as weak"]', 'D) A wish to prove capability, possibly masking insecurity about being seen as weak', NULL, 'HARD', 1, TRUE, '2026-07-17T08:25:44.221Z', '2026-07-17T08:25:44.221Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8801, 47, 'TEXT', ' Ravi offered to help organise the charity event, but each time a leadership decision needed to be made, quietly deferred to someone else in the group. Question: What does this pattern most likely suggest about Ravi''s feelings?', NULL, '["Complete disinterest in the charity event","A willingness to contribute paired with a lack of confidence in taking charge","Resentment towards the rest of the group","A strong desire to control every decision"]', 'B) A willingness to contribute paired with a lack of confidence in taking charge', NULL, 'HARD', 1, TRUE, '2026-07-17T08:25:44.523Z', '2026-07-17T08:25:44.523Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8802, 48, 'TEXT', ' Every afternoon, Daniel completed his homework before playing outside. He also packed his school bag the night before and arrived at school early every morning. What can you conclude about Daniel?', NULL, '["He dislikes school.","He is organised.","He is lazy.","He is irresponsible."]', 'B) He is organised.', NULL, 'EASY', 1, TRUE, '2026-07-17T08:44:14.946Z', '2026-07-17T08:44:14.946Z') ON CONFLICT DO NOTHING;
