INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8995, 48, 'TEXT', ' The software developer''s app has been downloaded 100 million times. It has become essential for people''s daily tasks. What can you conclude about the developer?', NULL, '["His app is irrelevant.","He is not a developer.","His app is not downloaded.","He has created a highly successful app."]', 'D) He has created a highly successful app.', NULL, 'HARD', 1, TRUE, '2026-07-17T08:44:45.905Z', '2026-07-17T08:44:45.905Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8996, 48, 'TEXT', ' The environmental group has protected 2 million acres of land from development. They continue to expand their conservation work. What can you conclude about the environmental group?', NULL, '["It only focuses on urban areas.","It is dedicated to protecting natural spaces.","It does not protect land.","It has no projects."]', 'B) It is dedicated to protecting natural spaces.', NULL, 'HARD', 1, TRUE, '2026-07-17T08:44:46.060Z', '2026-07-17T08:44:46.060Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8997, 48, 'TEXT', ' The chef has received three Michelin stars for her restaurant. Diners travel from around the world to eat her food. What can you conclude about the chef?', NULL, '["She is an amateur cook.","She only cooks for herself.","Her food is not well-received.","She is a world-class chef."]', 'D) She is a world-class chef.', NULL, 'HARD', 1, TRUE, '2026-07-17T08:44:46.214Z', '2026-07-17T08:44:46.214Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8998, 48, 'TEXT', ' The peace agreement has ended a 20-year conflict. Thousands of refugees are now returning to their homes. What can you conclude about the peace agreement?', NULL, '["It has not helped anyone.","Conflict has continued.","Refugees are not returning.","It has brought positive change to the region."]', 'D) It has brought positive change to the region.', NULL, 'HARD', 1, TRUE, '2026-07-17T08:44:46.370Z', '2026-07-17T08:44:46.370Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (8999, 48, 'TEXT', ' The dancer has performed on stages across the world. She has been praised for her technique and emotional expression. What can you conclude about the dancer?', NULL, '["She is not well-known.","She rarely performs.","She is a beginner.","She is an internationally acclaimed dancer."]', 'D) She is an internationally acclaimed dancer.', NULL, 'HARD', 1, TRUE, '2026-07-17T08:44:46.527Z', '2026-07-17T08:44:46.527Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9000, 48, 'TEXT', ' The company''s efforts to reduce plastic waste have been rewarded. They are now considered a leader in sustainability. What can you conclude about the company?', NULL, '["It creates more waste.","It is not recognised.","It is a leader in environmental responsibility.","It doesn''t care about sustainability."]', 'C) It is a leader in environmental responsibility.', NULL, 'HARD', 1, TRUE, '2026-07-17T08:44:46.683Z', '2026-07-17T08:44:46.683Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9001, 48, 'TEXT', ' The architect''s building has been named one of the most innovative of the decade. It has won multiple international awards. What can you conclude about the architect?', NULL, '["She is not well-known.","She is an award-winning innovative architect.","Her building is poorly designed.","She has not won awards."]', 'B) She is an award-winning innovative architect.', NULL, 'HARD', 1, TRUE, '2026-07-17T08:44:46.841Z', '2026-07-17T08:44:46.841Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9002, 49, 'TEXT', ' The new library is open from 9 am to 6 pm every day. It has over 10,000 books. Visitors can borrow up to five books at a time. The library also has computers and a quiet reading area. Question: What is the author''s purpose?', NULL, '["To entertain readers with a story","To inform readers about the library''s facilities","To describe a fictional place","To persuade people to visit the library"]', 'B) To inform readers about the library''s facilities', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:13.397Z', '2026-07-17T09:56:13.397Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9003, 49, 'TEXT', ' The sun was shining brightly. Birds were singing in the trees. Children were laughing and playing in the park. It was a perfect summer day. Question: What is the mood of this passage?', NULL, '["Angry","Frightening","Gloomy","Peaceful and joyful"]', 'D) Peaceful and joyful', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:13.609Z', '2026-07-17T09:56:13.609Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9004, 49, 'TEXT', ' Every Saturday, our local football team plays at the stadium. The matches start at 3 pm. Tickets cost £10 for adults and £5 for children. Come and support your local team! Question: What is the author''s purpose?', NULL, '["To entertain with a football story","To describe the stadium","To persuade people to come to the matches","To inform about ticket prices"]', 'C) To persuade people to come to the matches', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:13.767Z', '2026-07-17T09:56:13.767Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9005, 49, 'TEXT', ' The old house stood on the hill. Its windows were broken, and the paint was peeling. The wind howled through the cracks. Something moved in the shadows. Question: What is the tone of this passage?', NULL, '["Romantic","Mysterious and eerie","Cheerful","Humorous"]', 'B) Mysterious and eerie', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:13.929Z', '2026-07-17T09:56:13.929Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9006, 49, 'TEXT', ' Recycling is very important for our planet. Every year, millions of tonnes of plastic end up in the ocean. Please remember to recycle your bottles and paper. Together, we can make a difference! Question: What is the author''s purpose?', NULL, '["To persuade readers to recycle","To entertain with a story about recycling","To describe a recycling plant","To inform about recycling"]', 'A) To persuade readers to recycle', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:14.089Z', '2026-07-17T09:56:14.089Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9007, 49, 'TEXT', ' The puppy wagged its tail and jumped up and down. It licked the girl''s face and barked happily. The girl laughed and gave the puppy a big hug. Question: What is the tone of this passage?', NULL, '["Angry","Frightening","Joyful and playful","Sad"]', 'C) Joyful and playful', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:14.247Z', '2026-07-17T09:56:14.247Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9008, 49, 'TEXT', ' Exercise is good for your health. It helps you stay fit and strong. Doctors recommend at least 30 minutes of exercise every day. Walking, running, and swimming are all excellent forms of exercise. Question: What is the author''s purpose?', NULL, '["To describe a sports event","To tell a story about exercise","To persuade people to exercise","To inform about the benefits of exercise"]', 'D) To inform about the benefits of exercise', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:14.425Z', '2026-07-17T09:56:14.425Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9009, 49, 'TEXT', ' The night was dark and silent. The only sound was the dripping of water from the ceiling. She walked slowly down the corridor, her heart pounding. Suddenly, she heard footsteps behind her. Question: What is the mood of this passage?', NULL, '["Peaceful","Joyful","Romantic","Scary and tense"]', 'D) Scary and tense', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:14.628Z', '2026-07-17T09:56:14.628Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9010, 49, 'TEXT', ' Our school is hosting a bake sale on Friday. We need volunteers to help bake cakes and cookies. All money raised will go to charity. Please sign up at the office if you can help! Question: What is the author''s purpose?', NULL, '["To inform about the bake sale","To persuade readers to volunteer","To entertain with a story about baking","To describe the school"]', 'B) To persuade readers to volunteer', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:14.786Z', '2026-07-17T09:56:14.786Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9011, 49, 'TEXT', ' The beach was beautiful. The water was crystal clear, and the sand was white and soft. Palm trees swayed in the gentle breeze. It was paradise. Question: What is the tone of this passage?', NULL, '["Sad","Frightening","Boring","Enthusiastic and admiring"]', 'D) Enthusiastic and admiring', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:14.944Z', '2026-07-17T09:56:14.944Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9012, 49, 'TEXT', ' The supermarket on Oak Street is open 24 hours a day. It sells groceries, household items, and fresh produce. Customers can use the self-checkout machines for faster service. Question: What is the author''s purpose?', NULL, '["To entertain with a shopping story","To inform about the supermarket''s services","To describe a specific product","To persuade people to shop there"]', 'B) To inform about the supermarket''s services', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:15.103Z', '2026-07-17T09:56:15.103Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9013, 49, 'TEXT', ' The little girl had lost her favourite teddy bear. Tears streamed down her face. She searched everywhere but couldn''t find it. Her heart felt heavy and sad. Question: What is the mood of this passage?', NULL, '["Funny","Sad and upsetting","Exciting","Happy"]', 'B) Sad and upsetting', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:15.259Z', '2026-07-17T09:56:15.259Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9014, 49, 'TEXT', ' Visit Sunny Beach Resort for the holiday of a lifetime! Enjoy our luxurious rooms, delicious food, and beautiful views. Book now to get a special discount! Question: What is the author''s purpose?', NULL, '["To describe the beach","To persuade people to book a holiday","To inform about Sunny Beach Resort","To tell a story about a holiday"]', 'B) To persuade people to book a holiday', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:15.415Z', '2026-07-17T09:56:15.415Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9015, 49, 'TEXT', ' The old man sat quietly on the bench, feeding the pigeons. He smiled gently as they gathered around him. He had been coming to this park for 50 years. Question: What is the tone of this passage?', NULL, '["Peaceful and nostalgic","Exciting","Frightening","Angry"]', 'A) Peaceful and nostalgic', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:15.572Z', '2026-07-17T09:56:15.572Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9016, 49, 'TEXT', ' The planet Mars is the fourth planet from the Sun. It has two moons and a thin atmosphere. The temperature on Mars can drop to -60 degrees Celsius. Question: What is the author''s purpose?', NULL, '["To entertain with a story about Mars","To persuade people to visit Mars","To describe life on Mars","To inform about the planet Mars"]', 'D) To inform about the planet Mars', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:15.728Z', '2026-07-17T09:56:15.728Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9017, 49, 'TEXT', ' The thunder crashed loudly. Lightning lit up the dark sky. The wind howled like a wild animal. The trees bent and swayed dangerously. Question: What is the mood of this passage?', NULL, '["Romantic","Calm and peaceful","Happy and cheerful","Frightening and intense"]', 'D) Frightening and intense', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:15.884Z', '2026-07-17T09:56:15.884Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9018, 49, 'TEXT', ' Don''t miss our end-of-season sale! Up to 50% off on all items. Hurry, stocks are limited! Come and visit our store today! Question: What is the author''s purpose?', NULL, '["To entertain with a shopping story","To describe the store","To persuade people to buy items","To inform about the sale"]', 'C) To persuade people to buy items', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:16.041Z', '2026-07-17T09:56:16.041Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9019, 49, 'TEXT', ' The sun rose over the mountains. The sky turned shades of pink and orange. The birds began to sing, greeting the new day. Everything was quiet and still. Question: What is the tone of this passage?', NULL, '["Serene and peaceful","Humorous","Chaotic","Frightening"]', 'A) Serene and peaceful', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:16.198Z', '2026-07-17T09:56:16.198Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9020, 49, 'TEXT', ' The history museum has exhibits from ancient Egypt, Rome, and Greece. Visitors can see mummies, pottery, and ancient weapons. The museum is open daily from 10 am to 5 pm. Question: What is the author''s purpose?', NULL, '["To describe ancient artefacts","To entertain with a story about history","To inform about the museum''s exhibits","To persuade people to visit the museum"]', 'C) To inform about the museum''s exhibits', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:16.354Z', '2026-07-17T09:56:16.354Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9021, 49, 'TEXT', ' The baby started to cry loudly. Her face turned red, and she kicked her little legs. Nothing seemed to calm her down. The mother looked worried. Question: What is the mood of this passage?', NULL, '["Peaceful","Playful","Frustrated and anxious","Joyful"]', 'C) Frustrated and anxious', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:16.512Z', '2026-07-17T09:56:16.512Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9022, 49, 'TEXT', ' Try our new healthy smoothie! Made with fresh fruits and vegetables, it''s packed with vitamins and minerals. Start your day the healthy way. Order yours now! Question: What is the author''s purpose?', NULL, '["To inform about smoothies","To entertain with a story","To describe the ingredients","To persuade people to buy the smoothie"]', 'D) To persuade people to buy the smoothie', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:16.671Z', '2026-07-17T09:56:16.671Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9023, 49, 'TEXT', ' The classroom was silent. All the students were looking at the test paper. Some were biting their nails. Others were frowning at the questions. It was a difficult exam. Question: What is the tone of this passage?', NULL, '["Cheerful","Humorous","Serious and tense","Carefree"]', 'C) Serious and tense', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:16.827Z', '2026-07-17T09:56:16.827Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9024, 49, 'TEXT', ' Water is essential for life. Humans need to drink about 2 litres of water every day. Water helps our bodies function properly and keeps us hydrated. Question: What is the author''s purpose?', NULL, '["To tell a story about water","To describe a river","To inform about the importance of water","To persuade people to drink more water"]', 'C) To inform about the importance of water', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:16.984Z', '2026-07-17T09:56:16.984Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9025, 49, 'TEXT', ' The room was filled with the smell of freshly baked bread. The fireplace crackled warmly. She curled up in the armchair with a cup of tea and a good book. Question: What is the mood of this passage?', NULL, '["Cosy and comfortable","Exciting","Cold and lonely","Stressful"]', 'A) Cosy and comfortable', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:17.142Z', '2026-07-17T09:56:17.142Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9026, 49, 'TEXT', ' Join our gym today and get the first month free! We have the best equipment and experienced trainers. Don''t delay - your new fitness journey starts now! Question: What is the author''s purpose?', NULL, '["To entertain with a fitness story","To inform about gym equipment","To persuade people to join the gym","To describe the trainers"]', 'C) To persuade people to join the gym', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:17.299Z', '2026-07-17T09:56:17.299Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9027, 49, 'TEXT', ' The little boy climbed the tree carefully. He reached for the highest branch. His mother watched from below, worried he might fall. Finally, he made it to the top. Question: What is the tone of this passage?', NULL, '["Suspenseful and anxious","Sad","Boring","Happy"]', 'A) Suspenseful and anxious', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:17.455Z', '2026-07-17T09:56:17.455Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9028, 49, 'TEXT', ' Ladybirds are small insects with bright red wings and black spots. They are helpful for gardens because they eat aphids. They are found all over the world. Question: What is the author''s purpose?', NULL, '["To describe a garden","To entertain with a story about ladybirds","To inform about ladybirds","To persuade people to like ladybirds"]', 'C) To inform about ladybirds', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:17.613Z', '2026-07-17T09:56:17.613Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9029, 49, 'TEXT', ' The festival was full of colours, music, and laughter. People were dancing in the streets. Children were eating candy floss and riding the Ferris wheel. It was pure joy. Question: What is the mood of this passage?', NULL, '["Exciting and joyful","Boring","Sad and gloomy","Frightening"]', 'A) Exciting and joyful', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:17.770Z', '2026-07-17T09:56:17.770Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9030, 49, 'TEXT', ' Have you ever wondered what it would be like to fly? Our flight simulator gives you the real experience! Visit us and feel what it''s like to be a pilot. Question: What is the author''s purpose?', NULL, '["To describe a plane","To persuade people to try the flight simulator","To inform about flying","To tell a story about a pilot"]', 'B) To persuade people to try the flight simulator', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:17.928Z', '2026-07-17T09:56:17.928Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9031, 49, 'TEXT', ' The mother held her baby close. Tears of joy streamed down her face. After months of waiting, she finally held her baby in her arms. It was the happiest moment of her life. Question: What is the tone of this passage?', NULL, '["Angry","Heartwarming and emotional","Frightening","Humorous"]', 'B) Heartwarming and emotional', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:18.084Z', '2026-07-17T09:56:18.084Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9032, 49, 'TEXT', ' Earth is the third planet from the Sun. It is the only known planet to support life. It has one moon and a magnetic field that protects it from solar radiation. Question: What is the author''s purpose?', NULL, '["To inform about the planet Earth","To persuade people to protect Earth","To describe life on Earth","To entertain with a story about Earth"]', 'A) To inform about the planet Earth', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:18.241Z', '2026-07-17T09:56:18.241Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9033, 49, 'TEXT', ' The forest was dark and quiet. The trees were tall and shadowy. A thick fog crept between the trunks. It was easy to get lost here. Question: What is the mood of this passage?', NULL, '["Warm and inviting","Peaceful","Bright and cheerful","Mysterious and eerie"]', 'D) Mysterious and eerie', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:18.397Z', '2026-07-17T09:56:18.397Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9034, 49, 'TEXT', ' Buy one, get one free! This is a limited-time offer. Don''t miss out on this amazing deal. Visit our website now and place your order! Question: What is the author''s purpose?', NULL, '["To inform about a product","To entertain with a story","To persuade people to buy a product","To describe the product"]', 'C) To persuade people to buy a product', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:18.554Z', '2026-07-17T09:56:18.554Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9035, 49, 'TEXT', ' The children were building a sandcastle on the beach. They used buckets and spades to make towers and walls. The waves came and washed it away. They laughed and started again. Question: What is the tone of this passage?', NULL, '["Playful and carefree","Frightening","Serious","Sad"]', 'A) Playful and carefree', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:18.712Z', '2026-07-17T09:56:18.712Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9036, 49, 'TEXT', ' The human skeleton has 206 bones. The skull protects the brain. The rib cage protects the heart and lungs. Bones also help us move and support our body. Question: What is the author''s purpose?', NULL, '["To inform about the human skeleton","To entertain with a story","To persuade people to exercise","To describe a hospital"]', 'A) To inform about the human skeleton', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:18.870Z', '2026-07-17T09:56:18.870Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9037, 49, 'TEXT', ' The dog wagged its tail and barked excitedly as the family returned home. It jumped up and down with joy. Everyone was happy to see each other. Question: What is the mood of this passage?', NULL, '["Joyful and heartwarming","Tense","Frightening","Sorrowful"]', 'A) Joyful and heartwarming', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:19.033Z', '2026-07-17T09:56:19.033Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9038, 49, 'TEXT', ' Support your local farmers! Buy fresh, organic produce from our market. It tastes better and is healthier for you. Visit us every Saturday morning! Question: What is the author''s purpose?', NULL, '["To persuade people to buy from the market","To inform about farming","To tell a story about farmers","To describe vegetables"]', 'A) To persuade people to buy from the market', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:19.190Z', '2026-07-17T09:56:19.190Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9039, 49, 'TEXT', ' The storm raged outside. The windows rattled violently, and the rain lashed against the glass. Inside, they huddled together, hoping it would soon pass. Question: What is the tone of this passage?', NULL, '["Calm and peaceful","Joyful","Intense and fearful","Romantic"]', 'C) Intense and fearful', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:19.347Z', '2026-07-17T09:56:19.347Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9040, 49, 'TEXT', ' Australia is both a country and a continent. It is the sixth-largest country in the world. Its capital city is Canberra. Australia is known for its unique wildlife. Question: What is the author''s purpose?', NULL, '["To entertain with a story about Australia","To persuade people to visit Australia","To describe a specific Australian animal","To inform about Australia"]', 'D) To inform about Australia', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:19.508Z', '2026-07-17T09:56:19.508Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9041, 49, 'TEXT', ' The grandmother hugged her grandson tightly. "I''ve missed you so much," she whispered. He smiled and said, "I missed you too, Grandma." It was a beautiful reunion. Question: What is the mood of this passage?', NULL, '["Exciting","Tense","Heartwarming and emotional","Sad"]', 'C) Heartwarming and emotional', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:19.665Z', '2026-07-17T09:56:19.665Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9042, 49, 'TEXT', ' Don''t wait any longer! Enrol in our course today and learn a new skill! We offer classes in everything from cooking to coding. Your future self will thank you! Question: What is the author''s purpose?', NULL, '["To describe the teachers","To persuade people to enrol","To inform about the courses","To entertain with a story"]', 'B) To persuade people to enrol', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:19.822Z', '2026-07-17T09:56:19.822Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9043, 49, 'TEXT', ' The carnival was loud and colourful. There were rides, games, and food stalls everywhere. Everyone was laughing and having a wonderful time. It was the best day ever. Question: What is the mood of this passage?', NULL, '["Exciting and joyful","Tense","Gloomy","Frightening"]', 'A) Exciting and joyful', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:19.979Z', '2026-07-17T09:56:19.979Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9044, 49, 'TEXT', ' The Sun is about 4.6 billion years old. It is a yellow dwarf star. It is about 150 million kilometres away from Earth. It provides light and heat to our planet. Question: What is the author''s purpose?', NULL, '["To describe the solar system","To entertain with a story about space","To inform about the Sun","To persuade people to protect the Sun"]', 'C) To inform about the Sun', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:20.137Z', '2026-07-17T09:56:20.137Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9045, 49, 'TEXT', ' The young man took a deep breath and got down on one knee. "Will you marry me?" he asked, holding up a small ring box. She smiled and said, "Yes!" Question: What is the tone of this passage?', NULL, '["Humorous","Angry","Frightening","Romantic and hopeful"]', 'D) Romantic and hopeful', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:20.293Z', '2026-07-17T09:56:20.293Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9046, 49, 'TEXT', ' Drink more water! It''s the easiest way to improve your health. Water helps your skin, digestion, and energy levels. Carry a water bottle with you everywhere! Question: What is the author''s purpose?', NULL, '["To persuade people to drink more water","To inform about the benefits of water","To describe different types of drinks","To entertain with a story about water"]', 'A) To persuade people to drink more water', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:20.451Z', '2026-07-17T09:56:20.451Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9047, 49, 'TEXT', ' The old dog lay on the rug, breathing slowly. His eyes were closed. The children sat beside him, stroking his fur. They knew it wouldn''t be long now. Question: What is the mood of this passage?', NULL, '["Sad and emotional","Exciting","Joyful","Playful"]', 'A) Sad and emotional', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:20.607Z', '2026-07-17T09:56:20.607Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9048, 49, 'TEXT', ' Insects are the most diverse group of animals on Earth. There are over one million known species. They live in almost every environment, from deserts to rainforests. Question: What is the author''s purpose?', NULL, '["To describe a specific insect","To entertain with a story about insects","To inform about insects","To persuade people to protect insects"]', 'C) To inform about insects', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:20.767Z', '2026-07-17T09:56:20.767Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9049, 49, 'TEXT', ' The explorer stood on the top of the mountain. He looked down at the world below. It was the most beautiful sight he had ever seen. He had finally reached his goal. Question: What is the tone of this passage?', NULL, '["Triumphant and proud","Frightening","Sad","Boring"]', 'A) Triumphant and proud', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:20.923Z', '2026-07-17T09:56:20.923Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9050, 49, 'TEXT', ' Book your holiday now and save 20%! Our packages include flights, hotel, and meals. Don''t miss this opportunity. Offer ends soon, so act fast! Question: What is the author''s purpose?', NULL, '["To describe a hotel","To inform about holidays","To persuade people to book a holiday","To entertain with a travel story"]', 'C) To persuade people to book a holiday', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:21.080Z', '2026-07-17T09:56:21.080Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9051, 49, 'TEXT', ' The children ran through the field, their laughter echoing in the air. The sun was warm on their faces. They felt free and happy, without a care in the world. Question: What is the mood of this passage?', NULL, '["Carefree and joyful","Tense","Frightening","Gloomy"]', 'A) Carefree and joyful', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:21.238Z', '2026-07-17T09:56:21.238Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9052, 49, 'TEXT', ' Photosynthesis is the process by which plants make food. They use sunlight, water, and carbon dioxide. This process releases oxygen into the air. Question: What is the author''s purpose?', NULL, '["To describe a garden","To entertain with a story about plants","To inform about photosynthesis","To persuade people to plant trees"]', 'C) To inform about photosynthesis', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:21.394Z', '2026-07-17T09:56:21.394Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9053, 49, 'TEXT', ' The mother sang softly to her baby. The baby''s eyes grew heavy, and soon she was sleeping peacefully. It was a quiet, special moment between them. Question: What is the tone of this passage?', NULL, '["Gentle and tender","Sad","Exciting","Tense"]', 'A) Gentle and tender', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:21.550Z', '2026-07-17T09:56:21.550Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9054, 49, 'TEXT', ' Try our new range of skincare products! They are made from natural ingredients and are gentle on your skin. Feel beautiful and confident. Order today! Question: What is the author''s purpose?', NULL, '["To inform about skincare","To describe the ingredients","To entertain with a beauty story","To persuade people to buy skincare products"]', 'D) To persuade people to buy skincare products', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:21.706Z', '2026-07-17T09:56:21.706Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9055, 49, 'TEXT', ' The school bell rang loudly. Students rushed out of the classroom, eager to start the holidays. Backpacks were packed, and smiles were everywhere. Finally, summer had arrived! Question: What is the mood of this passage?', NULL, '["Sad","Tense","Frightening","Excited and joyful"]', 'D) Excited and joyful', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:21.864Z', '2026-07-17T09:56:21.864Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9056, 49, 'TEXT', ' There are 195 countries in the world today. The largest country is Russia. The smallest is Vatican City. Each country has its own culture and traditions. Question: What is the author''s purpose?', NULL, '["To describe a specific country","To persuade people to travel","To inform about countries","To entertain with a story about countries"]', 'C) To inform about countries', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:22.021Z', '2026-07-17T09:56:22.021Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9057, 49, 'TEXT', ' The firefighter ran into the burning building. Smoke filled the air. He searched for anyone trapped inside. He was determined to save them, no matter what. Question: What is the tone of this passage?', NULL, '["Calm","Humorous","Brave and determined","Sad"]', 'C) Brave and determined', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:22.177Z', '2026-07-17T09:56:22.177Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9058, 49, 'TEXT', ' Eat more fruits and vegetables! They are full of vitamins and minerals. A balanced diet helps you stay healthy and strong. Start eating better today! Question: What is the author''s purpose?', NULL, '["To inform about nutrition","To persuade people to eat more fruits and vegetables","To entertain with a story about food","To describe a fruit market"]', 'B) To persuade people to eat more fruits and vegetables', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:22.335Z', '2026-07-17T09:56:22.335Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9059, 49, 'TEXT', ' The moon was full and bright in the night sky. The stars twinkled like diamonds. The world was silent and peaceful. It was a perfect night for a walk. Question: What is the mood of this passage?', NULL, '["Romantic and peaceful","Frightening","Chaotic","Tense"]', 'A) Romantic and peaceful', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:22.491Z', '2026-07-17T09:56:22.491Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9060, 49, 'TEXT', ' The Great Wall of China is the longest wall in the world. It was built over 2,000 years ago. It was designed to protect China from invasions. Question: What is the author''s purpose?', NULL, '["To inform about the Great Wall","To describe Chinese culture","To entertain with a story about China","To persuade people to visit the Great Wall"]', 'A) To inform about the Great Wall', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:22.648Z', '2026-07-17T09:56:22.648Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9061, 49, 'TEXT', ' The soldier returned home after years away. His family was waiting for him at the airport. When he saw them, his eyes filled with tears of joy. Question: What is the tone of this passage?', NULL, '["Boring","Angry","Frightening","Emotional and happy"]', 'D) Emotional and happy', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:22.805Z', '2026-07-17T09:56:22.805Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9062, 49, 'TEXT', ' Give the gift of music this Christmas! Our pianos are the perfect gift for anyone who loves music. Visit our showroom and find the perfect piano today! Question: What is the author''s purpose?', NULL, '["To persuade people to buy a piano","To entertain with a music story","To describe a musical performance","To inform about pianos"]', 'A) To persuade people to buy a piano', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:22.963Z', '2026-07-17T09:56:22.963Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9063, 49, 'TEXT', ' The waves crashed against the rocks. The wind howled fiercely. The sailors struggled to keep the boat steady. They had never seen a storm like this before. Question: What is the mood of this passage?', NULL, '["Romantic","Joyful","Peaceful","Intense and dangerous"]', 'D) Intense and dangerous', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:23.121Z', '2026-07-17T09:56:23.121Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9064, 49, 'TEXT', ' The Sahara Desert covers most of North Africa. It is the largest hot desert in the world. Temperatures can reach over 50 degrees Celsius during the day. Question: What is the author''s purpose?', NULL, '["To entertain with a story about the desert","To describe a desert animal","To persuade people to visit the desert","To inform about the Sahara Desert"]', 'D) To inform about the Sahara Desert', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:23.280Z', '2026-07-17T09:56:23.280Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9065, 49, 'TEXT', ' The little girl smiled at her father. "I love you, Daddy," she said. He picked her up and gave her a big hug. He felt so lucky to be her father. Question: What is the tone of this passage?', NULL, '["Tense","Heartwarming and loving","Exciting","Sad"]', 'B) Heartwarming and loving', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:23.439Z', '2026-07-17T09:56:23.439Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9066, 49, 'TEXT', ' Learn a new language today! Our courses are fun, easy, and affordable. Speaking another language opens up a world of opportunities. Enrol now! Question: What is the author''s purpose?', NULL, '["To describe different languages","To inform about language learning","To entertain with a story about languages","To persuade people to enrol in language courses"]', 'D) To persuade people to enrol in language courses', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:23.596Z', '2026-07-17T09:56:23.596Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9067, 49, 'TEXT', ' The cat stretched lazily in the sun. It yawned and closed its eyes. The birds chirped outside, but the cat was too comfortable to move. Life was good. Question: What is the mood of this passage?', NULL, '["Frightening","Relaxed and peaceful","Busy","Exciting"]', 'B) Relaxed and peaceful', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:23.753Z', '2026-07-17T09:56:23.753Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9068, 49, 'TEXT', ' Coffee is a popular drink made from roasted coffee beans. It contains caffeine, which helps people feel more awake. Coffee is grown in many tropical countries. Question: What is the author''s purpose?', NULL, '["To entertain with a story about coffee","To inform about coffee","To persuade people to drink coffee","To describe a café"]', 'B) To inform about coffee', NULL, 'EASY', 1, TRUE, '2026-07-17T09:56:23.914Z', '2026-07-17T09:56:23.914Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9069, 49, 'TEXT', ' Despite years of neglect, the old cathedral still stood tall. Its crumbling stones held secrets of centuries past. The stained glass windows, though faded, still cast colourful patterns on the stone floor, reminding visitors of the faith and hope that once filled the space. Question: What is the tone of this passage?', NULL, '["Humorous and light-hearted","Sombre and reflective","Exciting and adventurous","Cheerful and optimistic"]', 'B) Sombre and reflective', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:24.072Z', '2026-07-17T09:56:24.072Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9070, 49, 'TEXT', ' The annual science fair has been a tradition at our school for over 20 years. Students from all grades participate, presenting projects on topics from renewable energy to genetics. The winners receive trophies and certificates, and their projects are displayed in the main hall for the rest of the year. Question: What is the author''s purpose?', NULL, '["To persuade students to participate","To describe a specific science project","To inform about the school''s science fair","To entertain with a science story"]', 'C) To inform about the school''s science fair', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:24.230Z', '2026-07-17T09:56:24.230Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9071, 49, 'TEXT', ' As the first notes of the music filled the air, the dancers began to move. Their bodies swayed and turned, telling a story without words. The audience watched in awe, completely captivated by the performance unfolding before them. Question: What is the mood of this passage?', NULL, '["Tense","Boring","Mesmerising and enchanting","Frightening"]', 'C) Mesmerising and enchanting', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:24.523Z', '2026-07-17T09:56:24.523Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9072, 49, 'TEXT', ' Have you ever considered the benefits of meditation? It reduces stress, improves focus, and promotes emotional well-being. Just ten minutes a day can make a difference. Why not give it a try? Question: What is the author''s purpose?', NULL, '["To entertain with a meditation story","To persuade people to try meditation","To describe a meditation class","To inform about meditation techniques"]', 'B) To persuade people to try meditation', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:24.681Z', '2026-07-17T09:56:24.681Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9073, 49, 'TEXT', ' His voice trembled as he spoke the words he had been dreading. He couldn''t look his father in the eye, knowing the disappointment that would follow. The silence that hung between them was suffocating. Question: What is the tone of this passage?', NULL, '["Tense and remorseful","Romantic","Cheerful","Playful"]', 'A) Tense and remorseful', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:24.838Z', '2026-07-17T09:56:24.838Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9074, 49, 'TEXT', ' The Great Barrier Reef is the world''s largest coral reef system, stretching over 2,300 kilometres. It is home to thousands of species of marine life, including fish, turtles, and sharks. The reef is a popular destination for divers and snorkelers. Question: What is the author''s purpose?', NULL, '["To inform about the Great Barrier Reef","To describe a specific marine animal","To persuade people to visit the Great Barrier Reef","To entertain with a story about the reef"]', 'A) To inform about the Great Barrier Reef', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:24.995Z', '2026-07-17T09:56:24.995Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9075, 49, 'TEXT', ' The children burst into laughter as the clown slipped on a banana peel. He tumbled and rolled, his oversized shoes flopping in the air. The audience clapped and cheered, delighted by the silly show. Question: What is the mood of this passage?', NULL, '["Frightening","Serious","Tense","Humorous and joyful"]', 'D) Humorous and joyful', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:25.151Z', '2026-07-17T09:56:25.151Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9076, 49, 'TEXT', ' Did you know that over 70% of your immune system is in your gut? That''s why it''s so important to eat a healthy diet full of fibre and probiotics. Your health depends on it! Question: What is the author''s purpose?', NULL, '["To describe digestive system","To inform about the immune system","To persuade people to eat a healthy diet","To entertain with a health story"]', 'C) To persuade people to eat a healthy diet', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:25.308Z', '2026-07-17T09:56:25.308Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9077, 49, 'TEXT', ' The museum was eerily quiet. Paintings of long-dead monarchs stared down from the walls. As she walked through the empty halls, she couldn''t shake the feeling that she was being watched. Question: What is the tone of this passage?', NULL, '["Exciting","Romantic","Eerie and unsettling","Cheerful"]', 'C) Eerie and unsettling', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:25.466Z', '2026-07-17T09:56:25.466Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9078, 49, 'TEXT', ' The technology company announced its latest smartphone model. The phone features a 6.5-inch screen, a 48-megapixel camera, and a battery that lasts up to 48 hours. It will be available in stores next month. Question: What is the author''s purpose?', NULL, '["To inform about the new smartphone","To describe the company''s history","To entertain with a technology story","To persuade people to buy the phone"]', 'A) To inform about the new smartphone', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:25.622Z', '2026-07-17T09:56:25.622Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9079, 49, 'TEXT', ' She looked at her reflection in the mirror and smiled. The dress fit perfectly. She twirled around, and the skirt floated like a dancer''s. Tonight would be the best night of her life. Question: What is the mood of this passage?', NULL, '["Excited and hopeful","Tense","Frightening","Gloomy"]', 'A) Excited and hopeful', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:25.779Z', '2026-07-17T09:56:25.779Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9080, 49, 'TEXT', ' Imagine a world without plastic waste. Our oceans would be cleaner, and marine life would thrive. By reducing our plastic use, we can make this vision a reality. Join us in the fight against plastic pollution! Question: What is the author''s purpose?', NULL, '["To inform about plastic pollution","To entertain with an ocean story","To persuade people to reduce plastic use","To describe marine life"]', 'C) To persuade people to reduce plastic use', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:25.936Z', '2026-07-17T09:56:25.936Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9081, 49, 'TEXT', ' The detective examined the crime scene carefully. Something didn''t add up. He studied the footprints, the broken window, and the missing painting. There was a clue he was missing. Question: What is the tone of this passage?', NULL, '["Humorous","Calm and peaceful","Romantic","Analytical and suspenseful"]', 'D) Analytical and suspenseful', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:26.093Z', '2026-07-17T09:56:26.093Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9082, 49, 'TEXT', ' Hurricanes are powerful tropical storms that form over warm ocean waters. They have wind speeds of over 120 kilometres per hour and can cause significant damage to coastal areas. The Atlantic hurricane season runs from June to November. Question: What is the author''s purpose?', NULL, '["To inform about hurricanes","To persuade people to evacuate during storms","To describe a specific hurricane","To entertain with a storm story"]', 'A) To inform about hurricanes', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:26.249Z', '2026-07-17T09:56:26.249Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9083, 49, 'TEXT', ' The team had lost their fifth game in a row. The locker room was silent, the air thick with disappointment. No one spoke. The dream of winning the championship was slipping away. Question: What is the mood of this passage?', NULL, '["Joyful","Exciting","Disheartened and defeated","Peaceful"]', 'C) Disheartened and defeated', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:26.408Z', '2026-07-17T09:56:26.408Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9084, 49, 'TEXT', ' You deserve a break! Treat yourself to a weekend getaway at our spa resort. Relax in our hot tubs, enjoy gourmet meals, and forget your worries. Book your escape today! Question: What is the author''s purpose?', NULL, '["To inform about the resort","To describe the spa facilities","To persuade people to book a spa weekend","To entertain with a relaxation story"]', 'C) To persuade people to book a spa weekend', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:26.567Z', '2026-07-17T09:56:26.567Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9085, 49, 'TEXT', ' The old man''s hands trembled as he held the photograph. A single tear rolled down his wrinkled cheek. In the picture was the woman he had loved and lost 50 years ago. Question: What is the tone of this passage?', NULL, '["Exciting","Humorous","Cheerful","Melancholic and nostalgic"]', 'D) Melancholic and nostalgic', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:26.723Z', '2026-07-17T09:56:26.723Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9086, 49, 'TEXT', ' The Tour de France is the world''s most famous bicycle race. It covers over 3,500 kilometres across France and nearby countries. The race is held every July and attracts cyclists from around the world. Question: What is the author''s purpose?', NULL, '["To describe a specific cyclist","To inform about the Tour de France","To persuade people to watch the race","To entertain with a cycling story"]', 'B) To inform about the Tour de France', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:26.880Z', '2026-07-17T09:56:26.880Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9087, 49, 'TEXT', ' The balloons drifted up into the sky like colourful clouds. People stared in wonder, their faces turned upward. It was a sea of red, blue, and yellow against the clear blue sky. Question: What is the mood of this passage?', NULL, '["Joyful and colourful","Tense","Dark and gloomy","Frightening"]', 'A) Joyful and colourful', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:27.067Z', '2026-07-17T09:56:27.067Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9088, 49, 'TEXT', ' Did you know that adopting a pet can improve your mental health? Pets provide companionship, reduce stress, and encourage exercise. Consider visiting your local animal shelter today! Question: What is the author''s purpose?', NULL, '["To persuade people to adopt a pet","To inform about pet adoption","To entertain with a pet story","To describe different animals"]', 'A) To persuade people to adopt a pet', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:27.324Z', '2026-07-17T09:56:27.324Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9089, 49, 'TEXT', ' The king sat upon his throne, his eyes scanning the crowd. His subjects bowed their heads in deference. He was a just ruler, but his word was law, and everyone knew it. Question: What is the tone of this passage?', NULL, '["Authoritative and formal","Romantic","Playful","Humorous"]', 'A) Authoritative and formal', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:27.530Z', '2026-07-17T09:56:27.530Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9090, 49, 'TEXT', ' The Mona Lisa is one of the most famous paintings in the world. It was painted by Leonardo da Vinci in the 16th century. The painting is displayed in the Louvre Museum in Paris and attracts millions of visitors every year. Question: What is the author''s purpose?', NULL, '["To describe the Louvre Museum","To inform about the Mona Lisa","To persuade people to visit the Louvre","To entertain with an art story"]', 'B) To inform about the Mona Lisa', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:27.727Z', '2026-07-17T09:56:27.727Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9091, 49, 'TEXT', ' The waves were calm, and the sea was like glass. The sky was painted in shades of pink and orange as the sun set. They sailed on, united, as the world seemed to fall asleep. Question: What is the mood of this passage?', NULL, '["Frightening","Chaotic","Tense","Peaceful and romantic"]', 'D) Peaceful and romantic', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:27.882Z', '2026-07-17T09:56:27.882Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9092, 49, 'TEXT', ' Are you tired of feeling tired? Our energy supplements are the answer! Made with natural ingredients, they boost your energy without the crash. Try them today and feel the difference! Question: What is the author''s purpose?', NULL, '["To describe the ingredients","To inform about energy supplements","To entertain with a story","To persuade people to buy the product"]', 'D) To persuade people to buy the product', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:28.089Z', '2026-07-17T09:56:28.089Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9093, 49, 'TEXT', ' The general looked out at his troops, his face unreadable. He knew many would not survive the battle ahead. He said a silent prayer, hoping he was leading them to victory. Question: What is the tone of this passage?', NULL, '["Humorous","Joyful","Serious and sombre","Carefree"]', 'C) Serious and sombre', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:28.245Z', '2026-07-17T09:56:28.245Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9094, 49, 'TEXT', ' The Amazon River is the second-longest river in the world, flowing through Brazil, Peru, and several other countries. It contains the largest volume of freshwater of any river and is home to thousands of species of fish and plants. Question: What is the author''s purpose?', NULL, '["To describe the animals of the Amazon","To entertain with an Amazon story","To persuade people to visit the Amazon","To inform about the Amazon River"]', 'D) To inform about the Amazon River', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:28.402Z', '2026-07-17T09:56:28.402Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9095, 49, 'TEXT', ' The park was alive with the sounds of laughter and music. Couples danced, children played, and friends shared food on the grass. It was a celebration of life itself. Question: What is the mood of this passage?', NULL, '["Gloomy","Tense","Frightening","Vibrant and joyful"]', 'D) Vibrant and joyful', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:28.558Z', '2026-07-17T09:56:28.558Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9096, 49, 'TEXT', ' Don''t let another day pass without taking control of your finances! Our financial planning service can help you save for the future, reduce debt, and build wealth. Start your journey today! Question: What is the author''s purpose?', NULL, '["To inform about financial planning","To describe investment strategies","To entertain with a finance story","To persuade people to use the service"]', 'D) To persuade people to use the service', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:28.715Z', '2026-07-17T09:56:28.715Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9097, 49, 'TEXT', ' The poet sat in silence, watching the raindrops trace paths down the window. His heart was heavy, and he found himself reaching for the old notebook. "Hello, old friend," he said. Question: What is the tone of this passage?', NULL, '["Exciting","Playful","Melancholic and introspective","Joyful"]', 'C) Melancholic and introspective', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:28.873Z', '2026-07-17T09:56:28.873Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9098, 49, 'TEXT', ' The Underground Railroad was a network of secret routes and safe houses used by enslaved African Americans to escape to free states and Canada in the 19th century. It was one of the most significant acts of resistance in American history. Question: What is the author''s purpose?', NULL, '["To inform about the Underground Railroad","To describe a specific escape","To entertain with a historical story","To persuade readers to learn about history"]', 'A) To inform about the Underground Railroad', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:29.029Z', '2026-07-17T09:56:29.029Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9099, 49, 'TEXT', ' The flames danced in the fireplace, casting shadows across the room. The children sat in a circle, their eyes wide with excitement. "Tell us a story," they whispered. Question: What is the mood of this passage?', NULL, '["Cosy and magical","Sad","Tense","Scary"]', 'A) Cosy and magical', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:29.186Z', '2026-07-17T09:56:29.186Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9100, 49, 'TEXT', ' Imagine waking up to the sound of waves crashing on the shore. You open your eyes to a stunning ocean view. That''s what you can expect at our oceanfront resort. Book your dream vacation now! Question: What is the author''s purpose?', NULL, '["To describe a specific room","To persuade people to book a vacation","To inform about the resort","To entertain with a story"]', 'B) To persuade people to book a vacation', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:29.344Z', '2026-07-17T09:56:29.344Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9101, 49, 'TEXT', ' The soldier clutched the letter tightly, his hands shaking. It was the last letter from his brother. He read it through blurred eyes, the words "I love you" burning into his soul. Question: What is the tone of this passage?', NULL, '["Exciting","Intensely emotional and heartbreaking","Humorous","Cheerful"]', 'B) Intensely emotional and heartbreaking', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:29.503Z', '2026-07-17T09:56:29.503Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9214, 50, 'TEXT', 'Which sentence contains a simile?', NULL, '["He fought like a lion.","The car stopped at the red light.","The children laughed loudly.","She brushed her hair."]', 'A) He fought like a lion.', NULL, 'EASY', 1, TRUE, '2026-07-17T10:16:38.337Z', '2026-07-17T10:16:38.337Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9102, 49, 'TEXT', ' The world''s population is expected to reach 9 billion by 2050. This rapid growth presents challenges for food production, housing, and healthcare. Governments are working to address these issues. Question: What is the author''s purpose?', NULL, '["To describe overpopulation in cities","To entertain with a future story","To persuade people to have fewer children","To inform about population growth"]', 'D) To inform about population growth', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:29.659Z', '2026-07-17T09:56:29.659Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9103, 49, 'TEXT', ' The first cherry blossoms appeared on the trees, a sign that spring had finally arrived. Families gathered in the park for hanami, admiring the delicate pink petals. It was a moment of pure happiness. Question: What is the mood of this passage?', NULL, '["Beautiful and celebratory","Gloomy","Tense","Frightening"]', 'A) Beautiful and celebratory', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:29.821Z', '2026-07-17T09:56:29.821Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9104, 49, 'TEXT', ' You owe it to yourself to be happy. Our self-help program is designed to help you achieve your goals and find fulfilment. Don''t wait another moment to change your life! Question: What is the author''s purpose?', NULL, '["To persuade people to enrol","To inform about the program","To describe the benefits of happiness","To entertain with a success story"]', 'A) To persuade people to enrol', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:29.978Z', '2026-07-17T09:56:29.978Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9105, 49, 'TEXT', ' The city was in ruins. Buildings had crumbled. Fire still smouldered on the streets. The survivors walked through the rubble, searching for something that had been lost. Question: What is the tone of this passage?', NULL, '["Joyful","Hopeful","Exciting","Desolate and sombre"]', 'D) Desolate and sombre', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:30.134Z', '2026-07-17T09:56:30.134Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9106, 49, 'TEXT', ' Yoga has been practised for over 5,000 years in India. It combines physical postures, breathing techniques, and meditation. Modern science has confirmed its many health benefits, including stress relief and improved flexibility. Question: What is the author''s purpose?', NULL, '["To entertain with a yoga story","To describe a yoga pose","To inform about yoga","To persuade people to practise yoga"]', 'C) To inform about yoga', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:30.290Z', '2026-07-17T09:56:30.290Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9107, 49, 'TEXT', ' The girl skipped through the meadow, her red dress like a flag against the green grass. She twirled and laughed, her joy infectious. The world seemed to smile with her. Question: What is the mood of this passage?', NULL, '["Frightening","Gloomy","Bright and carefree","Tense"]', 'C) Bright and carefree', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:30.447Z', '2026-07-17T09:56:30.447Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9108, 49, 'TEXT', ' Tired of boring weekends? Our adventure weekend includes hiking, rock climbing, and zip-lining. It''s the perfect way to challenge yourself and make new friends. Sign up now! Question: What is the author''s purpose?', NULL, '["To describe the location","To persuade people to sign up","To inform about the activities","To entertain with an adventure story"]', 'B) To persuade people to sign up', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:30.604Z', '2026-07-17T09:56:30.604Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9109, 49, 'TEXT', ' The clock ticked loudly in the silence. She stared at the phone, willing it to ring. Each passing minute felt like an eternity. Where was he? What had happened? Question: What is the tone of this passage?', NULL, '["Joyful","Peaceful","Anxious and suspenseful","Humorous"]', 'C) Anxious and suspenseful', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:30.763Z', '2026-07-17T09:56:30.763Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9110, 49, 'TEXT', ' The Magna Carta, signed in 1215, is one of the most important documents in history. It established the principle that everyone, including the king, was subject to the law. It influenced the development of constitutional law. Question: What is the author''s purpose?', NULL, '["To describe a specific king","To entertain with a historical story","To inform about the Magna Carta","To persuade readers to learn about history"]', 'C) To inform about the Magna Carta', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:30.919Z', '2026-07-17T09:56:30.919Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9111, 49, 'TEXT', ' The crowd erupted in cheers as the hero walked onto the stage. He was bruised and battered, but he was victorious. This was the moment they had all been waiting for. Question: What is the mood of this passage?', NULL, '["Triumphant and celebratory","Frightening","Tense","Sad"]', 'A) Triumphant and celebratory', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:31.075Z', '2026-07-17T09:56:31.075Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9112, 49, 'TEXT', ' Read more books! Reading improves vocabulary, concentration, and empathy. It transports you to new worlds and helps you understand others. Pick up a book today and experience the magic! Question: What is the author''s purpose?', NULL, '["To describe a specific book","To persuade people to read more","To inform about the benefits of reading","To entertain with a reading story"]', 'B) To persuade people to read more', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:31.232Z', '2026-07-17T09:56:31.232Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9113, 49, 'TEXT', ' The professor stared at the blackboard, his mind racing. The equation was almost solved. Just one more variable, and he would have his answer. This was what he lived for. Question: What is the tone of this passage?', NULL, '["Exciting and intellectual","Humorous","Sad","Cheerful"]', 'A) Exciting and intellectual', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:31.390Z', '2026-07-17T09:56:31.390Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9114, 49, 'TEXT', ' The Taj Mahal was built in the 17th century by Emperor Shah Jahan in memory of his wife. It is made of white marble and is one of the most famous buildings in the world. Question: What is the author''s purpose?', NULL, '["To entertain with a love story","To persuade people to visit the Taj Mahal","To inform about the Taj Mahal","To describe Indian architecture"]', 'C) To inform about the Taj Mahal', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:31.547Z', '2026-07-17T09:56:31.547Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9115, 49, 'TEXT', ' The little boy clutched his mother''s hand tightly. The bright lights and loud noises of the fair overwhelmed him. But when he saw the carousel, his face broke into a smile. Question: What is the mood of this passage?', NULL, '["Overwhelming then joyful","Sad","Tense","Frightening"]', 'A) Overwhelming then joyful', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:31.703Z', '2026-07-17T09:56:31.703Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9116, 49, 'TEXT', ' Imagine having access to the world''s best doctors without leaving your home. Our telemedicine service connects you with specialists instantly. Experience the future of healthcare now! Question: What is the author''s purpose?', NULL, '["To entertain with a technology story","To describe a doctor","To persuade people to use the service","To inform about telemedicine"]', 'C) To persuade people to use the service', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:31.860Z', '2026-07-17T09:56:31.860Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9117, 49, 'TEXT', ' The actor stood in the spotlight, his heart pounding. The audience was silent, waiting. He took a breath and began to speak, his voice steady and clear. The magic was about to begin. Question: What is the tone of this passage?', NULL, '["Cheerful","Sad","Tense and expectant","Frightening"]', 'C) Tense and expectant', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:32.016Z', '2026-07-17T09:56:32.016Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9118, 49, 'TEXT', ' The Solar System consists of the Sun and everything that orbits it, including planets, moons, asteroids, and comets. It formed about 4.6 billion years ago from a giant cloud of gas and dust. Question: What is the author''s purpose?', NULL, '["To describe a specific planet","To persuade people to study space","To entertain with a space story","To inform about the Solar System"]', 'D) To inform about the Solar System', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:32.172Z', '2026-07-17T09:56:32.172Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9170, 49, 'TEXT', ' The lighthouse stood alone on the cliff, its beam cutting through the darkness. The sea raged below, but the light was a beacon of hope. It had saved countless lives. Question: What is the mood of this passage?', NULL, '["Frightening","Hopeful and steadfast","Tense","Gloomy"]', 'B) Hopeful and steadfast', NULL, 'HARD', 1, TRUE, '2026-07-17T09:56:40.530Z', '2026-07-17T09:56:40.530Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9119, 49, 'TEXT', ' The sun was setting, casting golden light across the valley. Wildflowers swayed in the gentle breeze. In the distance, a deer emerged from the trees, watching them with curious eyes. Question: What is the mood of this passage?', NULL, '["Beautiful and serene","Exciting","Tense","Frightening"]', 'A) Beautiful and serene', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:32.330Z', '2026-07-17T09:56:32.330Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9120, 49, 'TEXT', ' Your health is your most valuable asset. Our health screening service can detect problems early, when they''re most treatable. Regular check-ups save lives. Book yours today! Question: What is the author''s purpose?', NULL, '["To describe medical equipment","To entertain with a health story","To persuade people to get health checks","To inform about health screening"]', 'C) To persuade people to get health checks', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:32.487Z', '2026-07-17T09:56:32.487Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9121, 49, 'TEXT', ' The doctor walked into the room, a grave expression on his face. He didn''t need to say a word. She knew from his eyes that the news was not good. Her heart sank. Question: What is the tone of this passage?', NULL, '["Humorous","Exciting","Cheerful","Sombre and heartbreaking"]', 'D) Sombre and heartbreaking', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:32.644Z', '2026-07-17T09:56:32.644Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9122, 49, 'TEXT', ' The Great Wall of China stretches over 13,000 miles. It was built over several centuries by different Chinese dynasties. It is one of the most popular tourist destinations in the world. Question: What is the author''s purpose?', NULL, '["To inform about the Great Wall of China","To persuade people to visit the wall","To describe Chinese history","To entertain with a Chinese story"]', 'A) To inform about the Great Wall of China', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:32.803Z', '2026-07-17T09:56:32.803Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9123, 49, 'TEXT', ' The children''s laughter filled the air like music. The rain had finally stopped, and the puddles glistened in the sun. It was the best day ever. Question: What is the mood of this passage?', NULL, '["Gloomy","Tense","Frightening","Joyful and carefree"]', 'D) Joyful and carefree', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:32.961Z', '2026-07-17T09:56:32.961Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9124, 49, 'TEXT', ' Tired of slow internet? Our high-speed fibre internet is the fastest in the country, with download speeds of up to 1,000 Mbps. Say goodbye to buffering forever. Call us today! Question: What is the author''s purpose?', NULL, '["To persuade people to switch providers","To inform about internet speeds","To entertain with a technology story","To describe fibre optics"]', 'A) To persuade people to switch providers', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:33.120Z', '2026-07-17T09:56:33.120Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9125, 49, 'TEXT', ' The abandoned warehouse was dark and cold. Cobwebs hung in every corner. The silence was broken only by the drip of water. He had to find what he was looking for before it was too late. Question: What is the tone of this passage?', NULL, '["Creepy and suspenseful","Romantic","Peaceful","Joyful"]', 'A) Creepy and suspenseful', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:33.280Z', '2026-07-17T09:56:33.280Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9126, 49, 'TEXT', ' The Pulitzer Prize is an award for excellence in journalism, literature, and music. It was established in 1917 by Joseph Pulitzer. Winners are announced every spring. Question: What is the author''s purpose?', NULL, '["To inform about the Pulitzer Prize","To entertain with a Pulitzer story","To persuade people to read Pulitzer-winning works","To describe a Pulitzer-winning author"]', 'A) To inform about the Pulitzer Prize', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:33.439Z', '2026-07-17T09:56:33.439Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9127, 49, 'TEXT', ' The bride walked down the aisle, her dress flowing like a cloud. Everyone was watching, their eyes filled with tears. At the altar, the groom was waiting, his smile wide. Question: What is the mood of this passage?', NULL, '["Frightening","Gloomy","Tense","Romantic and heartwarming"]', 'D) Romantic and heartwarming', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:33.598Z', '2026-07-17T09:56:33.598Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9128, 49, 'TEXT', ' You don''t have to be a professional to enjoy photography. Anyone can capture beautiful moments with a camera. Start your photography journey today with our beginner-friendly course! Question: What is the author''s purpose?', NULL, '["To describe a camera","To inform about photography","To persuade people to take the course","To entertain with a photography story"]', 'C) To persuade people to take the course', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:33.758Z', '2026-07-17T09:56:33.758Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9129, 49, 'TEXT', ' The wind howled like a pack of wolves. The trees bent and groaned under its force. She clutched her coat tightly, her face stinging from the cold. Question: What is the tone of this passage?', NULL, '["Peaceful","Joyful","Calm","Harsh and intense"]', 'D) Harsh and intense', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:33.921Z', '2026-07-17T09:56:33.921Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9130, 49, 'TEXT', ' The human body contains about 60% water. It needs water to regulate temperature, transport nutrients, and remove waste. Without water, humans can survive only a few days. Question: What is the author''s purpose?', NULL, '["To persuade people to drink more water","To inform about the body''s need for water","To entertain with a body story","To describe dehydration"]', 'B) To inform about the body''s need for water', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:34.082Z', '2026-07-17T09:56:34.082Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9131, 49, 'TEXT', ' The mountain was majestic, its peak covered in snow. The river below sparkled like a ribbon of silver. It was a view that made everything else fade away. Question: What is the mood of this passage?', NULL, '["Tense","Gloomy","Majestic and awe-inspiring","Frightening"]', 'C) Majestic and awe-inspiring', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:34.241Z', '2026-07-17T09:56:34.241Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9132, 49, 'TEXT', ' Looking for a new career? Our employment agency can help you find the perfect job. We have connections with top companies across every industry. Let us help you succeed! Question: What is the author''s purpose?', NULL, '["To inform about employment","To persuade people to use the agency","To entertain with a career story","To describe job interviews"]', 'B) To persuade people to use the agency', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:34.522Z', '2026-07-17T09:56:34.522Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9133, 49, 'TEXT', ' The old man spoke of the war with a distant look in his eyes. He had seen things no one should see. The memories haunted him still, but he was proud of what he had done. Question: What is the tone of this passage?', NULL, '["Exciting","Haunting and reflective","Humorous","Cheerful"]', 'B) Haunting and reflective', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:34.680Z', '2026-07-17T09:56:34.680Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9134, 49, 'TEXT', ' Mount Everest is the tallest mountain in the world, standing at 8,848.86 metres. It is located in the Himalayas, on the border between Nepal and China. The first successful ascent was made in 1953 by Sir Edmund Hillary and Tenzing Norgay. Question: What is the author''s purpose?', NULL, '["To persuade people to climb Everest","To describe a climbing expedition","To inform about Mount Everest","To entertain with an Everest story"]', 'C) To inform about Mount Everest', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:34.840Z', '2026-07-17T09:56:34.840Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9135, 49, 'TEXT', ' The flower petals fluttered down like confetti. The air was sweet with the scent of cherry blossoms. It was spring, and the world was reborn. Question: What is the mood of this passage?', NULL, '["Frightening","Gentle and uplifting","Tense","Gloomy"]', 'B) Gentle and uplifting', NULL, 'MEDIUM', 1, TRUE, '2026-07-17T09:56:35.001Z', '2026-07-17T09:56:35.001Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9136, 49, 'TEXT', ' The photograph had faded with time. She ran her fingers over the image of her grandmother, a woman she had never met. In her hand was a letter that had been written 80 years ago. She could barely read the words, but the emotion was clear. Question: What is the tone of this passage?', NULL, '["Cheerful","Deeply nostalgic and poignant","Humorous","Exciting"]', 'B) Deeply nostalgic and poignant', NULL, 'HARD', 1, TRUE, '2026-07-17T09:56:35.157Z', '2026-07-17T09:56:35.157Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9137, 49, 'TEXT', ' The company''s latest financial report revealed a 75% increase in profits. This was largely attributed to the successful launch of their new product line, which had exceeded all expectations. Share prices rose dramatically on the news. Question: What is the author''s purpose?', NULL, '["To inform about the company''s financial success","To persuade people to buy shares","To entertain with a business story","To describe the new product"]', 'A) To inform about the company''s financial success', NULL, 'HARD', 1, TRUE, '2026-07-17T09:56:35.313Z', '2026-07-17T09:56:35.313Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9138, 49, 'TEXT', ' The fog swallowed the city whole. Streetlights flickered like distant stars. Cars crawled along, their headlights barely penetrating the white curtain. The world seemed to have disappeared. Question: What is the mood of this passage?', NULL, '["Eerie and disorienting","Clear and bright","Joyful","Romantic"]', 'A) Eerie and disorienting', NULL, 'HARD', 1, TRUE, '2026-07-17T09:56:35.478Z', '2026-07-17T09:56:35.478Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9139, 49, 'TEXT', ' Think of the possibility of starting a business. Now think of all the reasons you haven''t done it. We can help you overcome every obstacle and turn your dream into reality. Apply for our mentorship program! Question: What is the author''s purpose?', NULL, '["To describe the challenges of business","To persuade people to join the program","To inform about starting a business","To entertain with a success story"]', 'B) To persuade people to join the program', NULL, 'HARD', 1, TRUE, '2026-07-17T09:56:35.639Z', '2026-07-17T09:56:35.639Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9140, 49, 'TEXT', ' The poet stood at the edge of the cliff, looking out at the sea. The waves crashed below, a reminder of the power of nature. In his hands, he clutched the papers that held his final words. It was time to let go of everything. Question: What is the tone of this passage?', NULL, '["Melancholic and dramatic","Humorous","Joyful","Peaceful"]', 'A) Melancholic and dramatic', NULL, 'HARD', 1, TRUE, '2026-07-17T09:56:35.798Z', '2026-07-17T09:56:35.798Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9141, 49, 'TEXT', ' The Wright brothers made the first successful powered flight in 1903. Their aircraft, the Flyer, flew for 12 seconds and covered 120 feet. This event marked the beginning of the aviation era. Question: What is the author''s purpose?', NULL, '["To describe the Wright brothers","To persuade people to study aviation","To entertain with a flying story","To inform about the first flight"]', 'D) To inform about the first flight', NULL, 'HARD', 1, TRUE, '2026-07-17T09:56:35.960Z', '2026-07-17T09:56:35.960Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9142, 49, 'TEXT', ' The cherry trees were in full bloom, their branches heavy with pink flowers. The path beneath them was carpeted with petals, like a soft pink cloud. It was a moment of perfect beauty. Question: What is the mood of this passage?', NULL, '["Gloomy","Delicate and beautiful","Tense","Frightening"]', 'B) Delicate and beautiful', NULL, 'HARD', 1, TRUE, '2026-07-17T09:56:36.119Z', '2026-07-17T09:56:36.119Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9143, 49, 'TEXT', ' Experience the thrill of flying without ever leaving the ground! Our new flight simulator offers the most realistic virtual reality experience available. Book your session today and take to the skies! Question: What is the author''s purpose?', NULL, '["To describe the technology","To persuade people to book a session","To entertain with a VR story","To inform about flight simulators"]', 'B) To persuade people to book a session', NULL, 'HARD', 1, TRUE, '2026-07-17T09:56:36.277Z', '2026-07-17T09:56:36.277Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9144, 49, 'TEXT', ' The old cathedral had survived wars, fires, and centuries of neglect. Its walls held the prayers of millions. As the bells tolled, the priest felt the weight of history on his shoulders. Question: What is the tone of this passage?', NULL, '["Cheerful","Reverent and historical","Humorous","Exciting"]', 'B) Reverent and historical', NULL, 'HARD', 1, TRUE, '2026-07-17T09:56:36.435Z', '2026-07-17T09:56:36.435Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9145, 49, 'TEXT', ' The Treaty of Versailles was signed in 1919, officially ending World War I. It imposed heavy reparations on Germany and redrew the map of Europe. Many historians believe it contributed to the outbreak of World War II. Question: What is the author''s purpose?', NULL, '["To persuade readers to study history","To describe World War I","To entertain with a historical story","To inform about the Treaty of Versailles"]', 'D) To inform about the Treaty of Versailles', NULL, 'HARD', 1, TRUE, '2026-07-17T09:56:36.592Z', '2026-07-17T09:56:36.592Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9146, 49, 'TEXT', ' The snow fell softly, covering the town in a blanket of white. Children built snowmen, their cheeks rosy from the cold. It was the first snowfall of winter, and it was perfect. Question: What is the mood of this passage?', NULL, '["Tense","Gloomy","Frightening","Calm and happy"]', 'D) Calm and happy', NULL, 'HARD', 1, TRUE, '2026-07-17T09:56:36.750Z', '2026-07-17T09:56:36.750Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9147, 49, 'TEXT', ' Stop dreaming and start achieving! Our life coaching program is designed to turn your goals into reality. We''ve helped thousands of people transform their lives. Your journey begins now! Question: What is the author''s purpose?', NULL, '["To persuade people to join the program","To inform about life coaching","To entertain with a transformation story","To describe the coaching process"]', 'A) To persuade people to join the program', NULL, 'HARD', 1, TRUE, '2026-07-17T09:56:36.909Z', '2026-07-17T09:56:36.909Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9148, 49, 'TEXT', ' The painter stood back to admire his work. The canvas was alive with colour and emotion. It was his masterpiece, the culmination of a lifetime of struggle and passion. Question: What is the tone of this passage?', NULL, '["Humorous","Joyful","Triumphant and reflective","Frightening"]', 'C) Triumphant and reflective', NULL, 'HARD', 1, TRUE, '2026-07-17T09:56:37.066Z', '2026-07-17T09:56:37.066Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9149, 49, 'TEXT', ' The migration of monarch butterflies is one of nature''s most amazing phenomena. Each year, millions of monarchs travel up to 3,000 miles from Canada to Mexico. They travel using a combination of environmental cues and an internal compass. Question: What is the author''s purpose?', NULL, '["To describe a specific butterfly","To persuade people to protect monarchs","To entertain with a butterfly story","To inform about monarch butterfly migration"]', 'D) To inform about monarch butterfly migration', NULL, 'HARD', 1, TRUE, '2026-07-17T09:56:37.225Z', '2026-07-17T09:56:37.225Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9150, 49, 'TEXT', ' The library was silent, the air thick with the smell of old paper. Dust motes danced in the sunlight streaming through the window. He had been here for hours, searching for the answer in the ancient texts. Question: What is the mood of this passage?', NULL, '["Tense","Quiet and mysterious","Joyful","Exciting"]', 'B) Quiet and mysterious', NULL, 'HARD', 1, TRUE, '2026-07-17T09:56:37.381Z', '2026-07-17T09:56:37.381Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9151, 49, 'TEXT', ' You could have it all—wealth, happiness, and success. Our financial planning service has helped thousands achieve their dreams. Don''t settle for less. Take control of your financial future today! Question: What is the author''s purpose?', NULL, '["To inform about financial planning","To entertain with a wealth story","To persuade people to use the service","To describe investment strategies"]', 'C) To persuade people to use the service', NULL, 'HARD', 1, TRUE, '2026-07-17T09:56:37.538Z', '2026-07-17T09:56:37.538Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9152, 49, 'TEXT', ' The battlefield was silent now. The cries of the wounded had faded. A single flag stood atop the hill, a symbol of victory and sacrifice. He looked at it and wept. Question: What is the tone of this passage?', NULL, '["Triumphant","Humorous","Exciting","Sombre and reflective"]', 'D) Sombre and reflective', NULL, 'HARD', 1, TRUE, '2026-07-17T09:56:37.696Z', '2026-07-17T09:56:37.696Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9171, 49, 'TEXT', ' You can make a difference. Your voice matters. The future is shaped by people who stand up for what they believe in. Don''t stay silent—take action now and join the movement! Question: What is the author''s purpose?', NULL, '["To inform about the movement","To entertain with a political story","To describe the issues","To persuade people to join"]', 'D) To persuade people to join', NULL, 'HARD', 1, TRUE, '2026-07-17T09:56:40.689Z', '2026-07-17T09:56:40.689Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9153, 49, 'TEXT', ' The Sistine Chapel ceiling was painted by Michelangelo between 1508 and 1512. It depicts scenes from the Book of Genesis, including the famous Creation of Adam. It is considered one of the greatest works of art ever created. Question: What is the author''s purpose?', NULL, '["To describe Michelangelo''s life","To persuade people to visit the Sistine Chapel","To inform about the Sistine Chapel ceiling","To entertain with an art story"]', 'C) To inform about the Sistine Chapel ceiling', NULL, 'HARD', 1, TRUE, '2026-07-17T09:56:37.854Z', '2026-07-17T09:56:37.854Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9154, 49, 'TEXT', ' The waves whispered secrets to the shore. The moon cast a silver path across the water. Two figures stood hand in hand, watching the infinite sea. The moment was timeless. Question: What is the mood of this passage?', NULL, '["Frightening","Peaceful and romantic","Exciting","Tense"]', 'B) Peaceful and romantic', NULL, 'HARD', 1, TRUE, '2026-07-17T09:56:38.012Z', '2026-07-17T09:56:38.012Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9155, 49, 'TEXT', ' Are you ready to take your fitness to the next level? Our personal trainers work with you to achieve your goals, whether it''s weight loss, strength building, or improving endurance. Sign up for a trial session today! Question: What is the author''s purpose?', NULL, '["To entertain with a fitness story","To persuade people to sign up","To describe exercise routines","To inform about personal training"]', 'B) To persuade people to sign up', NULL, 'HARD', 1, TRUE, '2026-07-17T09:56:38.168Z', '2026-07-17T09:56:38.168Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9156, 49, 'TEXT', ' The architect''s eyes swept across the plans. Every line was perfect, every detail thought out. This building would stand for centuries, a testament to her skill and vision. Question: What is the tone of this passage?', NULL, '["Humorous","Frightening","Cheerful","Professional and proud"]', 'D) Professional and proud', NULL, 'HARD', 1, TRUE, '2026-07-17T09:56:38.324Z', '2026-07-17T09:56:38.324Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9157, 49, 'TEXT', ' The Rosetta Stone, discovered in 1799, was the key to deciphering Egyptian hieroglyphs. It contains the same text in three scripts: Greek, Demotic, and Hieroglyphic. Its discovery revolutionised our understanding of ancient Egypt. Question: What is the author''s purpose?', NULL, '["To entertain with a discovery story","To inform about the Rosetta Stone","To describe Egyptian writing","To persuade people to study Egyptology"]', 'B) To inform about the Rosetta Stone', NULL, 'HARD', 1, TRUE, '2026-07-17T09:56:38.481Z', '2026-07-17T09:56:38.481Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9158, 49, 'TEXT', ' The garden was a secret haven, hidden from the world by tall hedges. The flowers bloomed in a riot of colours, and butterflies danced among them. It was a place to forget everything. Question: What is the mood of this passage?', NULL, '["Magical and peaceful","Tense","Frightening","Gloomy"]', 'A) Magical and peaceful', NULL, 'HARD', 1, TRUE, '2026-07-17T09:56:38.638Z', '2026-07-17T09:56:38.638Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9159, 49, 'TEXT', ' Why settle for ordinary when you can have extraordinary? Our luxury travel experiences are designed for those who expect the best. From private jets to five-star hotels, we make your dreams come true. Book now! Question: What is the author''s purpose?', NULL, '["To entertain with a travel story","To inform about luxury travel","To persuade people to book a trip","To describe a destination"]', 'C) To persuade people to book a trip', NULL, 'HARD', 1, TRUE, '2026-07-17T09:56:38.795Z', '2026-07-17T09:56:38.795Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9160, 49, 'TEXT', ' The professor stood in front of the class, her voice trembling with emotion. The truth she was about to reveal would change everything. She had kept it a secret for 20 years. Question: What is the tone of this passage?', NULL, '["Cheerful","Humorous","Tense and dramatic","Peaceful"]', 'C) Tense and dramatic', NULL, 'HARD', 1, TRUE, '2026-07-17T09:56:38.954Z', '2026-07-17T09:56:38.954Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9161, 49, 'TEXT', ' The invention of the printing press by Johannes Gutenberg in the 15th century made books much more affordable. It allowed for the rapid spread of knowledge and contributed to the Renaissance and the Scientific Revolution. Question: What is the author''s purpose?', NULL, '["To describe Gutenberg''s life","To inform about the printing press","To persuade people to read more books","To entertain with a historical story"]', 'B) To inform about the printing press', NULL, 'HARD', 1, TRUE, '2026-07-17T09:56:39.112Z', '2026-07-17T09:56:39.112Z') ON CONFLICT DO NOTHING;
INSERT INTO "english_questions" ("id", "syllabusId", "questionType", "questionText", "questionImage", "options", "correctAnswer", "explanation", "difficulty", "marks", "isActive", "createdAt", "updatedAt") VALUES (9162, 49, 'TEXT', ' The aurora borealis lit up the night sky with curtains of green and purple light. The snow sparkled under the stars. It was a moment of pure wonder. Question: What is the mood of this passage?', NULL, '["Frightening","Tense","Awe-inspiring and magical","Gloomy"]', 'C) Awe-inspiring and magical', NULL, 'HARD', 1, TRUE, '2026-07-17T09:56:39.270Z', '2026-07-17T09:56:39.270Z') ON CONFLICT DO NOTHING;
